window.TRAFIK_BANK = [{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l2","r1","r2","l12"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"1 § första stycket","title":"Vårdslöshet i trafik","rule":"En väsentlig brist i den omsorg som situationen krävde kan ge dagsböter. Regeln omfattar vägtrafikanter, spårvagnsförare och den som kör motordrivet fordon utanför väg.","apply":"Jämför faktisk körning med vad sikt, hastighet och närheten till andra krävde. Vad gör avvikelsen väsentlig?","pitfall":"En kollision visar att något hänt. Utred också hur trafikanten handlade och vad personen kunde uppfatta."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l2","r1","r2"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"1 § andra stycket","title":"Grov vårdslöshet i trafik","rule":"Den som för motordrivet fordon eller spårvagn kan dömas vid grov oaktsamhet eller uppenbar likgiltighet för andra människors liv eller egendom.","apply":"Beskriv medvetet risktagande, riskens omfattning och vilka andra som utsattes. Ange hur uppgifterna styrks.","pitfall":"Personkretsen är snävare än i första stycket. Skadans storlek avgör inte ensam hur brottet rubriceras."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l1","l2"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"2 §","title":"Väsentligt hinder eller störning","rule":"En vägtrafikant eller spårvagnsförare kan straffas för att i onödan och i väsentlig mån hindra eller störa trafiken på väg, om gärningen inte faller under 1 §.","apply":"Ange konkret vem som hindrades, hur länge och om ett godtagbart skäl fanns.","pitfall":"Att någon kör långsamt säger lite utan uppgifter om trafikläget och skälet."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l3","l8","l9","r3"],"sources":["Trafikjuridik 1","RäV 2024:3 – olovlig körning"],"ref":"3 § första stycket, första meningen","title":"Olovlig körning","rule":"Det krävs att en person uppsåtligen för ett körkortspliktigt fordon utan behörighet.","apply":"Bestäm fordonsklass och behörighetskrav. Jämför med vad som gällde för föraren den aktuella dagen och utred vad personen insåg.","pitfall":"Ett saknat körkortskort visar inte i sig att föraren saknar rätt att köra."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l3","r3"],"sources":["Trafikjuridik 1","RäV 2024:3 – olovlig körning"],"ref":"3 § första stycket, andra meningen","title":"Olovlig körning som är grov","rule":"Tidigare återkallat körkort, vanemässighet eller andra kvalificerande omständigheter kan ligga till grund för den strängare bedömningen.","apply":"Bygg en tidslinje med återkallelsebeslut och tidigare körningar. Kontrollera att uppsåtet omfattar den aktuella obehörigheten.","pitfall":"Utred det tidigare beslutets art. Ett omhändertagande och en återkallelse är olika beslut."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l3","l8"],"sources":["Trafikjuridik 1","RäV 2024:3 – olovlig körning"],"ref":"3 § andra stycket","title":"Överträdelse av körkortsvillkor","rule":"Den som uppsåtligen eller av oaktsamhet åsidosätter en föreskrift om sin rätt att föra fordonet kan dömas till böter.","apply":"Läs villkoret på behörigheten, exempelvis krav på synhjälpmedel. Beskriv på vilket sätt körningen stred mot villkoret.","pitfall":"Fel behörighetsklass och brutet villkor kan leda till olika prövningar."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l3","l9"],"sources":["Trafikjuridik 1","RäV 2024:3 – olovlig körning"],"ref":"3 § tredje stycket","title":"Tillåtande av olovlig körning","rule":"Den som uppsåtligen eller av oaktsamhet anlitar eller tillåter en obehörig förare kan själv dömas.","apply":"Utred vem som kunde bestämma över fordonet, vilket tillstånd föraren fick och hur behörigheten kontrollerades.","pitfall":"Släktskap eller registrerat ägande bevisar inte att personen gav tillåtelse."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l3","l9","r4","r5"],"sources":["Trafikjuridik 1","RäV 2024:3 – olovlig körning"],"ref":"3 § fjärde stycket","title":"Traktor, moped II och andra särskilt uppräknade fordon","rule":"Reglerna för förare och tillåtande tillämpas också på traktor, moped klass II, snöskoter, terränghjuling, motorredskap och spårvagn.","apply":"Fastställ verklig fordonsklass, krav på förarbevis eller annan behörighet och eventuella undantag.","pitfall":"En beteckning i en annons eller en äldre registrering kan avvika från fordonets verkliga egenskaper."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l4","l11"],"sources":["Trafikjuridik 2","Övningsuppgifter vecka 3"],"ref":"4 § första stycket","title":"Rattfylleri genom alkoholkoncentration","rule":"Gränsen är minst 0,2 promille i blod eller 0,10 mg/l i utandningsluft under eller efter färden med motordrivet fordon eller spårvagn.","apply":"Ange provtyp, enhet, mätresultat och samband med körningen. Utred tidpunkt för alkoholintaget.","pitfall":"Ett utslag i sållningsprov är inte detsamma som ett kvantitativt bevisprov."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l4","l11"],"sources":["Trafikjuridik 2","Övningsuppgifter vecka 3"],"ref":"4 § andra stycket","title":"Drograttfylleri och ordinationsundantaget","rule":"Efter intag ska ett narkotiskt ämne finnas i blodet under eller efter färden. Intag enligt behörig receptutfärdares ordination undantas från detta stycke.","apply":"Jämför blodanalys och tidsuppgifter med eventuell ordination, dos och faktiskt intag.","pitfall":"Urinprov ensamt visar inte den förekomst i blod som denna regel kräver."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l4","l11"],"sources":["Trafikjuridik 2","Övningsuppgifter vecka 3"],"ref":"4 § tredje stycket","title":"Kliniskt rattfylleri","rule":"Alkohol eller annat medel kan påverka föraren så mycket att betryggande körning inte kan antas. Bestämmelsen kräver ingen viss koncentration.","apply":"Knyt beskrivna symtom och körsätt till tidpunkten för färden och till möjlig påverkan. Utred andra förklaringar.","pitfall":"Även korrekt ordinerad medicin kan vara relevant när körförmågan faktiskt har påverkats."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l4"],"sources":["Trafikjuridik 2","Övningsuppgifter vecka 3"],"ref":"4 § fjärde och femte styckena","title":"Undantag beroende på fordon och ändamål","rule":"För gåendeförda motorfordon undantas första och andra styckena. Ett regerings- eller myndighetstillstånd för en vetenskaplig eller jämförlig undersökning kan omfatta även tredje stycket.","apply":"Kontrollera fordonets avsedda användning eller det faktiska tillståndet och vad det täcker.","pitfall":"Undantaget för gåendeförda fordon omfattar inte regeln om faktisk påverkan i tredje stycket."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l4","r6"],"sources":["Trafikjuridik 2","Övningsuppgifter vecka 3"],"ref":"4 a §","title":"Grovt rattfylleri","rule":"Bedöm körningen som helhet. Minst 1,0 promille i blod eller 0,50 mg/l i utandningsluft, avsevärd påverkan eller påtaglig trafikfara är särskilt viktiga omständigheter.","apply":"Redovisa varje omständighet som finns i fallet, inklusive fordonstyp och hur körningen faktiskt gick till.","pitfall":"Gränsen för alkohol är inte det enda sättet att bedöma ett rattfylleri som grovt."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l5","l12"],"sources":["Trafikjuridik 2","Hantera trafikolycka"],"ref":"5 §","title":"Smitning från trafikolycksplats","rule":"Den som haft del i en olyckas uppkomst kan dömas om personen undandrar sig skäliga åtgärder eller skyldigheten att lämna uppgifter. Även den som saknar skuld till olyckan omfattas.","apply":"Pröva delaktighet, insikt om händelsen, vilka åtgärder som behövdes och vad personen kunde göra. Läs även TrF 2 kap. 8 §.","pitfall":"Utred varför personen gick och hur uppgifterna lämnades. Att lämna platsen för att skaffa hjälp kan vara motiverat."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l5","r7"],"sources":["Trafikjuridik 2","RäV 2023:4 – förverkande"],"ref":"7 §","title":"Förverkande av fordon eller annat hjälpmedel","rule":"Förverkande får ske för att förebygga fortsatta trafikbrott om det inte är uppenbart oskäligt. Vid olovlig körning och rattfylleribrott väger tidigare sådan brottslighet särskilt.","apply":"Utred sambandet med brottet, återfallsrisken, äganderätten, egendomens värde och vilka följder ett förverkande skulle få.","pitfall":"Beslag är ett tillfälligt beslut. Förverkande kräver en egen prövning. Tredje stycket gäller även avsedda hjälpmedel vid fullbordat brott."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l5"],"sources":["Trafikjuridik 2","RäV 2023:4 – förverkande"],"ref":"8 §","title":"Förtida försäljning eller förstöring","rule":"Undersökningsledare eller åklagare kan besluta om detta för beslagtaget fordon under en femtedel av prisbasbeloppet vid beslaget, när förverkande enligt 7 § skäligen kan antas.","apply":"Ange värdering, rätt års prisbasbelopp och underrättelsedag. Verkställighet får ske tidigast tre veckor efter att underrättelsen sänts.","pitfall":"En begäran om rättens prövning av beslaget hindrar verkställighet tills tingsrätten prövat beslaget."},{"law":"TBL","name":"Lag (1951:649) om straff för vissa trafikbrott","url":"https://data.riksdagen.se/dokument/sfs-1951-649.html","units":["l5"],"sources":["Trafikjuridik 2","RäV 2023:4 – förverkande"],"ref":"9–10 §§","title":"Ägarens ersättning och domstolsprövning","rule":"Om fordonet sålts eller förstörts men inte förverkas kan ägaren ansöka om ersättning hos Polismyndigheten. Tingsrätten kan pröva ersättningsbeslutet.","apply":"Skilj köpeskillingen vid försäljning från skäligt belopp vid förstöring. Begär rättens prövning inom en månad från delgivning av ersättningsbeslutet.","pitfall":"Fristen för rättens prövning av ersättningen är en annan än väntetiden för att sälja fordonet."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 1–3 §§","title":"Vad ett godkännande innebär","rule":"Polisens ordningsbot föreläggs den misstänkte för godkännande. Ett godkänt föreläggande får samma verkan som en lagakraftvunnen dom.","apply":"Förklara gärningen, beloppet och rättsverkan före underskrift. Skilj polisens ordningsbot från åklagarens strafföreläggande.","pitfall":"En önskan att ändra sig i efterhand ger inte i sig rätt att få boten undanröjd."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 13–14 §§","title":"Vilka gärningar kan ge ordningsbot?","rule":"Brottet ska uppfylla villkoren om penningböter, omfattas av riksåklagarens urval och sakna särskilt åtalsvillkor.","apply":"Leta upp rätt gärning i aktuell bilaga och kontrollera att beskrivningen faktiskt passar omständigheterna.","pitfall":"Att ett brott kan ge böter är bara en del av prövningen."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 15 §","title":"Tre hinder mot ordningsbot","rule":"Bot får inte utfärdas om personen förnekar gärningen, om föreläggandet inte omfattar alla kända brott som ska bedömas eller om enskilt anspråk kan väntas.","apply":"Efter en kollision, fråga efter egendomsskada och eventuella anspråk samt utred om ett allvarligare brott behöver prövas.","pitfall":"Den misstänktes vilja att betala löser inte andra hinder i paragrafen."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 16 §","title":"På plats, senare eller i frånvaro","rule":"Den misstänkte får normalt ta ställning i närvaro av polisen. Det går att medge tid för senare godkännande, även för föreläggande i frånvaro.","apply":"Skilj rådrum för den närvarande från kontorsföreläggande. Kontrollera villkoren i FAP 261-1.","pitfall":"Att vara tveksam inför godkännandet är något annat än att förneka gärningen."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 17 § och 12 a §","title":"Innehåll och rättelse av förbiseenden","rule":"17 § anger vad föreläggandet ska innehålla och gör reglerna om bland annat rättelse tillämpliga på ordningsbot.","apply":"Vid ett tydligt skriv- eller räknefel, skilj rättelse från en ny sakprövning. Följ även kompetens- och underrättelsereglerna.","pitfall":"En sådan rättelse får inte höja straffet eller göras mot den berördas invändning."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6","p1-5"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"48 kap. 18 §","title":"Återtagande direkt vid godkännandet","rule":"Vid en uppenbar oriktighet som upptäcks i omedelbart samband med godkännandet kan personen genast få återta det. Då återkallas föreläggandet och ett nytt får utfärdas.","apply":"Beskriv felet, tidssambandet och personens ställningstagande. Ett för högt belopp kan omfattas.","pitfall":"Enbart ett för lågt belopp omfattas inte. Polisen kan inte ensidigt plocka bort ett godkännande."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l6"],"sources":["Föreläsning ordningsbot","FAP 261-1"],"ref":"59 kap. 6–10 §§","title":"Klagan över godkänt föreläggande","rule":"Kapitlet anger särskilda grunder och former för att få ett godkänt föreläggande undanröjt. Det kan exempelvis ha saknats en giltig viljeförklaring.","apply":"Knyt det påstådda felet till en grund i 6 § och läs hänvisningen för ordningsbot i 10 §.","pitfall":"Skilj domstolens undanröjande från polisens omedelbara återkallelse enligt 48 kap. 18 §."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"1–3 §§","title":"Tillämpningsområde, behörighet och identitet","rule":"Föreskriften gäller polisens ordningsbot med undantag för elektroniska ATK-förelägganden. Utfärdaren ska vara utbildad. Den misstänktes identitet ska vara styrkt.","apply":"Notera hur identiteten styrktes innan föreläggandet utfärdas.","pitfall":"Ett påstående om namn är inte automatiskt en styrkt identitet."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"4 §","title":"Kontrollera katalog och svårhetsgrad","rule":"Föreskriften hänvisar till riksåklagarens katalog. Den aktuella grundförfattningen är SFS 2024:1084. Allmänna rådet uppmärksammar fall där en svårare rubricering kan aktualiseras.","apply":"Motivera varför händelsen är ett normalfall av den valda förseelsen.","pitfall":"Kursens tryckta hänvisning till 1999:178 avser en upphävd föreskrift."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6","l10"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"5 §","title":"Uppenbar fordonsbrist","rule":"En brist ska vara uppenbar och kunna fastställas utan ingående undersökning för att ligga till grund för bot enligt denna regel.","apply":"Beskriv vad som syntes eller hördes och om bristen kan ha uppstått under färden. Pröva sedan personens ansvar separat.","pitfall":"En konstaterad brist uppfyller inte automatiskt kraven för ordningsbot mot varje förare."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6","l10"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"6–7 §§","title":"Flygande inspektion och farligt gods","rule":"Vid flygande inspektion krävs relevant förordnande och protokoll. För brister vid transport av farligt gods krävs tillsynsbehörighet och föreskriven dokumentation.","apply":"Skilj den som konstaterar bristen från den polis som därefter utfärdar boten.","pitfall":"En ordningsbotsutbildning ensam ger inte behörighet till alla tekniska och specialiserade kontroller."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"8 §","title":"Hinder mot att utfärda bot","rule":"Utöver RB finns hinder vid känd LVU- eller LVM-vård, viss allvarlig psykisk störning eller verkställighet av frihetsstraff vid brottstidpunkten. Rapport ska då lämnas till åklagare.","apply":"Identifiera vilken av de uppräknade situationerna som faktiskt är känd och vid vilken tidpunkt den gällde.","pitfall":"Förbudet handlar om hanteringsformen. Bedöm själva gärningen separat."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"9 §","title":"Hinder mot bot på plats","rule":"Märkbar påverkan, behov av regelkontroll som inte genast kan göras eller att den misstänkte är upprörd eller skadad hindrar utfärdande på plats.","apply":"Pröva om ett kontorsföreläggande är möjligt, annars rapport till åklagare.","pitfall":"Skilj dessa platshinder från de generella hindren i 8 §."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"10 §","title":"Förklaring före godkännande","rule":"Innebörden och följderna av ett godkännande ska förklaras. Körkortsinnehavare ska även informeras om att brottet under vissa förutsättningar kan påverka körkortet.","apply":"Be personen återge vad anklagelsen gäller och vilka val som finns före godkännande.","pitfall":"Påstå inte att körkortet kommer att återkallas när ett sådant beslut ännu inte finns."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"11 §","title":"Rådrum och unga","rule":"För den som bor eller stadigvarande vistas i ett nordiskt land kan åtta dagars rådrum medges. För personer under 18 år rekommenderas rådrum, särskilt över 2 000 kr.","apply":"Förklara hur och när personen kan godkänna. Skilj föreskriftens krav från dess allmänna råd om samråd med vuxen.","pitfall":"Rådrum kräver inte svenskt medborgarskap."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"12 §","title":"Kontorsföreläggande","rule":"Föreläggande i frånvaro får utfärdas vid bosättning eller stadigvarande vistelse i Sverige eller annat nordiskt land. Den misstänkte ska informeras om hur godkännande sker.","apply":"Kontrollera förutsättningarna vid exempelvis en skada som hindrade bot på plats.","pitfall":"Om gärningen förnekas kvarstår hindret i RB 48 kap. 15 §."},{"law":"FAP 261-1","name":"Polismyndighetens föreskrifter och allmänna råd om ordningsbot (PMFS 2020:9)","url":"https://polisen.se/857e3733dc008e475b2dda20f704b4a6/siteassets/forfattningssamling/fap-nummer/fap261-01-pmfs2020-09/","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"13–15 §§","title":"Behörig rättelse och undantag","rule":"Särskild beslutsutbildning krävs för rättelse. Reglerna skiljer mellan smärre fel och andra uppenbara oriktigheter. Polismyndigheten kan besluta om undantag vid särskilda skäl.","apply":"Fastställ vem som har beslutsbehörighet och när den berörda ska få yttra sig.","pitfall":"En enskild utfärdare kan inte själv besluta om undantag från föreskriften."},{"law":"OBK","name":"Ordningsbotskungörelse (1968:199)","url":"https://data.riksdagen.se/dokument/sfs-1968-199.html","units":["l6"],"sources":["FAP 261-1","Föreläsning ordningsbot"],"ref":"1, 13 och 20 §§","title":"Behörighet och information om förenklad delgivning","rule":"Kungörelsen reglerar bland annat behörighetskraven och informationen när föreläggandet inte godkänns genast, gärningen förnekas eller bot inte kan utfärdas.","apply":"Pröva om den misstänkte kan delges information om förenklad delgivning. Läs vidare i RB 33 kap. 6 §.","pitfall":"Information om senare delgivning är ingen underskrift eller bekännelse."},{"law":"RÅ:s katalog","name":"Riksåklagarens föreskrifter (2024:1084) om ordningsbot för vissa brott","url":"https://www.aklagare.se/om-oss/dokument/ordningsbotskatalog/","units":["l6"],"sources":["Föreläsning ordningsbot","Seminarium ordningsbot","FAP 261-1"],"ref":"1–2 och 4 §§ samt bilagorna","title":"Hitta rätt botkod och belopp","rule":"Aktuella bilagor anger gärningar och fasta belopp för normalfall. Särskilda skäl leder till överlämnande till åklagare.","apply":"Välj regelverk, öppna rätt bilaga och jämför gärning, personkategori och belopp. Kontrollera även handlings- och ansvarsregeln.","pitfall":"Äldre facit använder ibland en äldre katalog eller ett äldre belopp."},{"law":"RÅ:s katalog","name":"Riksåklagarens föreskrifter (2024:1084) om ordningsbot för vissa brott","url":"https://www.aklagare.se/om-oss/dokument/ordningsbotskatalog/","units":["l6"],"sources":["Föreläsning ordningsbot","Seminarium ordningsbot","FAP 261-1"],"ref":"3 §","title":"Flera förseelser i samma bot","rule":"Vid gemensam ordningsbot tas högsta beloppet fullt ut och hälften av summan för övriga brott läggs till.","apply":"Två belopp på 2 000 och 1 000 kr ger 2 500 kr när båda gärningarna får omfattas. Se även BrB 25 kap. 6 §.","pitfall":"Beräkningen görs först efter prövning av om brotten kan och ska tas upp tillsammans."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l1","l3"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"1 kap. 2 §","title":"Uppsåt som huvudregel","rule":"Uppsåt krävs om det inte finns en särskild regel om annat. Vid flera trafikbrott anges oaktsamhet uttryckligen.","apply":"Stryk under skuldkravet i varje straffbestämmelse och förklara vilka omständigheter det måste omfatta.","pitfall":"Kravet kan skilja sig mellan två stycken i samma paragraf, exempelvis i TBL 3 §."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l6","l9"],"sources":["Övningstentamen trafik","Vecka 4 – övningsuppgifter"],"ref":"1 kap. 6 §","title":"Ålder vid en ordningsbotsförseelse","rule":"För kursens penningbotsbrott kan påföljd dömas ut först om personen fyllt 15 år vid gärningen. Undantaget för vissa mycket allvarliga brott begångna av 14-åringar omfattar inte dessa förseelser.","apply":"Utgå från födelsedagen och gärningsdagen när du bedömer en elevs eget ansvar.","pitfall":"Eventuellt ansvar för en vuxen förare eller tillåtare prövas för sig."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2","l12"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"3 kap. 7 §","title":"Vållande till annans död","rule":"För ansvar ska någon genom oaktsamhet ha orsakat en annan persons död. Lagen skiljer mellan ringa brott, normalgraden och grovt brott.","apply":"Förklara vad en aktsam förare kunde ha gjort och varför just avvikelsen orsakade dödsfallet.","pitfall":"Ett dödsfall räcker inte som bevis för oaktsamhet eller för den grova graden."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2","l12"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"3 kap. 8 §","title":"Vållande till kroppsskada eller sjukdom","rule":"Oaktsamheten ska ha orsakat en annan person en kroppsskada eller sjukdom som är mer än ringa.","apply":"Skilj ut skadans art och följder, orsakssambandet och det påstådda oaktsamma handlandet. Läs därefter 12 §.","pitfall":"Förväxla inte skadans omfattning med graden av själva brottet."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2","l12"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"3 kap. 9 §","title":"Framkallande av fara för annan","rule":"Grov oaktsamhet ska ha utsatt en annan person för konkret livsfara eller fara för svår kroppsskada eller allvarlig sjukdom.","apply":"Identifiera vem som befann sig i faran och förklara hur nära och allvarlig den var.","pitfall":"En allmänt riskabel körning och konkret kvalificerad fara för en person är olika prövningar."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2","l12"],"sources":["Trafikjuridik 1","RäV 2023:18 – vårdslöshet och vållande"],"ref":"3 kap. 12 §","title":"När krävs målsägandens angivelse?","rule":"Vid vållande till kroppsskada eller sjukdom som inte är grovt krävs i regel angivelse och att åtal är påkallat ur allmän synpunkt. Angivelse behövs inte om den skadade var under 18 år.","apply":"Fråga om inställningen till åtal och dokumentera svaret. Skilj frågan om åtal från ett ersättningsanspråk.","pitfall":"Åldern avser gärningstillfället. Att angivelse inte krävs för ett barn tar inte bort kravet om allmän synpunkt."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l12"],"sources":["Hantera trafikolycka","Polisjuridik med kommentar"],"ref":"4 kap. 6 a och 6 c §§","title":"Fotografering och spridning av integritetskänsliga bilder","rule":"6 a § avser hemlig, olovlig fotografering i vissa privata utrymmen. 6 c § gäller spridning av vissa känsliga bilder eller uppgifter när spridningen typiskt kan medföra allvarlig skada.","apply":"I ett olycksfall, pröva plats och fotografering för sig. Pröva sedan bildens innehåll, spridning och om gärningen var försvarlig.","pitfall":"En synlig kamera vid vägkanten visar inte ensam att ett brott har begåtts."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2","l12"],"sources":["Övningsuppgifter vecka 7"],"ref":"12 kap. 1 §","title":"Skadegörelse","rule":"Att förstöra eller skada egendom till men för någon annans rätt till den kan vara skadegörelse. Uppsåt krävs som huvudregel.","apply":"Fråga vad som skadades, vems rätt som berörs och vad föraren hade uppsåt till.","pitfall":"En oavsiktlig skada vid en olycka är inte i sig uppsåtlig skadegörelse."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"13 kap. 5 c §","title":"Sabotage mot blåljusverksamhet","rule":"Straffbudet avser angrepp på eller störningar av polis, räddningstjänst eller ambulanssjukvård som uppfyller lagens krav och är ägnade att allvarligt hindra eller försena verksamheten.","apply":"I ett olycksfall, identifiera den konkreta gärningen och hur den skulle påverka en utryckning eller brottsbekämpande insats.","pitfall":"Att en åskådare befinner sig eller filmar på platsen räcker inte i sig."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"16 kap. 1 och 3 §§","title":"Upplopp och ohörsamhet mot ordningsmakten","rule":"Bestämmelserna gäller särskilda situationer med folksamlingar och skilda krav på beteende, uppsåt och myndighetsåtgärder.","apply":"Vid en olycksplats, kontrollera vilka omständigheter som faktiskt rör folksamlingen och vilken befallning som lämnats.","pitfall":"En enskild vägran att följa en valfri uppmaning uppfyller inte automatiskt dessa straffbud."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l6","w2-3"],"sources":["Vecka 2 – övningsuppgifter"],"ref":"16 kap. 16 §","title":"Förargelseväckande beteende","rule":"Oväsen på allmän plats eller annat offentligt beteende kan ge penningböter om beteendet är ägnat att väcka förargelse hos allmänheten.","apply":"Beskriv platsens tillgänglighet, insyn och hur personen agerade i parkfallet. Slå därefter upp relevant katalogpost.","pitfall":"En enskild persons irritation avgör inte ensam om beteendet varit förargelseväckande."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l11"],"sources":["Polisjuridik med kommentar"],"ref":"20 kap. 1 §","title":"Tjänstefel vid myndighetsutövning","rule":"Att uppsåtligen eller av oaktsamhet åsidosätta vad som gäller för en uppgift vid myndighetsutövning kan medföra ansvar för tjänstefel. Ringa gärningar är undantagna.","apply":"Ange vilken tjänsteuppgift, regel och försummelse som påstås och vilka konsekvenser den haft.","pitfall":"Ett beslut som senare ändras är inte ensamt bevis för tjänstefel."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l3","l4"],"sources":["Trafikjuridik 2","Övningstentamen trafik"],"ref":"23 kap. 4 §","title":"Anstiftan och medhjälp","rule":"Medverkansregeln kan omfatta den som främjat brottet med råd eller handling. Vid specialstraffrätt gäller den normalt när fängelse är föreskrivet, eller om en särskild regel anger det.","apply":"Utred varje persons handling och eget skuldkrav. Kontrollera i TrF om det finns en särskild hänvisning till medverkansansvar.","pitfall":"En passagerares närvaro ensam bevisar inte att gärningen har främjats."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l11"],"sources":["Polisjuridik med kommentar"],"ref":"24 kap. 1 §","title":"Nödvärn","rule":"I de situationer som lagen räknar upp kan en gärning i nödvärn vara tillåten. Gränsen är om den är uppenbart oförsvarlig med hänsyn till omständigheterna.","apply":"Skilj prövningen av en faktisk nödvärnssituation från frågan om det fanns lagstöd för en planerad myndighetsåtgärd.","pitfall":"Nödvärn utgör inte ett allmänt tillstånd till tvång i en trafikkontroll."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l6"],"sources":["Föreläsning ordningsbot"],"ref":"25 kap. 1–3 och 5–6 §§","title":"Dagsböter, penningböter och gemensamma böter","rule":"Penningböter anges i kronor och kan som gemensamt straff för flera brott uppgå till högst 10 000 kr. Dagsböter består av ett antal och ett belopp per dag.","apply":"Skilj domstolens bötesformer från föreläggandeformen. Använd RÅ:s 3 § när flera ordningsbotsbelopp får läggas samman.","pitfall":"En föreskrift om dagsböter blir inte en ordningsbotsförseelse för att gärningen är lätt att utreda."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l5"],"sources":["RäV 2023:4 – förverkande"],"ref":"29 kap. 5 § och 30 kap. 4 §","title":"Omständigheter vid straffmätning och påföljdsval","rule":"Utöver straffvärdet kan vissa följder för den tilltalade påverka straffmätning och valet av påföljd.","apply":"Anteckna egendomens värde och de konkreta följder som åberopas vid yrkande om fordonsförverkande.","pitfall":"Förverkandets egna villkor i TBL 7 § måste fortfarande prövas."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l6"],"sources":["FAP 261-1, 8 §"],"ref":"30 kap. 6 §","title":"Allvarlig psykisk störning och rapporteringsform","rule":"FAP 261-1 hänvisar till denna paragraf för vad som avses med allvarlig psykisk störning i föreskriftens ordningsbotshinder.","apply":"I ett övningsfall, skilj kända omständigheter om sådan störning från märkbar alkoholpåverkan enligt 9 § FAP.","pitfall":"Oro, ilska eller ett ovanligt beteende är inte i sig en fastställd psykisk störning."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l5"],"sources":["RäV 2023:4 – förverkande"],"ref":"34 kap. 3 §","title":"Nyupptäckt brott efter tidigare dom","rule":"Bestämmelsen anger när en tidigare påföljd får omfatta även nyupptäckt brottslighet.","apply":"I förverkandevägledningens tidigare-dom-exempel, läs domslutet och skilj påföljden från ett separat förverkandeyrkande.","pitfall":"Ett förordnande om tidigare påföljd ersätter inte en bedömning enligt TBL 7 §."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l2"],"sources":["RäV 2023:18 – vårdslöshet och vållande"],"ref":"35 kap. 2 §","title":"Åtalspreskription vid flera brott i samma gärning","rule":"När samma gärning innefattar flera brott kan påföljd dömas ut för samtliga så länge något av dem inte är preskriberat.","apply":"Identifiera först om det gäller en eller flera gärningar. Använd dagens paragraf och kontrollera övergångsreglerna för gärningsdagen.","pitfall":"RäV 2023:18 hänvisar till dåvarande 35 kap. 1 §. Läs nuvarande 2 § för regeln om flera brott."},{"law":"BrB","name":"Brottsbalk (1962:700)","url":"https://data.riksdagen.se/dokument/sfs-1962-700.html","units":["l5","r7"],"sources":["RäV 2023:4 – förverkande"],"ref":"36 kap. 2, 11 och 13–15 §§","title":"Vem kan träffas av ett förverkande?","rule":"Kapitlet kompletterar förverkanderegler i andra författningar. Kontrollera särskilda regler, ägande och lagens presumtioner om ägare.","apply":"Vid lånad bil, utred faktisk besittning, köpehandlingar och uppgifter från berörda. Läs både TBL 7 § och nu gällande 36 kap. BrB.","pitfall":"RäV 2023:4 återger gamla 36 kap. 5 §. Kapitlet skrevs om den 8 november 2024. Registrerad ägare är inte alltid verklig ägare."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12","l2"],"sources":["RäV 2023:18 – vårdslöshet och vållande"],"ref":"20 kap. 4 §","title":"Samma gärning och angivelse","rule":"Om en och samma gärning innefattar flera brott får åklagaren åtala för alla även om bara något av dem hör under allmänt åtal utan angivelse.","apply":"Dokumentera ändå den skadades inställning till åtal för vållande. Den andra rubriceringen kan falla bort.","pitfall":"Flera brott vid samma tillfälle är inte alltid samma gärning."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12","l2"],"sources":["RäV 2023:18 – vårdslöshet och vållande"],"ref":"20 kap. 8 § och 22 kap. 2 §","title":"Målsägande och enskilt anspråk","rule":"RB anger vem som är målsägande och när åklagaren ska biträda med ett enskilt anspråk.","apply":"Fråga vem brottet riktat sig mot eller skadat, vilket anspråk som finns och vilket underlag som stöder det.","pitfall":"Målsägandeställning, önskan om åtal och begäran om skadestånd är tre skilda frågor."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11","l12"],"sources":["Trafikjuridik 2","Hantera trafikolycka"],"ref":"23 kap. 1, 3, 4 och 6 §§","title":"Inledande, ledning och objektiv utredning","rule":"Förundersökning ska normalt inledas när det finns anledning att anta ett brott under allmänt åtal. Reglerna styr ledning, objektivitet och vem som får höras.","apply":"Skilj grund för att inleda utredning från misstankegrad mot en viss person. Anteckna även uppgifter som talar till personens fördel.","pitfall":"En hypotes om föraren ersätter inte utredning av vem som faktiskt körde."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"23 kap. 8 §","title":"Medföljande till förhör","rule":"En person på platsen där brott begås kan under lagens förutsättningar vara skyldig att följa med till omedelbart förhör. Särskilda regler gäller vissa allvarliga brott i närheten.","apply":"Beskriv plats, tid, förhörsbehov och varför det måste ske omedelbart.","pitfall":"Att en person kan ha sett något innebär inte en obegränsad befogenhet att ta med personen."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11"],"sources":["Övningstentamen trafik","Polisjuridik med kommentar"],"ref":"24 kap. 1 och 7–8 §§","title":"Gripande och skyndsam omprövning","rule":"Gripande, anhållande och häktning är olika beslut. Vid ett brådskande gripande ska förutsättningarna för åtgärden finnas och fortsatt frihetsberövande prövas skyndsamt.","apply":"Ange misstankegrund, relevant frihetsberövandegrund, proportionalitet, förhör och vem som beslutar i nästa led.","pitfall":"En tidigare lagföring eller en passagerares närvaro räcker inte för att utan vidare gripa personen."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l5","l11"],"sources":["Trafikjuridik 2","RäV 2023:4 – förverkande"],"ref":"27 kap. 1 §","title":"Beslag för bevisning eller förverkande","rule":"Egendom som skäligen kan antas ha betydelse för utredningen eller kunna förverkas kan bland annat tas i beslag under krav på proportionalitet.","apply":"Ange exakt föremål och beslagets ändamål. Vid fordonsförverkande, knyt bedömningen till TBL 7 §.","pitfall":"Ett beslag avgör inte vem som äger egendomen eller om den slutligen förverkas."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l5","l11"],"sources":["Trafikjuridik 2","RäV 2023:4 – förverkande"],"ref":"27 kap. 4 och 6 §§","title":"Vem beslutar om beslag och hur prövas det?","rule":"4 § skiljer mellan olika grunder för att ta föremål i beslag och reglerar anmälan och prövning av polisbeslag. Den drabbade får begära rättens prövning av ett beslag som genomförts utan rättens förordnande.","apply":"Kontrollera hur föremålet påträffades och vem som fattade beslutet. Koppla en begärd domstolsprövning till spärren i TBL 8 §.","pitfall":"Fara i dröjsmål måste bedömas i det konkreta fallet."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"27 kap. 15 §","title":"Avspärrning för att säkra brottsutredning","rule":"För att säkerställa utredning om brott får bland annat tillträde till ett område förbjudas.","apply":"I en olycka, förklara vilken bevisning eller undersökning som behöver skyddas och varför området måste avgränsas.","pitfall":"En avspärrning skapar inte automatiskt ett allmänt förbud att fotografera från utsidan."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"27 kap. 20 a–20 c §§","title":"Hemlig kameraövervakning som särskilt tvångsmedel","rule":"Dessa bestämmelser hör till de särskilt reglerade hemliga tvångsmedlen. Kursens äldre kommentar tar upp dem i avsnittet om filmning.","apply":"Identifiera först vem som filmar, i vilket syfte och om det över huvud taget är fråga om det hemliga tvångsmedlet.","pitfall":"Bestämmelsernas brotts- och tillståndskrav gäller en annan situation än en privatpersons fotografering vid en trafikolycka."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11"],"sources":["Trafikjuridik 2","Polisjuridik med kommentar"],"ref":"28 kap. 1–2 §§","title":"Husrannsakan efter föremål eller person","rule":"1 § rör sökande efter bland annat bevis vid utredning av ett brott med fängelse i straffskalan. 2 § reglerar eftersökande av en person för angivna ändamål.","apply":"Ange om syftet gäller ett föremål eller en person, aktuell brottsmisstanke och vems utrymme som berörs.","pitfall":"En vanlig trafikkontroll ger inte i sig grund för husrannsakan. Villkoren är strängare hos annan än den misstänkte."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11"],"sources":["Trafikjuridik 2","Polisjuridik med kommentar"],"ref":"28 kap. 3 a och 4–5 §§","title":"Proportionalitet och beslut om husrannsakan","rule":"Tvångsmedlet kräver en avvägning mellan skäl och intrång. Kapitlet reglerar beslutsbehörighet och polisens möjlighet vid fara i dröjsmål.","apply":"Förklara konkret vad som riskerar att gå förlorat om beslut inväntas och ange vem som beslutade.","pitfall":"Prövningen av brådska ersätter inte kraven i den materiella husrannsakansregeln."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11"],"sources":["Trafikjuridik 2","Polisjuridik med kommentar"],"ref":"28 kap. 11 §","title":"Kroppsvisitation","rule":"Kroppsvisitation omfattar undersökning av bland annat kläder, väskor och föremål som bärs. Förutsättningarna beror på ändamål, brott och personens koppling till brottet.","apply":"Beskriv vad som ska sökas och varför det har betydelse för utredningen. Ange om personen är skäligen misstänkt.","pitfall":"En visitation för brottsutredning och en visitation enligt polislagen har skilda ändamål."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l4","l11"],"sources":["Trafikjuridik 2","Hantera trafikolycka","Övningstentamen trafik"],"ref":"28 kap. 12 §","title":"Kroppsbesiktning vid brottsmisstanke","rule":"Kroppsbesiktning kan innefatta prov från kroppen. Regeln förutsätter skälig misstanke om brott med fängelse i straffskalan och ett tillåtet ändamål.","apply":"Vid misstänkt drograttfylleri, redovisa misstankegrunden, provets ändamål och beslutet. Kontrollera även särskild provtagningslag där den är tillämplig.","pitfall":"Förekomst i urin och förekomst i blod besvarar olika bevisfrågor."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l11"],"sources":["Övningstentamen trafik","Polisjuridik med kommentar"],"ref":"28 kap. 12 a–12 c och 14 §§","title":"DNA-prov och andra biometriska underlag","rule":"DNA-prov omfattas av särskilda villkor. Andra biometriska underlag regleras bland annat i 14 §. Reglerna ändrades 2025.","apply":"Fastställ ändamålet för varje åtgärd, aktuell misstanke, frihetsberövande och om det redan finns registrerade uppgifter.","pitfall":"Ett bevisprov för alkohol och registrering av en DNA-profil har olika lagstöd."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l4","l11"],"sources":["Trafikjuridik 2","Övningstentamen trafik"],"ref":"28 kap. 13 och 13 a §§","title":"Beslut, medtagande och kvarhållande för prov","rule":"Kapitlet reglerar beslut och genomförande samt medtagande och begränsad tid för kvarhållande. Blodprov får bara tas av läkare eller legitimerad sjuksköterska.","apply":"Ange grunden för besiktningen innan du beskriver medtagandet. Tid för kvarhållande och eventuell förlängning måste kunna motiveras.","pitfall":"Att någon ska lämna ett prov är inte i sig en grund för obegränsat kvarhållande."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l2","l3","l6"],"sources":["RäV 2024:3 – olovlig körning","RäV 2023:18 – vårdslöshet och vållande"],"ref":"30 kap. 9 §","title":"Rättskraft och samma gärning","rule":"En fråga om ansvar för en gärning som redan prövats genom lagakraftvunnen dom får som huvudregel inte tas upp på nytt.","apply":"Jämför tid, plats och handlingsförlopp med tidigare dom eller godkänt föreläggande. Läs även 48 kap. 3 §.","pitfall":"En ny brottsrubricering innebär inte automatiskt en ny gärning."},{"law":"RB","name":"Rättegångsbalk (1942:740)","url":"https://data.riksdagen.se/dokument/sfs-1942-740.html","units":["l12"],"sources":["Polisjuridik med kommentar"],"ref":"36 kap.","title":"Vittne i domstol","rule":"Kapitlet styr bland annat vem som får vittna, undantag och hur vittnesförhör går till.","apply":"Skilj uppgifter från en person på plats från senare kallelse och skyldigheter inför rätta.","pitfall":"Vittnesreglerna ger inte i sig en allmän rätt att identitetskontrollera alla som befinner sig på en olycksplats."},{"law":"Förverkandeförfarandelagen","name":"Lag (2024:782) om förfarandet vid förverkande av egendom och åläggande av företagsbot","url":"https://data.riksdagen.se/dokument/sfs-2024-782.html","units":["l5"],"sources":["RäV 2023:4 – förverkande (äldre förfarande)","Trafikjuridik 2"],"ref":"3 kap. och 4 kap. 1–2 §§","title":"Särskild talan om förverkande och beslut i vissa fall","rule":"Lagen anger när brottsbekämpande myndigheter själva kan besluta. Om förverkandefrågan ska prövas i domstol separat från skuldfrågan förs särskild talan av åklagaren.","apply":"Pröva först vem yrkandet rör och om förverkandet kan handläggas tillsammans med ansvarsfrågan. Läs sedan den tillämpliga förfaranderegeln.","pitfall":"TBL 7 § reglerar de materiella villkoren. Den anger inte ensam alla regler om vem som beslutar."},{"law":"Förverkandelagen 1986","name":"Lag (1986:1009) om förfarandet i vissa fall vid förverkande m.m.","url":"https://data.riksdagen.se/dokument/sfs-1986-1009.html","units":["l5"],"sources":["RäV 2023:4 – förverkande"],"ref":"2–3 §§ (upphävda)","title":"Äldre regler i kursens förverkandevägledning","rule":"Lagen upphävdes den 8 november 2024 genom SFS 2024:782. Kursvägledningen skrevs före reformen.","apply":"Använd hänvisningen för att förstå äldre rättsfall. Börja i den nya lagen för ett nytt övningsfall och kontrollera övergångsbestämmelser vid äldre händelser.","pitfall":"Att ett paragrafnummer finns i en uppladdad vägledning visar inte att bestämmelsen fortfarande gäller."},{"law":"SFB","name":"Socialförsäkringsbalk (2010:110)","url":"https://data.riksdagen.se/dokument/sfs-2010-110.html","units":["l5"],"sources":["RäV 2023:4 – förverkande","TBL 8 §"],"ref":"2 kap. 6–7 §§","title":"Prisbasbelopp vid värdering av beslagtaget fordon","rule":"Balken reglerar prisbasbeloppet. TBL 8 § knyter sitt värdevillkor till en femtedel av prisbasbeloppet vid beslaget.","apply":"Slå upp beloppet för beslagets år, dela med fem och jämför med dokumenterad värdering.","pitfall":"TBL kräver att värdet understiger gränsen. Exakt samma belopp ligger inte under den."},{"law":"Ärendelagen","name":"Lag (1996:242) om domstolsärenden","url":"https://data.riksdagen.se/dokument/sfs-1996-242.html","units":["l5"],"sources":["TBL 10 §","RäV 2023:4 – förverkande"],"ref":"1–2 §§","title":"Domstolens handläggning av ersättningsfrågan","rule":"TBL 10 § hänvisar till lagen om domstolsärenden vid prövning av ersättning för ett fordon som inte förverkats efter förtida försäljning eller förstöring.","apply":"Skilj domstolsärendet om ersättningen från brottmålet och från den tidigare prövningen av beslaget.","pitfall":"Den särskilda tidsfristen för att begära prövning står i TBL 10 §."},{"law":"LUL","name":"Lag (1964:167) med särskilda bestämmelser om unga lagöverträdare","url":"https://data.riksdagen.se/dokument/sfs-1964-167.html","units":["l9","l11"],"sources":["Vecka 5 – övningsuppgifter om ung förare (kompletterande lagstöd)"],"ref":"5–7 §§","title":"Ung misstänkt – vårdnadshavare och socialtjänst","rule":"Vid skälig misstanke mot någon under 18 år ska vårdnadshavare som huvudregel underrättas och kallas till förhör. För socialnämndens underrättelse och närvaro finns egna villkor.","apply":"I ett mopedfall, skilj beslut om vårdnadshavare, socialtjänst och försvarare. Läs undantagen, särskilt om den vuxne själv kan vara inblandad.","pitfall":"Att en förälder är på plats ersätter inte prövningen av den unges rätt till försvarare."},{"law":"LUL","name":"Lag (1964:167) med särskilda bestämmelser om unga lagöverträdare","url":"https://data.riksdagen.se/dokument/sfs-1964-167.html","units":["l9","l11"],"sources":["Vecka 5 – övningsuppgifter om ung förare (kompletterande lagstöd)"],"ref":"24 §","title":"Offentlig försvarare för person under 18 år","rule":"En offentlig försvarare ska förordnas om det inte är uppenbart att den unge saknar behov av försvarare. Undersökningsledaren anmäler frågan hos rätten.","apply":"Bedöm den unges behov i det enskilda fallet innan förhörets genomförande planeras.","pitfall":"Ett kort exempel i ett övningsfacit är ingen generell regel om att hålla förhör utan försvarare."},{"law":"FUK","name":"Förundersökningskungörelse (1947:948)","url":"https://data.riksdagen.se/dokument/sfs-1947-948.html","units":["l9","l12"],"sources":["Vecka 5 – övningsuppgifter om ung förare (kompletterande lagstöd)"],"ref":"17–18 §§","title":"Planering av förhör med barn","rule":"Barnförhör ska anpassas så att barnet skyddas mot skada. Omfattning och antal förhör ska begränsas. Särskild kompetens hos förhörsledaren är önskvärd.","apply":"Ange om barnet hörs som misstänkt, målsägande eller vittne och anpassa språk, längd och stöd till barnet.","pitfall":"Förhörsplanering och vårdnadshavares närvaro har olika rättsliga förutsättningar."},{"law":"MB","name":"Miljöbalk (1998:808)","url":"https://data.riksdagen.se/dokument/sfs-1998-808.html","units":["l6"],"sources":["Vecka 6 – övningsuppgifter","Föreläsning ordningsbot"],"ref":"29 kap. 7 och 7 a §§","title":"Nedskräpning och nedskräpningsförseelse","rule":"Nedskräpning utomhus där allmänheten har tillträde eller insyn kan vara brottslig. Är gärningen mindre allvarlig kan den bedömas som nedskräpningsförseelse med penningböter.","apply":"Beskriv vad som lämnades, platsen, omfattningen och personens uppsåt eller oaktsamhet. Pröva sedan katalogpost och hinder mot bot.","pitfall":"Varje fall av nedskräpning är inte en nedskräpningsförseelse som får ordningsbotsrapporteras."},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"1 kap. 1–2 §§","title":"Var gäller trafikreglerna?","rule":"Förordningen reglerar trafik på väg och i terräng. På vissa inhägnade områden undantas de bestämmelser som räknas upp i 2 §.","apply":"Pröva först vad platsen används till och därefter om just den aktuella regeln finns i undantagslistan.","pitfall":"Privat mark eller en parkeringsplats innebär i sig inget generellt undantag.","sources":["Trafikjuridik 2, bild 28"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K1P1","units":["l1","l13"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"1 kap. 4 §","title":"Ryttare, gående och den som leder en cykel","rule":"Fordonsregler gäller i tillämpliga delar för ryttare och den som leder eller driver kreatur. Flera andra trafikanter jämställs med gående.","apply":"Den som kliver av och leder cykeln bedöms enligt gångreglerna. För rullstol som personen själv för har gångfarten betydelse.","pitfall":"Skilj på att färdas på ett fordon och att leda det.","sources":["Trafikjuridik 2, bild 28"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K1P4","units":["l1","l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"1 kap. 5 §","title":"Ägarens skyldighet när någon annan kör","rule":"Ägaren ska se till att fordonet används enligt reglerna. När en annan person brukar det är skyldigheten begränsad till angivna vikt-, däck- och belastningsregler.","apply":"I vinterdäcksfallet prövas vilka åtgärder ägaren kunde vidta och därefter ansvaret enligt 14 kap. 11 §.","pitfall":"Ägandet ensamt räcker inte för ansvar.","sources":["Trafikjuridik 2, bild 28","Facit vecka 2, fråga 2","Övningstenta med facit"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K1P5","units":["l1","w2-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 1 §","title":"Omsorg, varsamhet och hänsyn","rule":"Alla trafikanter ska anpassa sitt uppträdande till risken för olyckor. Barn, äldre och vissa andra grupper kräver särskild hänsyn.","apply":"Beskriv vad föraren kunde uppfatta, vilka risker miljön innebar och hur en försiktig trafikant kunde agera.","pitfall":"Pröva en konkret straffsanktionerad regel och vid allvarlig oaktsamhet även trafikbrottslagen.","sources":["Trafikjuridik 2, bild 30","Rättslig vägledning om vårdslöshet i trafik"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P1","units":["l1","l2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 2 §","title":"Vägmärken, vägmarkeringar och signaler","rule":"En trafikanvisning gäller framför en avvikande trafikregel. Fast sken i trafiksignal gäller framför skyltad stopp- eller väjningsplikt.","apply":"Vid en rödljuspassage behövs uppgifter om signalbilden när fordonet passerade stopplinjen. Vid fast gult har möjligheten att stanna säkert betydelse.","pitfall":"Fast gult och blinkande gult har olika innebörd.","sources":["Trafikjuridik 2, bild 30","Facit vecka 6, fråga 4","Facit vecka 7, case 2"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P2","units":["l7","w6-3","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 3 §","title":"Polismans anvisning i trafiken","rule":"Trafikanten ska följa en polismans anvisning även när den avviker från en signal eller en trafikregel. Bestämmelsen omfattar också vissa andra behöriga personer.","apply":"Om en polis dirigerar trafiken vid ett trafikljus, ange vad polisen faktiskt visade och vem anvisningen riktade sig till.","pitfall":"Enbart polisens närvaro är ingen anvisning.","sources":["Trafikjuridik 1","Trafikjuridik 2, bild 30"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P3","units":["l1","l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 5 §","title":"Fri väg för utryckningsfordon och spårtrafik","rule":"Trafikanten ska lämna fri väg för ett utryckningsfordon som signalerar med föreskriven larmanordning samt för järnvägståg och spårvagn med de undantag paragrafen anger. Stanna om det behövs.","apply":"Skilj trafikantens skyldighet från utryckningsförarens rätt att kräva fri väg i 11 kap. 12 §.","pitfall":"En signal tar inte bort utryckningsförarens eget säkerhetsansvar.","sources":["Trafikjuridik 2, bild 30","Trafikjuridik 3, bild 25"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P5","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 6–7 §§","title":"Procession och korsning med järnväg","rule":"6 § skyddar bland annat barngrupper under ledning och processioner mot att hindras eller brytas. 7 § kräver särskild försiktighet vid järnväg och spårväg och anger när en korsning inte får beträdas.","apply":"Vid plankorsning, ange bommens läge, signalbild, annalkande tåg och om utrymmet bortom korsningen var fritt.","pitfall":"En öppen bom tar inte bort trafikantens uppmärksamhetsplikt.","sources":["Trafikjuridik 1, exemplet på hänvisningar i 14 kap. 3 §"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P6","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"2 kap. 8 §","title":"Skyldigheter när en trafikolycka har inträffat","rule":"Den som haft del i olyckan ska stanna kvar, hjälpa skadade efter förmåga och medverka till rimliga åtgärder, oavsett skuld. Paragrafen reglerar också uppgifter, underrättelse och flyttning av fordon.","apply":"Vid parkeringsskada utan närvarande ägare ska den inblandade trafikanten snarast underrätta den skadelidande eller polisen. Vid personskada som inte är obetydlig ska polisen underrättas.","pitfall":"Vid död eller svår personskada får fordonet flyttas endast om det äventyrar annan trafik. Skilj skyldigheterna här från smitningsansvaret i 5 § TBL.","sources":["Trafikjuridik 2, bild 31","Facit vecka 5, fråga 4"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K2P8","units":["l5","l12","w5-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 1 §","title":"Förarens förmåga att köra säkert","rule":"Ett fordon får inte föras av den som på grund av exempelvis sjukdom, uttröttning eller påverkan saknar förmåga att föra det på ett betryggande sätt.","apply":"Knyt trötthet eller påverkan till iakttagelser om färden och förarens tillstånd.","pitfall":"För bedömning av rattfylleri måste rekvisiten i trafikbrottslagen prövas särskilt.","sources":["Trafikjuridik 2, bild 35"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P1","units":["l4","l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 2 §","title":"Avstånd till framförvarande","rule":"Avståndet ska anpassas så att en påkörning kan undvikas om den framförvarande saktar in eller stannar. Avståndet ska också medge säker omkörning för andra när det behövs.","apply":"Beskriv fart, avstånd, observationstid, sikt och väglag i regnfallet.","pitfall":"Paragrafen innehåller ingen allmän fast sekundgräns.","sources":["Trafikjuridik 2, bild 35–36","Facit vecka 7, case 4"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P2","units":["l7","w7-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 3 §","title":"På- och avstigning under färd","rule":"På- och avstigning är förbjuden när fordonet eller spårvagnen är i rörelse. Fotsteg får inte användas för färd om de inte är särskilt inrättade för det.","apply":"Ange om fordonet rörde sig och var personen befann sig.","pitfall":"Farlig passagerarplacering och påstigning i rörelse har olika rekvisit.","sources":["Trafikjuridik 1, exemplet på hänvisningar i 14 kap. 3 §"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P3","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 5 §","title":"Så visar föraren väjningsplikt","rule":"Föraren ska tydligt visa sin avsikt att väja genom att i god tid sänka hastigheten eller stanna och får fortsätta först när det kan ske utan fara eller hinder med hänsyn till andra trafikanters läge och rörelse.","apply":"Vid sen inbromsning behöver du ange hur den andra trafikantens färd påverkades och vad som syntes innan dess.","pitfall":"Utred även vilken bestämmelse eller anvisning som gav föraren väjningsplikt.","sources":["Trafikjuridik 1","Facit vecka 4, fråga 4"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P5","units":["l7","w4-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 6 §","title":"Körbana, cykelbana och gångbana","rule":"Fordon förs normalt på körbana. Cykel och tvåhjulig moped klass II använder normalt cykelbana när sådan finns. Regeln anger när körbana får väljas och när små barn får cykla på gångbana.","apply":"Bedöm elsparkcykelns fordonsklass och skilj mellan körbana, gångbana och cykelbana. Ålder, omsorg och vägens hastighetsgräns kan avgöra undantaget.","pitfall":"Att en cykelbana saknas ger inte en vuxen generell rätt att cykla på gångbanan.","sources":["Trafikjuridik 2, bild 35","Facit vecka 3, fråga 12","Facit vecka 7, case 6"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P6","units":["l7","w3-5","w7-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 7–9 §§","title":"Placering och riktning i körfälten","rule":"Grundreglerna anger högerplacering, när körfält får väljas och vilka körfält som inte får användas på en dubbelriktad väg.","apply":"Rita vägens körfält, markera färdriktningen och ange vilken del av 7–9 §§ som träffar placeringen.","pitfall":"Flera körfält i samma riktning kan medge andra körfältsval än på en smal dubbelriktad väg.","sources":["Trafikjuridik 2, bild 35"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P7","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 10 §","title":"Körfält som reserverats för andra","rule":"Ett körfält för visst fordonsslag får andra fordon normalt använda endast för att korsa det.","apply":"I budbilsfallet, läs vägmärke och tilläggstavla, fastställ om reservationen gällde och hur fordonet använde fältet.","pitfall":"Jämför 8 kap. 2 § för kollektivkörfält och kontrollera lokala föreskrifter.","sources":["Trafikjuridik 2, bild 35","Facit vecka 7, case 1"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P10","units":["l7","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 11 §","title":"Heldragen linje och spärrområde","rule":"Ett hjul får som huvudregel inte föras över en heldragen linje eller på ett spärrområde. Undantagen är knutna till särskilda situationer.","apply":"Anteckna vilken markering hjulet passerade och om det fanns exempelvis ett hinder, en anslutning till fastighet eller en streckad linje på rätt sida.","pitfall":"En långsamtgående vägtrafikant är inte i sig ett generellt undantag.","sources":["Trafikjuridik 2, bild 35","Facit vecka 4, fråga 10"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P11","units":["l7","w4-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 12–13 §§","title":"Vägren och cirkulationens riktning","rule":"12 § anger vilka trafikanter som ska använda en lämplig vägren och när andra får göra det. 13 § anger bland annat färd motsols i cirkulationsplats.","apply":"Fastställ fordonsklass och vägrenens användbarhet. Vid cirkulationsplats prövas infartens väjningsplikt separat enligt 22 §.","pitfall":"En vägren är inte ett vanligt körfält.","sources":["Trafikjuridik 2, bild 35","Rättslig vägledning om mopeder"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P12","units":["l7","l9"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 14 §","title":"Säker hastighet och stoppsträcka","rule":"Hastigheten ska anpassas till förhållandena så att föraren behåller kontrollen och kan stanna på överblickbar vägsträcka och för förutsebara hinder.","apply":"Beskriv hur regn, mörker, last eller sikt påverkade den möjliga stoppsträckan.","pitfall":"Färd under skyltad gräns kan ändå vara för snabb för förhållandena.","sources":["Trafikjuridik 2, bild 36","Rättslig vägledning om vårdslöshet i trafik"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P14","units":["l2","l7","w7-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 15 §","title":"När särskilt låg fart behövs","rule":"Paragrafen pekar ut situationer som kräver tillräckligt låg hastighet, exempelvis skymd sikt, halka eller risk för att barn kommer ut på vägen.","apply":"Namnge riskmiljön och beskriv varför hastigheten var för hög just där.","pitfall":"Kravet att kunna stanna på överblickbar sträcka står i 14 §.","sources":["Trafikjuridik 2, bild 36"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P15","units":["l2","l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 16 §","title":"Omotiverat hinder i trafiken","rule":"En förare får inte utan giltigt skäl köra överdrivet långsamt, bromsa plötsligt eller på annat sätt hindra andra förares körning.","apply":"Utred orsaken till inbromsningen och hur andra förares färd påverkades.","pitfall":"Sikthinder, halka eller en fotgängare kan ge ett giltigt skäl.","sources":["Trafikjuridik 1","Trafikjuridik 2, bild 36"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P16","units":["l2","l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 17 §","title":"Skyltad fart och bashastighet","rule":"Grundgränsen är 50 km/h inom och 70 km/h utom tättbebyggt område. Föreskrifter kan sätta andra gränser och motorväg har särskild reglering.","apply":"Knyt mätplatsen till gällande föreskrift och ange tillåten och uppmätt hastighet efter tillämpligt avdrag.","pitfall":"Fordonstypen kan ge en lägre gräns enligt 4 kap. 20 §.","sources":["Trafikjuridik 2, bild 36","Facit vecka 4, fråga 1"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P17","units":["l7","w4-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 18 §","title":"Högerregeln","rule":"När två fordons kurser skär varandra har föraren normalt väjningsplikt mot fordon från höger, med undantag för särskilt reglerade fall.","apply":"I fallet med den bredare gatan, undersök bland annat huvudled, väjningsmärke och om någon kör ut från parkering eller fastighet.","pitfall":"Gatans bredd avgör inte vem som ska väja.","sources":["Trafikjuridik 2, bild 38","Facit vecka 6, fråga 7"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P18","units":["l7","w6-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 19 §","title":"Var ska man stanna?","rule":"Den som har stopplikt eller ska stanna för en signal ska stanna vid stopplinje. Utan linje gäller den plats paragrafen anger för signal respektive korsande väg.","apply":"I en kö behöver varje förare stanna på den plats som gäller för den egna infarten.","pitfall":"Ett tidigare stopp längst bak i kön fullgör inte automatiskt stopplikten.","sources":["Trafikjuridik 2, bild 38","Facit vecka 4, fråga 3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P19","units":["l7","w4-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 20–21 §§","title":"Korsning, huvudled och utfart","rule":"Körsättet ska anpassas så att korsande trafik inte hindras i onödan. 21 § reglerar bland annat infart på huvudled och utfart från parkering, fastighet eller liknande område.","apply":"Fastställ varifrån respektive fordon kom och om en utfartsregel tar över högerregeln.","pitfall":"En infart kan se ut som en vanlig korsning trots att tillfartens funktion är en annan.","sources":["Trafikjuridik 2, bild 38","Facit vecka 6, fråga 7"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P20","units":["l7","w6-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 22–23 §§","title":"Infart i cirkulationsplats och accelerationsfält","rule":"Den som kör in i en cirkulationsplats ska väja för fordon i cirkulationen. I accelerationsfält gäller särskilda skyldigheter att anpassa fart och lämna fältet säkert.","apply":"Identifiera om händelsen gäller infart, körfältsbyte inne i cirkulationen eller anslutning via accelerationsfält.","pitfall":"Ett körfältsbyte inne i cirkulationen prövas också mot 43 §.","sources":["Trafikjuridik 1","Trafikjuridik 2, bild 38"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P22","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 24–29 §§","title":"Sväng, körfältsval och korsande av körbana","rule":"Reglerna anger hur föraren ska förvissa sig om att manövern kan göras säkert, placera fordonet före och efter sväng samt hantera mötande trafik. Cykel och moped klass II har en särskild möjlighet vid vänstersväng.","apply":"Rita fordonens rörelser före, under och efter svängen. Välj paragraf för just den del där fara eller hinder uppstod.","pitfall":"Blinkers ger inte rätt att svänga framför andra.","sources":["Trafikjuridik 2, bild 38","Trafikjuridik 3, bild 14"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P24","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 30–31 §§","title":"Möte och sida vid omkörning","rule":"Vid möte hålls fordon till höger med säkert sidavstånd. Omkörning sker normalt till vänster. 31 § anger undantag, bland annat för cyklande och mopedförare som kan passera andra fordon än cykel och moped till höger.","apply":"Ange riktning, fordonsslag och om det framförvarande fordonet tydligt förberedde vänstersväng.","pitfall":"Skilj omkörning från sådan passage i skilda körfält som regleras i 41 §.","sources":["Trafikjuridik 2, bild 38","Facit vecka 6, fråga 5"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P30","units":["l7","w6-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 32–38 §§","title":"När är en omkörning säker?","rule":"Säkerhetskraven omfattar bland annat bakomvarande trafik, fritt körfält, sidavstånd och säker återgång. Särskilda regler gäller spårtrafik och den som blir omkörd.","apply":"Beskriv vilken trafik som fanns i de berörda körfälten och hur länge den kunde överblickas.","pitfall":"En streckad linje innebär inte att varje omkörning är säker.","sources":["Trafikjuridik 2, bild 38"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P32","units":["l7","w4-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 39–42 §§","title":"Platser med omkörningsförbud","rule":"39–40 §§ reglerar omkörning vid bland annat korsningar och obevakade övergångsställen. 41–42 §§ avgränsar vissa passager i skilda körfält och vid reserverade körfält.","apply":"Avgör vilken typ av passage du observerat och vilken platsregel som gäller före eller på platsen.","pitfall":"Ett undantag för en typ av korsning kan inte flyttas över till ett obevakat övergångsställe.","sources":["Trafikjuridik 2, bild 38"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P39","units":["l7","w4-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 43–46 §§","title":"Sidoförflyttning, bussutfart och backning","rule":"Körfältsbyte kräver en säker lucka. Vid sammanvävning ska förare ta ömsesidig hänsyn. 45 § gäller buss som lämnar hållplats och 46 § säker vändning och backning.","apply":"Identifiera om föraren bytte körfält eller om två körfält faktiskt gick ihop. Vid bussutfart, kontrollera hastighetsgränsen och bussens tecken.","pitfall":"En köbildning visar inte i sig att körfälten löper samman.","sources":["Trafikjuridik 2, bild 38"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P43","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 47–49 §§","title":"Fara, olämplig uppställning och parkeringsruta","rule":"47 § förbjuder bland annat uppställning som orsakar fara eller onödigt hinder eller skymmer märken och signaler. 48–49 §§ reglerar bland annat uppställning på gång- och cykelbana samt i markerad ruta.","apply":"Beskriv platsen, fordonets läge och vad andra trafikanter kunde se eller göra. Kontrollera undantag för berört fordonsslag.","pitfall":"Välj rätt påföljdssystem för den konkreta uppställningsregeln.","sources":["Trafikjuridik 2, bild 38","Trafikjuridik 3, bild 4–8"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P47","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 49 a §","title":"Tidsgräns, avgift och parkeringsskiva","rule":"På angivna allmänna platser och inom vägområde för allmän väg gäller normalt högst 24 timmars parkering i följd på vardagar utom vardag före sön- och helgdag. Paragrafen reglerar också särskilda parkeringsvillkor.","apply":"Kontrollera plats, huvudman, veckodag och lokala villkor innan du räknar tiden.","pitfall":"24-timmarsregeln gäller inte generellt på all privat mark.","sources":["Trafikjuridik 3, bild 20–21"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P49a","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 50–52 §§","title":"När fordonet lämnas eller blir stående","rule":"50 § gäller bland annat rullningsrisk, obehörigt brukande och dörröppning. 51 § gäller flyttning av ett fordon som blivit stående på förbjuden plats. 52 § anger hur fordon ställs på vägen.","apply":"Vid en dörröppning framför en cyklist, ange vem som öppnade dörren och vilken fara eller olägenhet som uppstod.","pitfall":"Ett redan parkerat fordon utesluter inte ansvar för en farlig dörröppning.","sources":["Trafikjuridik 2, bild 38","Trafikjuridik 3, bild 7–8"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P50","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 53 §","title":"Platser där man varken får stanna eller parkera","rule":"Förbudet omfattar bland annat övergångsstället och de tio metrarna före det samt vägkorsning och området tio meter från korsande körbanas närmaste ytterkant.","apply":"Rita färdriktningen och markera var avståndet mättes. Vid övergångsstället avgör riktningen vilken sida som ligger före.","pitfall":"Tiometersregeln vid övergångsställe och vid vägkorsning mäts på olika sätt.","sources":["Trafikjuridik 2, bild 38","Trafikjuridik 3, bild 5 och 21"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P53","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 54–55 §§","title":"Hållplats, reserverad plats och huvudled","rule":"54 § reglerar bland annat hållplats och laddplats. 55 § förbjuder parkering på bland annat huvudled, framför en fastighetsinfart och nära plankorsning.","apply":"Avgör först varför fordonet stod stilla. På hållplats kan på- eller avstigning vara tillåten om det kan ske utan hinder för den avsedda trafiken.","pitfall":"Förbud mot parkering och förbud mot stannande får olika betydelse vid påstigning.","sources":["Trafikjuridik 2, bild 38","Trafikjuridik 3, bild 21"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P54","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 56–57 §§","title":"Motorvägsstopp och varningstriangel","rule":"56 § hänvisar till motorvägs- och motortrafikledsreglerna. 57 § anger när föraren ska sätta ut varningstriangel vid bland annat haveri, och när ytterligare varning behövs.","apply":"Pröva varför fordonet stod stilla, gällande hastighetsgräns, plats och sikt. Ange hur triangeln kunde uppfattas av trafiken.","pitfall":"Ett motorfel tar inte bort skyldigheterna att varna och flytta fordonet när det är möjligt.","sources":["Trafikjuridik 2, bild 38"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P56","units":["l7","l12"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 61 §","title":"Väjningsplikt vid obevakat övergångsställe","rule":"Förare ska väja för gående som gått ut eller just ska gå ut. Vid obevakad cykelpassage regleras i stället hastighetsanpassning och särskilda skyldigheter efter sväng eller utfart ur cirkulationsplats.","apply":"I motorcykelfallet med blinkande gult, fastställ om övergångsstället var obevakat och var fotgängaren befann sig.","pitfall":"Jämställ inte varje cyklande vid en cykelpassage med gående på ett övergångsställe.","sources":["Facit vecka 7, case 5"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P61","units":["l7","w7-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 64–67 §§","title":"Signal, tecken och bländning","rule":"Ge varningssignal när det behövs för att undvika fara och ge tecken inför bland annat sväng och körfältsbyte. Föraren måste ändå kontrollera att manövern är säker. Lyktor får inte blända andra förare.","apply":"Skilj signalens syfte från frågan om manövern kunde genomföras utan fara.","pitfall":"Utebliven blinkers och farligt körfältsbyte kräver olika observationer.","sources":["Trafikjuridik 2, bild 39"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P64","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 68–73 §§","title":"Belysning under färd på väg","rule":"Föreskriven belysning ska vara tänd under färd. I 68–73 §§ finns villkor för halvljus, helljus, annat ljus i dagsljus, dimbakljus och fordon utan föreskrivna lyktor.","apply":"Vid ett släckt halvljus, skilj på hur föraren använde belysningen och om lyktan var tekniskt defekt. Notera ljus- och väderförhållanden.","pitfall":"Vilka ljus som krävs kan ändras redan vid dålig sikt under dagen.","sources":["Trafikjuridik 2, bild 39","Facit vecka 5, fråga 10"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P68","units":["l7","l10","w5-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 74–77 a §§","title":"Parkeringsljus, ljusfärger och terräng","rule":"74–75 §§ reglerar belysning vid uppställning. 76 § reglerar ljusets färg under färd på väg. 77 § gäller ljus i terräng och 77 a § tillåter särskilt svagt blått ljus på angivna utryckningsfordon.","apply":"Kontrollera färdriktning, ljusfärg, om fordonet var i rörelse och om en specialföreskrift gäller.","pitfall":"Arbetsljus, backning och särskilda fordon kan behöva prövas mot uttryckliga undantag.","sources":["Trafikjuridik 2, bild 39","VVFS 2003:19, belysningsregler"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P74","units":["l7","l9"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 78 §","title":"Last som skymmer föraren eller föreskriven utrustning","rule":"Lasten får inte hindra förarens sikt eller manövrering och inte heller skymma bland annat föreskrivna lyktor eller tecken.","apply":"Ange exakt vilket synfält, reglage, ljus eller tecken som påverkades.","pitfall":"Utskjutande last kan vara rätt utmärkt och ändå hindra sikten.","sources":["Trafikjuridik 2, bild 39","Facit vecka 3, fråga 3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P78","units":["l7","w3-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 79 §","title":"Farlig placering av passagerare","rule":"Antalet passagerare och deras placering får inte medföra risk för fara.","apply":"Ett barn i bagageutrymmet aktualiserar både var barnet satt och vilka konkreta risker platsen medförde. Pröva också 4 kap. 6 och 10 §§.","pitfall":"Farlig placering och överträdelse av antalet registrerade passagerarplatser är skilda frågor.","sources":["Trafikjuridik 2, bild 39","Facit vecka 3, fråga 1","Facit vecka 5, fråga 1"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P79","units":["l7","w3-1","w4-3","w5-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 80–81 §§","title":"Säkra lasten och dess anordningar","rule":"Lasten ska placeras och vid behov säkras så att den exempelvis inte kan skada personer, falla av eller försvåra körningen. Lastsäkringsanordningar får inte släpa eller hänga löst på sätt som anges i 81 §.","apply":"I fallet med pallen, beskriv vikt, placering, säkringen och hur lasten kunde förskjutas. Vid lös hund, utred den konkreta faran.","pitfall":"Att inget föremål ännu har fallit av utesluter inte att lasten kunde falla av.","sources":["Trafikjuridik 2, bild 39","Facit vecka 6, fråga 9","Facit vecka 7, case 9"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P80","units":["l7","w6-5","w7-6"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"3 kap. 82–83 §§","title":"Utmärkning av utskjutande last","rule":"Last framför fordonet eller mer än en meter bakom ska märkas ut. Framåt finns undantag för mindre än en meter som tydligt syns. 83 § reglerar sidled, bland annat över 20 cm utanför fordonet eller mer än 260 cm bred last.","apply":"Mät åt rätt håll, bedöm synligheten och kontrollera de särskilda kraven på lyktor och reflexer vid mörker eller nedsatt sikt.","pitfall":"En meter är en gräns för utmärkning bakom fordonet, ingen generell maxlängd.","sources":["Trafikjuridik 2, bild 39","Facit vecka 3, fråga 3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K3P82","units":["l7","w3-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 3–4 §§","title":"Släpvagnsvikt och totalvikt","rule":"Dragfordonets högsta tillåtna släpvagnsvikt och varje fordons totalvikt begränsar den faktiska belastningen.","apply":"Jämför registrerade uppgifter och faktiska vikter. Pröva förarens behörighet separat.","pitfall":"Ett lätt lastat släp kan ändå kräva högre körkortsbehörighet på grund av totalvikterna.","sources":["Trafikjuridik 3, bild 3","Övningstenta med facit"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P3","units":["l8","w5-5","w6-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 6 §","title":"Passagerare i bil","rule":"Bilen får bara ta så många passagerare som den är registrerad för. Varje passagerare ska färdas på en plats avsedd för passagerare.","apply":"Kontrollera registrerat antal platser och var var och en faktiskt satt. Pröva förarens och passagerarens ansvar var för sig.","pitfall":"Ett tomt framsäte gör inte bagageutrymmet till en passagerarplats.","sources":["Trafikjuridik 3, bild 3","Facit vecka 3, fråga 1","Facit vecka 4, fråga 5","Nationella strategier, avsnittet om bilbälte"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P6","units":["l7","w3-1","w4-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 6 a §","title":"Passagerare i A-traktor","rule":"Vid färd på väg med en bil ombyggd till traktor ska varje passagerare sitta på avsedd plats, högst en per plats.","apply":"Jämför faktisk placering med vilka platser som är avsedda för passagerare efter ombyggnaden.","pitfall":"Att en ursprunglig sittdyna finns kvar visar inte att platsen är godkänd.","sources":["A-traktor, passagerare","Trafikjuridik 3, bild 3","Facit vecka 5, fråga 1–2"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P6a","units":["l9","w5-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 6 b §","title":"Passagerare på motorcykel","rule":"Motorcykeln måste vara inrättad för passagerare. Högst en får följa med på själva motorcykeln och sidvagnen har egen kapacitetsgräns. Normalt krävs att föraren fyllt 18 år.","apply":"Kontrollera fordonets utförande, plats, förarens ålder och om det rör övningskörning.","pitfall":"En extra sittdyna visar inte ensam att motorcykeln är avsedd för passagerare.","sources":["Trafikjuridik 3, bild 3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P6b","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 7–8 §§","title":"Buller, avgaser och störande körning","rule":"7 § kräver att föraren undviker onödigt buller och så långt möjligt avgasolägenheter. 8 § rör onödig och störande körning vid bostadsbebyggelse och störningar genom färdväg, fart eller färdsätt.","apply":"Ange vad föraren gjorde, när och var det hände och vilken störning det gav upphov till.","pitfall":"Ett skadat avgassystem och medvetet onödigt motorbuller aktualiserar olika frågor.","sources":["Trafikjuridik 3, bild 3","Facit vecka 7, case 7 och 10"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P7","units":["l7","l10","w7-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 9 §","title":"Hjälm på motorcykel, moped och vissa terrängfordon","rule":"Hjälm krävs vid färd med motorcykel, moped, traktor b utan karosseri och terrängskoter utan karosseri. Paragrafen räknar upp undantag och anger förarens ansvar för passagerare under 15 år.","apply":"Kontrollera fordonstyp, om det var i rörelse, platsen och eventuellt karosseri och bälte.","pitfall":"En trasig hjälm och en planerad tur till affären ger inget eget undantag.","sources":["Trafikjuridik 3, bild 3","Rättslig vägledning om mopeder","Facit vecka 7, case 5"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P9","units":["l7","l9","w7-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 10 §","title":"Bilbälte och särskilt skydd för barn","rule":"I de uppräknade fordonen ska en tillgänglig bältesplats och bältet användas vid färd på väg. Barn under 135 cm ska normalt ha en särskild skyddsanordning. Undantagen för tillfälliga transporter beror bland annat på ålder och placering.","apply":"Fastställ fordonsklass, färd på väg, tillgängliga platser samt barnets ålder och längd. Pröva även 10 c–d §§.","pitfall":"135 cm styr barnskyddet. Åldersgränsen 15 år har en annan funktion i förarens skyldighet.","sources":["Trafikjuridik 3, bild 3","Facit vecka 4, fråga 7 och 9","A-traktor, bälte","Nationella strategier, avsnittet om bilbälte"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P10","units":["l7","l9","w4-4","w6-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 10 a–10 b §§","title":"Bältesplats i buss och rullstolsplats i bil","rule":"I buss ska den som är äldre än tre år normalt använda tillgänglig bältesplats och bälte. Lokala transporter i tättbebyggda områden har ett undantag. 10 b § reglerar plats, bälte och fasthållning för den som färdas sittande i rullstol i bil.","apply":"Pröva bussens utrustning, resans typ och vilka platser som fanns. Bedöm därefter vem som hade ansvar.","pitfall":"Att resan gjordes med buss avgör inte ensamt om bälte krävdes.","sources":["Trafikjuridik 3, bild 3","Facit vecka 3, fråga 2","Nationella strategier, avsnittet om bilbälte"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P10a","units":["l7","w3-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 10 c §","title":"Vem hjälper barn att använda skyddet?","rule":"Föraren, annan ombordpersonal, ledsagare och gruppledare ska vidta lämpliga åtgärder för passagerare under 15 år och hjälpa till med placering av rullstol.","apply":"Ange personens roll och vilka åtgärder som var möjliga. Läs sedan 14 kap. 5 § för förare och 8 a § för övriga roller.","pitfall":"För förare av buss i linjetrafik finns ett särskilt undantag i ansvarsbestämmelsen.","sources":["Trafikjuridik 3, bild 3","Facit vecka 3, fråga 2","Facit vecka 4, fråga 9","Nationella strategier, avsnittet om bilbälte"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P10c","units":["l7","w3-1","w4-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 10 d §","title":"Bältesundantag vid parkering och backning","rule":"Bälte eller särskild skyddsanordning behöver inte användas när fordonet står stilla, vid backning eller vid färd inom vissa angivna områden, bland annat parkeringsplats och parkeringshus.","apply":"Dokumentera var fordonet befann sig när iakttagelsen gjordes, särskilt vid utfart från en parkering.","pitfall":"Att färden började på en parkering säger inget om bältesplikten ute på vägen.","sources":["Trafikjuridik 3, bild 3","Facit vecka 6, fråga 3","Nationella strategier, avsnittet om bilbälte"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P10d","units":["l7","w6-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 10 e §","title":"Mobiltelefon och kommunikationsutrustning","rule":"Vid färd på väg med motordrivet fordon får aktiviteter inte påverka körningen menligt. Telefon eller annan kommunikationsutrustning får inte användas handhållen.","apply":"Beskriv vad föraren höll och hur utrustningen användes. Vid handsfree behöver eventuell menlig inverkan beskrivas.","pitfall":"De två meningarna har olika rekvisit. För prövning av tjänsteundantag, se 11 kap. 10 a §.","sources":["Trafikjuridik 3, bild 4 och 23","Facit vecka 3, fråga 4","Facit vecka 4, fråga 5"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P10e","units":["l7","w3-2","w4-3"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 12–14 §§","title":"Vägens bärighet och tillåtna fordonsvikter","rule":"Paragraferna reglerar hur bland annat axeltryck, axelavstånd och vägens bärighetsklass begränsar belastningen på andra vägar än enskilda.","apply":"Identifiera vägen, kontrollera bärighetsklass och jämför rätt tabell med uppmätta värden och axelavstånd.","pitfall":"Registrerad totalvikt besvarar inte ensam om vägen tål den aktuella belastningen.","sources":["Övningstenta med facit, ägarens ansvar"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P12","units":["l8"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 15–17 §§","title":"Bredd, längd och lastens yttermått","rule":"15 § reglerar bland annat last som skjuter ut i sidled samt fordonsbredd på andra vägar än enskilda. 16 § gäller hur bredden mäts. 17 § reglerar längd för andra motordrivna fordon än bussar och deras kombinationer.","apply":"Mät med lasten inräknad och pröva fordonsslag, vägtyp och eventuella särskilda villkor.","pitfall":"Att lasten märks ut enligt 3 kap. 82–83 §§ medger inte automatiskt överskriden bredd eller längd.","sources":["Trafikjuridik 3, bild 3","Facit vecka 3, fråga 3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P15","units":["l8","w3-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 18 a §","title":"Vinterdäck för personbil, A-traktor och lätta fordon","rule":"Från 1 december till 31 mars krävs vinterdäck eller likvärdig utrustning vid vinterväglag för personbil klass I och II, ombyggd bil som är traktor, lätt lastbil, lätt buss och deras släp.","apply":"Kontrollera datum, fordonsklass, väglag och eventuellt undantag. Bedöm därefter förares och ägares ansvar var för sig.","pitfall":"Under denna paragraf måste både perioden och vinterväglaget stämma.","sources":["Trafikjuridik 3, bild 4","Facit vecka 2, fråga 2","Övningstenta med facit"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P18a","units":["l7","l10","w2-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 18 b–18 e §§","title":"Tunga fordons vinterutrustning och undantag","rule":"Tung lastbil, tung buss och deras släp ska ha vinterdäck eller likvärdig utrustning 10 november–10 april. 18 c–d §§ behandlar undantag och 18 e § vissa viktförhållanden för tvåaxlad tung lastbil med släp under perioden.","apply":"Jämför den lätta lastbilen i 18 a § med en tung lastbil samma dag och kontrollera fordonets klass i registret.","pitfall":"18 b § ställer inget villkor om vinterväglag för de angivna tunga fordonen.","sources":["Övningstenta med facit, ägaransvar","Trafikjuridik 3, vinterdäck"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P18b","units":["l7","l8","w2-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 20 §","title":"Högsta hastighet för fordonsklassen eller kombinationen","rule":"Utöver vägens hastighetsgräns finns särskilda tak för olika fordon och kombinationer. En bil ombyggd till traktor får föras i högst 30 km/h på väg.","apply":"Identifiera fordonsslag och tillkopplat fordon, läs rätt rad i den lydelse som gäller vid färden och jämför med vägens gräns.","pitfall":"En hastighetsöverträdelse bevisar inte ensam att en teknisk ombyggnad ändrat fordonsklass.","sources":["Trafikjuridik 2, bild 37","A-traktor, hastighet","Facit vecka 5, fråga 1"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P20","units":["l7","l8","l9","w5-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"4 kap. 22 a–22 d §§","title":"Vilka fordon får köra i miljözon?","rule":"Fordonskategori och utsläppsegenskaper avgör om ett fordon får föras i miljözon klass 1, 2 eller 3.","apply":"Fastställ zonens klass och gräns, ta fram fordonsuppgifter och pröva rätt paragraf och eventuellt undantag.","pitfall":"Undantag för viss yrkesutövning måste prövas separat enligt 11 kap. 4 §.","sources":["Trafikjuridik 3, bild 16"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K4P22a","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"5 kap. 1–6 §§","title":"Terrängmotorfordon ute på väg","rule":"Terrängmotorfordon och terrängsläp är normalt hänvisade till enskilda vägar. 2 § medger viss nödvändig vägpassage. 3–5 §§ reglerar utfart, passagerare och fart. Tung terrängvagn på hjul har ett särskilt undantag i 6 §.","apply":"Vid skoterkörning, fastställ först om färden gick på väg eller i terräng. Vid utfart från terrängen ska föraren stanna och lämna vägtrafiken företräde.","pitfall":"Bestämmelser om körning på väg och förbud mot körning i terräng besvarar olika frågor.","sources":["Trafikjuridik 3, avsnittet om tjänsteundantag","Facit vecka 3, skoterolyckan"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K5P1","units":["l13","w3-5"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"6 kap. 3 §","title":"Passagerare på cykel och moped","rule":"Högst så många får färdas samtidigt som fordonet är byggt för. Barn kan medföras enligt särskilda villkor om bland annat ålder, lämpliga säten och skydd.","apply":"För två vuxna på en elsparkcykel, kontrollera att fordonet är en cykel och hur många det är byggt för. Pröva både förares och passagerares ansvar.","pitfall":"En lång ståplatta visar inte att fordonet är byggt för två.","sources":["Facit vecka 7, case 8"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K6P3","units":["l7","w7-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"6 kap. 4 a §","title":"Hjälm för barn som färdas på cykel","rule":"Den som är under 15 år och färdas med tvåhjulig cykel ska använda cykelhjälm eller annat lämpligt huvudskydd. Cykelföraren ska se till att detta följs av passagerare.","apply":"Ange om barnet själv cyklade eller var passagerare. Vid passagerare, pröva förarens skyldighet och 14 kap. 6 a §.","pitfall":"En hjälmplikt för barnet innebär inte att barnet själv kan dömas till böter.","sources":["Trafikjuridik 3, bild 28, hänvisningen till 14 kap. 6 a §","Rättslig vägledning 2023:20, hjälmkrav"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K6P4a","units":["l7","l9"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"6 kap. 4 b §","title":"Huvudskydd på särskild typ av moped klass II","rule":"Den som färdas med en tvåhjulig moped klass II av tramp- och vevtyp, där motorn inte ger krafttillskott över 25 km/h, ska använda cykelhjälm eller annat lämpligt huvudskydd.","apply":"Identifiera mopedens konstruktion innan du väljer mellan hjälmregeln här och motorcykelhjälmsregeln i 4 kap. 9 §.","pitfall":"Hjälmkravet för den här mopedtypen gäller även vuxna.","sources":["Rättslig vägledning 2023:20, avsnitt 3.2"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K6P4b","units":["l9"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"7 kap. 1, 3 §§","title":"Var ska gående gå och korsa vägen?","rule":"Gående ska använda gångbana eller vägren, med de möjligheter som anges när sådan saknas eller är olämplig. För korsande reglerar 3 § bland annat när övergångsställe ska användas.","apply":"Utred banindelning och om övergångsställe låg i närheten. Ange var och hur personen gick.","pitfall":"Koppla en ansvarsbedömning till exakt den del av handlingsregeln som 14 kap. 9 § omfattar.","sources":["Trafikjuridik 3, bild 28, hänvisningen till 14 kap. 9 §"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K7P1","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"8 kap. 1 §","title":"Gågata och gångfartsområde","rule":"Fordon ska hålla gångfart, lämna gående företräde och följa parkeringsförbudet. För motordrivna fordon på gågata finns särskilda begränsningar och transportundantag.","apply":"Vid snabb cykling i gångfartsområde, identifiera områdets utmärkning, beskriv färden och koppla den till 14 kap. 6 §.","pitfall":"Gångfart anger en anpassning till gående. Någon fast km/h-gräns står inte i paragrafen.","sources":["Facit vecka 2, fråga 4","Trafikjuridik 3, bild 21"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K8P1","units":["l7","w2-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"8 kap. 2 §","title":"Vem får använda kollektivkörfält?","rule":"Körfält för linjetrafik får användas av fordon i linjetrafik. I högra fältet i färdriktningen får även cykel och moped klass II föras. Andra föreskrifter kan ändra kretsen.","apply":"Kontrollera fältets placering, vägmärken, tilläggstavlor och eventuellt tjänsteundantag i 11 kap.","pitfall":"En leverans i arbetet ger inte i sig en budbil tillträde.","sources":["Trafikjuridik 3, bild 12 och 15","Facit vecka 7, case 1"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K8P2","units":["l7","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"9 kap. 1–2 §§","title":"Motorväg och motortrafikled","rule":"1 § reglerar tillåtna fordon, infart, utfart, uppställning, vändning, backning och fart på motorväg. 2 § för över angivna delar till motortrafikled och dess anslutningar.","apply":"Vid moped i motorvägsmiljö, kontrollera fordonsklass. Vid hastighetsöverträdelse, fastställ om det verkligen är motorväg och vilken gräns som gäller där.","pitfall":"Motorvägens grundgräns 110 km/h förs inte över till motortrafikled genom 2 §.","sources":["Trafikjuridik 3, bild 17","Facit vecka 4, fråga 1","Rättslig vägledning 2023:20, avsnitt 3.3"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K9P1","units":["l7","w4-1","w6-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"10 kap. 1 §","title":"Lokala trafikföreskrifter","rule":"Särskilda trafikregler får beslutas för vissa vägar, sträckor eller områden i de ämnen som paragrafen räknar upp, exempelvis hastighet och parkering.","apply":"Sök den aktuella föreskriften i Svensk trafikföreskriftssamling. Jämför beslutets utsträckning, giltighetstid och utmärkning med observationsplatsen.","pitfall":"Det räcker inte att ange en kommun om frågan gäller en bestämd sträcka.","sources":["Trafikjuridik 3, bild 9"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K10P1","units":["l1","l7","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"10 kap. 10, 14 §§","title":"Enskild väg och tillfälliga trafikregler","rule":"10 § gäller enskild vägägares möjlighet att förbjuda viss trafik. 14 § gäller trafikregler i angivna särskilda situationer, bland annat vägarbete eller skada på väg.","apply":"Identifiera vem som beslutat om regeln och vilket hinder eller vilken inskränkning som faktiskt gällde.","pitfall":"Ett tjänsteundantag från en viss trafikinskränkning i 11 kap. 1 § ger inte allmän dispens från andra regler.","sources":["Trafikjuridik 3, bild 12 och 22"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K10P10","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 1 §","title":"Gångbana, gågata och förbjuden väg i tjänsten","rule":"För polisman, bilinspektör, tulltjänsteman och Säpo-personal vid angiven skyddsåtgärd finns ett särskilt undantag på gång- och cykelbanor samt gågator. Där gäller särskild försiktighet och högst 30 km/h. Andra stycket medger vissa vägar och områden för en delvis annan grupp.","apply":"Ange vem som använder fordonet, uppgiften och vilken plats det gäller. För kollektivfält eller väg med trafikförbud, läs andra styckets egen uppräkning av yrken och situationer.","pitfall":"30 km/h är ett tak i första stycket. Säkerheten kan kräva betydligt lägre fart.","sources":["Trafikjuridik 3, bild 11–13"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P1","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 2 §","title":"Vägtransporteskort och placering","rule":"Vid föreskriven eskort av vägtransport får polisman eller vägtransportledare göra avsteg från vissa placerings- och svängregler när omständigheterna kräver det och särskild försiktighet iakttas.","apply":"Fastställ att uppdraget faktiskt är ett sådant eskortuppdrag och att just regeln finns uppräknad.","pitfall":"En vanlig tjänsteresa är inget eskortuppdrag.","sources":["Trafikjuridik 3, bild 14"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P2","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 3 §","title":"Särskild rätt till kollektivkörfält","rule":"Ett auktoriserat bevakningsföretag vid transport av egendom, Kriminalvården i angivna uppdrag samt Säpo-personal vid viss skyddsåtgärd får använda kollektivkörfält när omständigheterna kräver det och särskild försiktighet iakttas.","apply":"Identifiera rätt aktör och vad transporten avser. För vanlig polisiär yrkesutövning, läs även 1 § andra stycket.","pitfall":"Att arbeta för ett bevakningsföretag är inte tillräckligt för varje resa.","sources":["Trafikjuridik 3, bild 15"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P3","units":["l7","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 4 §","title":"Undantag för miljözon","rule":"Paragrafen medger avsteg från 4 kap. 22 a–22 d §§ för en uppräknad krets. Där ingår bland annat viss yrkesutövning för polis, tull och vårdpersonal, räddningstjänst, utryckningsfordon och särskilda persontransporter.","apply":"Ange miljözonens klass och exakt vilken punkt som omfattar fordonet eller användningen.","pitfall":"Veteranfordonets undantag omfattar inte miljözon klass 3.","sources":["Trafikjuridik 3, bild 16"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P4","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 5 §","title":"Avsteg från vissa motorvägsregler","rule":"Vissa särskilt angivna regler på motorväg och motortrafikled får frångås vid räddningstjänst, av polis, bilinspektör, tull eller kustbevakning i tjänst, i jämförliga trängande fall, vid angiven Säpo-åtgärd eller av vägtransportledare under eskort. Omständigheterna måste kräva det och särskild försiktighet iakttas.","apply":"Koppla den aktuella bestämmelsen till 9 kap. 1 § första stycket 1–5 eller 2 § och förklara varför uppdraget krävde undantaget.","pitfall":"Hastighetsregeln i punkt 6 täcks inte av 11 kap. 5 §.","sources":["Trafikjuridik 3, bild 17"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P5","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 6 §","title":"Terrängmotorfordon på väg i särskilda uppdrag","rule":"Polis, bilinspektör, tull, kustbevakning och de uppräknade vårdyrkena får i yrkesutövning föra terrängmotorfordon eller terrängsläp på väg trots 5 kap. 1, 4 och 5 §§. Även sjuktransport, räddningstjänst och jämförliga trängande fall omfattas.","apply":"Identifiera fordonstyp, vägmiljö och uppgift. Ange vilken av reglerna i 5 kap. som annars hade gällt.","pitfall":"Förtur till färja regleras i nästa paragraf, 7 §.","sources":["Trafikjuridik 3, bild 18, rubrikens lagrum"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P6","units":["l7","l13"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 7 §","title":"Förtur vid vägfärja","rule":"För de färjor som utgör väganordning har bland annat brådskande räddnings- och sjuktransporter, angivna yrkesutövare i brådskande uppdrag och vissa andra transporter förtur.","apply":"Fastställ färjetyp och om transporten ryms i någon punkt. Även exempelvis linjetrafik, taxi, skolskjuts och färdtjänst finns i uppräkningen.","pitfall":"Föreläsningens bild 18 visar 7 § under rubriken 6 §. Förturen står i 7 §.","sources":["Trafikjuridik 3, bild 18"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P7","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 8 §","title":"Stannande och parkering under eskort","rule":"En polisman vid föreskriven vägtransporteskort och en vägtransportledare under eskortuppdrag kan stanna eller parkera trots vissa uppräknade regler eller lokala förbud när omständigheterna kräver det och särskild försiktighet iakttas.","apply":"Pröva uppdraget och jämför den aktuella parkeringsregeln ord för ord mot hänvisningarna.","pitfall":"Undantaget omfattar inte varje regel i 3 kap. om uppställning.","sources":["Trafikjuridik 3, bild 19"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P8","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 9 §","title":"Stannande och parkering i särskilda verksamheter","rule":"Vissa parkerings- och stannanderegler får frångås när omständigheterna kräver det och särskild försiktighet iakttas. Kretsen omfattar bland annat parkeringsövervakning, polis, bilinspektör, tull och kustbevakning i tjänst, räddningstjänst och vissa vård- och myndighetsuppdrag.","apply":"Pröva exakt förbud, exakt uppdrag och behovet vid just den tidpunkten. Huvudled och kollektivkörfält finns bland de begränsade hänvisningarna.","pitfall":"Förbudet vid övergångsställe i 3 kap. 53 § första stycket 1 täcks inte av hänvisningen till punkt 10.","sources":["Trafikjuridik 3, bild 20–21"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P9","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 10 §","title":"Hastighetsgränser vid brådskande uppdrag","rule":"Angivna hastighetsgränser får frångås vid brådskande utryckning för räddningstjänst eller sjuktransport, vid brådskande yrkesutövning av de uppräknade yrkesgrupperna och i andra jämförliga trängande fall. En särskild regel gäller bandfordon för polis och bilinspektör.","apply":"Beskriv uppgiften och varför den var brådskande. Utred de kvarstående kraven på säker fart i 3 kap. 14–15 §§.","pitfall":"En vanlig tjänsteresa eller ett allmänt tidsschema uppfyller inte automatiskt kravet.","sources":["Trafikjuridik 3, bild 22"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P10","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 10 a §","title":"Handhållen utrustning i vissa uppdrag","rule":"Undantaget gäller endast handhållandeförbudet i 4 kap. 10 e § andra meningen, i angivna fall vid räddningstjänst, sjuktransport, polisarbete, Säpo-skyddsåtgärd, eskort och viss brådskande tjänsteutövning. Omständigheterna måste kräva det och särskild försiktighet iakttas.","apply":"Beskriv uppdraget och kommunikationsbehovet. Bedöm även om användningen påverkade körningen menligt.","pitfall":"Förbudet mot menlig påverkan i första meningen gäller fortfarande.","sources":["Trafikjuridik 3, bild 23"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P10a","units":["l7","w3-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 11 §","title":"Trängande fall och spaningsverksamhet","rule":"En förare av utryckningsfordon i trängande fall kan frångå föreskrifter som inte gäller föraren särskilt. Vid angiven spaning för polis, Säpo, tull och kustbevakning krävs absolut nödvändighet för uppdraget och att det uppenbarligen kan ske utan trafiksäkerhetsfara. Särskild försiktighet gäller.","apply":"Håll isär fordonsstatus och uppgift. Motivera rekvisiten för den gren som är aktuell och ange om en behörig person dirigerade trafiken.","pitfall":"Anvisning från polis eller annan behörig trafikdirigent ska följas även då undantaget gäller.","sources":["Trafikjuridik 3, bild 24"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P11","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"11 kap. 12 §","title":"Att kräva fri väg","rule":"En utryckningsfordonsförare får kräva fri väg i trängande fall genom föreskriven larmanordning. Föraren ska också då ta hänsyn till andra trafikanters säkerhet.","apply":"Kontrollera om det var ett utryckningsfordon, om fallet var trängande och om signal gavs. Koppla till 2 kap. 5 § för övriga trafikanter.","pitfall":"En avgiven signal är ingen garanti för att övriga trafikanter har uppfattat den.","sources":["Trafikjuridik 3, bild 25"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K11P12","units":["l7"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"13 kap. 3 §","title":"Vem får pröva undantag?","rule":"Paragrafens tabell visar vilken myndighet som prövar undantag från angivna trafikregler och föreskrifter. Behörigheten beror på regeln och ibland på färdens geografiska omfattning.","apply":"Identifiera först den trafikregel som behöver frångås. Läs sedan samma rad i tabellen för att hitta beslutsmyndigheten.","pitfall":"En hänvisning i ingressen till en äldre föreskrift måste läsas mot den dåvarande lydelsen.","sources":["VVFS 2003:19, ingressen"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K13P3","units":["l1","l9"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 3 §","title":"Ansvar för förare av motordrivet fordon","rule":"En förare av motordrivet fordon kan dömas till penningböter för uppsåtliga eller oaktsamma överträdelser som räknas upp här. Hänvisningarna kan avse enbart ett visst stycke eller en viss punkt.","apply":"Ange först handlingsregeln, sedan den exakta hänvisningen i ansvarsregeln. Koppla till iakttagelsen och förarens skuld.","pitfall":"Varje olämpligt beteende i 2 eller 3 kap. har inte en egen straffbestämmelse.","sources":["Trafikjuridik 1, handlingsregel och ansvar","Trafikjuridik 3, bild 28","Facit vecka 4 och 7"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P3","units":["l1","l6","w4-1","w7-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 4 §","title":"Föraransvar vid vissa vikt- och däcköverträdelser","rule":"Vid de uppräknade överträdelserna krävs att föraren kände till eller borde ha känt till hindret för brukandet. För olovligt brukande av annans fordon och medverkan finns särskilda bestämmelser.","apply":"I fallet med lånad bil och sommardäck, ange vad föraren kände till och vad som borde ha uppmärksammats före eller under färden.","pitfall":"Förarens prövning ska skiljas från ägarens skyldighet enligt 14 kap. 11 §.","sources":["Trafikjuridik 3, bild 28","Facit vecka 2, fråga 2","Övningstenta med facit"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P4","units":["l1","w2-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 5 §","title":"Föraransvar för annans hjälm eller bälte","rule":"Den förare som uppsåtligen eller oaktsamt åsidosätter plikten i 4 kap. 9 § tredje stycket eller 10 c § kan dömas till penningböter. Förare av buss i linjetrafik enligt yrkestrafiklagen omfattas inte av denna straffbestämmelse.","apply":"Bedöm vilka lämpliga åtgärder föraren vidtog för ett barn under 15 år och håll isär barnets och förarens situation.","pitfall":"En vuxen passagerares eget bältesansvar hör till 8 §.","sources":["Trafikjuridik 3, bild 28","Facit vecka 3, fråga 2","Facit vecka 4, fråga 9"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P5","units":["l1","l6","w3-1","w4-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 6, 6 a §§","title":"Ansvar för cyklande och andra förare","rule":"6 § gäller förare av fordon som inte är motordrivna samt trafikanter enligt 1 kap. 4 § första stycket och de särskilt uppräknade överträdelserna. 6 a § gäller cykelförares skyldighet för passagerare under 15 år enligt 6 kap. 4 a § andra stycket.","apply":"I gångfartsområdet, avgör först om fordonet rättsligt är cykel. Slå sedan upp den överträdda regeln i 6 §.","pitfall":"Klassningen av en elsparkcykel påverkar vilket föraransvar som kan användas.","sources":["Trafikjuridik 1","Trafikjuridik 3, bild 28","Facit vecka 2, fråga 4","Facit vecka 7, case 6"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P6","units":["l1","l6","w2-4","w7-4"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 7 §","title":"Andra trafikanters ansvar","rule":"Andra trafikanter än de som avses i 3 och 6 §§ kan dömas för uppsåtlig eller oaktsam överträdelse av de regler som särskilt anges, till exempel vissa olycksplatsskyldigheter och anvisningar.","apply":"Identifiera trafikantens roll vid händelsen och läs vilken del av handlingsregeln som omfattas.","pitfall":"Hela 2 kap. 8 § omfattas inte av hänvisningen i 7 §.","sources":["Trafikjuridik 3, bild 28"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P7","units":["l1","l12"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 8, 8 a §§","title":"Passagerare, ombordpersonal och ledsagare","rule":"8 § gäller passagerares egna överträdelser av bland annat regler om sittplats, hjälm och bälte. 8 a § gäller ombordpersonal, ledsagare och gruppledare som åsidosätter sina skyldigheter enligt 4 kap. 10 c §.","apply":"Identifiera ålder, roll och vilken skyldighet som tillkom just den personen. Förarens ansvar har egna bestämmelser.","pitfall":"Att flera personer sitter i samma bil innebär inte ett gemensamt bötesansvar.","sources":["Trafikjuridik 3, bild 28","Facit vecka 3, fråga 1–2","Facit vecka 6, fråga 6"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P8","units":["l1","l6","w3-1","w6-1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 9 §","title":"Gåendes ansvar","rule":"Gående kan dömas till penningböter vid uppsåtlig eller oaktsam överträdelse av 7 kap. 1 § första stycket eller 3 §.","apply":"Pröva var personen gick och om gångbana, vägren eller en laglig plats för korsande fanns. Koppla iakttagelsen till rätt handlingsregel.","pitfall":"Alla rekommendationer om hur gående bör bete sig är inte separat straffbelagda.","sources":["Trafikjuridik 1","Trafikjuridik 3, bild 28"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P9","units":["l1"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 11 §","title":"Ägarens straffansvar för bland annat däck och vikt","rule":"Ägaren kan dömas till penningböter om denne uppsåtligen eller oaktsamt har underlåtit sådant som skäligen kunde krävas för att hindra brukande i strid med de särskilt angivna reglerna. Vissa nyttjanderättshavare jämställs med ägaren.","apply":"Fråga vad ägaren visste om utlåningen och däck eller last, och vilka rimliga förebyggande åtgärder som fanns.","pitfall":"Det är inte ett strikt ansvar för allt den som lånade bilen gör.","sources":["Trafikjuridik 3, bild 28","Facit vecka 2, fråga 2","Övningstenta med facit"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P11","units":["l1","w2-2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 14 §","title":"När ett allvarligare brott tar över","rule":"Ansvar enligt förordningen faller bort när straff kan dömas ut för samma gärning enligt brottsbalken eller trafikbrottslagen. För vissa föreskrifter gäller även utmärknings- och kungörelsekrav.","apply":"Pröva den konkreta trafikregeln och vad som därutöver visar exempelvis väsentlig oaktsamhet enligt 1 § TBL. Skilj separata gärningar från samma gärning.","pitfall":"En olycka innebär inte automatiskt att föraren gjort sig skyldig till vårdslöshet i trafik.","sources":["Trafikjuridik 2, bild 29","Rättslig vägledning om vårdslöshet i trafik"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P14","units":["l1","l2"]},{"law":"TrF","name":"Trafikförordning (1998:1276)","ref":"14 kap. 15 §","title":"När fortsatt färd kan hindras","rule":"Om ett fordon framförs i strid med förordningen eller en föreskrift meddelad med stöd av den kan fortsatt färd hindras enligt klampningslagen.","apply":"Vid osäkrad tung last, dokumentera faran och pröva sedan förutsättningar, åtgärd, behörighet och varaktighet enligt klampningslagen.","pitfall":"Hänvisningen till klampningslagen ger inte stöd för varje slags åtgärd i alla situationer.","sources":["Trafikjuridik 3, bild 28–29","Facit vecka 7, case 9"],"url":"https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/trafikforordning-19981276_sfs-1998-1276/#K14P15","units":["l10","w7-6"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"2 kap. 1 och 5 §§","title":"Vilket körkort kräver fordonet?","rule":"Fordonsslaget avgör vilka behörigheter som kan räcka. Bokstäverna på körkortet anger vilka fordonskategorier och kombinationer föraren får köra.","apply":"Bestäm fordonets verkliga klass, läs körkortets behörigheter och kontrollera giltighet och villkor. För moped klass I räcker AM.","pitfall":"En registrering som moped eller A-traktor avgör inte ensam vilken behörighet en ändrad konstruktion kräver.","sources":["Trafikjuridik 4, bild 25–28","RäV 2023:20 Mopeder, avsnitt 2–4"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l3","l8","l9"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"2 kap. 2 §","title":"Traktor a och motorredskap klass II på väg","rule":"För traktor a med gummihjul och motorredskap klass II gäller på väg krav på gällande körkort eller traktorkort, med ett begränsat undantag för exempelvis kort färd mellan en gårds ägor.","apply":"Pröva fordonstyp, färdväg och det verkliga syftet. Ett giltigt AM-körkort kan räcka för A-traktor.","pitfall":"En kort privat nöjestur uppfyller inte undantaget bara för att sträckan är kort.","sources":["A-traktorer, bild 10–13","Tentamen Polisiärt arbete i trafik, fråga om A-traktor"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l9"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"2 kap. 3 och 7 b §§ samt övergångsbestämmelser","title":"Moped klass II, snöskoter och terränghjuling","rule":"Moped klass II får köras med förarbevis, körkort eller traktorkort. För snöskoter och terränghjuling krävs normalt rätt förarbevis. Äldre behörigheter kan ge fortsatt rätt.","apply":"Kontrollera om personen fyllde 15 före 1 oktober 2009 för klass II. För terrängfordonen kontrolleras bland annat om körkort eller traktorkort utfärdats före 1 januari 2000.","pitfall":"Moped klass I har andra behörighetskrav. Äldre traktorkort kan omfattas av en egen övergångsregel.","sources":["RäV 2023:20 Mopeder, avsnitt 3","Vecka 3, facit uppgift 11"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l9","l13"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"2 kap. 5 och 7 a §§","title":"B, utökad B och släp","rule":"Med B får man dra ett lätt släp. Ett släp med totalvikt högst 750 kg är lätt även om summan av totalvikterna överstiger 3 500 kg. För tyngre släp gäller som huvudregel högst 3 500 kg sammanlagd totalvikt med B, upp till 4 250 kg med utökad B.","apply":"I vecka 5 har bilen totalvikt 2 620 kg och släpet 1 300 kg. Summan 3 920 kg kräver minst utökad B i det fallet. Kontrollera därefter bilens draggränser.","pitfall":"Ett tomt släp har kvar samma totalvikt. Bruttovikten kan däremot ändras.","sources":["Vecka 5, facit uppgift 8"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l3"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"2 kap. 12 §","title":"Kort förflyttning i tjänsten","rule":"En polisman med behörighet B får i tjänsteutövningen köra varje slag av körkortspliktigt fordon en kortare sträcka.","apply":"Beskriv vilken uppgift som kräver förflyttningen och varför just den sträckan behövs.","pitfall":"Bestämmelsen ger ingen generell rätt att köra alla slags tjänstefordon.","sources":["Trafikjuridik 4, bild 28"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l11"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"3 kap. 1, 10, 13 och 19 §§","title":"Ålder, villkor och giltighet","rule":"Kapitlet reglerar utfärdande, individuella villkor, ogiltighet och förarbevis. Körkort kan exempelvis kräva synhjälpmedel eller en särskilt utrustad bil.","apply":"Läs villkorskoden, utred vad den innebär för just det fordonet och kontrollera giltighet vid färdtillfället.","pitfall":"Skilj personens ålder för att få behörigheten från åldern för övningskörning.","sources":["Trafikjuridik 4, bild 26, 34, 37","RäV 2023:20 Mopeder, avsnitt 3"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l3"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"3 kap. 15 och 15 a §§ samt 9 kap. 2 och 2 a §§","title":"Körkort glömt hemma","rule":"Den som kör ska ha med körkortet och på begäran visa det. För nyutfärdat, ännu ej utlämnat körkort finns ett tidsbegränsat alternativ med identitetshandling. För övningskörning finns särskilda identitetskrav.","apply":"Pröva skyldigheten först och därefter straffrihetsgrunderna i 9 kap. 2 §. Om förarens identitet genast kan fastställas ska glömt körkort inte leda till straff.","pitfall":"Glömd handling och avsaknad av körbehörighet är olika frågor.","sources":["Trafikjuridik 4, bild 32, 40–42","Vecka 3, facit uppgift 6"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l11"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"4 kap. 1–2 och 5–8 §§","title":"Elevens förutsättningar vid övningskörning","rule":"Behörighetsslag och utbildningsform avgör elevens åldersgräns och kraven på tillstånd och uppsikt. För personbil utan släp är huvudgränsen 16 år.","apply":"Kontrollera elevens ålder och tillstånd, vem som har uppsikt samt att övningen omfattas av handlingarna.","pitfall":"Elevens körkortstillstånd, identitetshandling och handledarens godkännande har skilda funktioner.","sources":["Trafikjuridik 4, bild 30–31","Vecka 3, facit uppgift 13"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l11"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"5 kap. 1, 3, 4 och 9 §§","title":"Återkallelse, varning och alkolås","rule":"Återkallelse kan följa bland annat av rattfylleri, grov vårdslöshet, vissa allvarliga eller upprepade trafiköverträdelser och medicinsk olämplighet. Varning kan bli aktuell i lagens särskilda fall.","apply":"Välj först den punkt i 3 § som stämmer med händelsen. Bedöm sedan om de särskilda reglerna om begränsning eller varning blir aktuella.","pitfall":"Transportstyrelsens prövning av körkortet är skild från straffansvaret.","sources":["Trafikjuridik 4, bild 34–37","Vecka 3, facit uppgift 7"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l4"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"5 kap. 7 §","title":"När körkortet ska omhändertas","rule":"Lagen anger fyra grunder, bland andra tydliga påverkanstecken, sannolik återkallelse enligt vissa uppräknade grunder och bristande körförmåga på grund av sjukdom eller skada.","apply":"Ange den tillämpliga punkten och de iakttagelser som bär den. Möjligheten att medge körning under 48 timmar gäller endast fall enligt 5 kap. 3 § 4.","pitfall":"Ett positivt sållningsprov räcker inte i sig för slutsatsen att rekvisitet tydliga tecken är uppfyllt.","sources":["Trafikjuridik 4, bild 37","Trafik som metod, bild 10–12"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l4","l8","l11"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"5 kap. 8 §","title":"Hindra fortsatt färd vid körkortsöverträdelse","rule":"En polisman ska hindra fortsatt färd när ett fordon körs i strid med körkortsreglerna och fortsatt färd kan innebära påtaglig fara för trafiksäkerheten eller svåra problem på annat sätt.","apply":"Beskriv både överträdelsen och den konkreta följden av fortsatt färd.","pitfall":"Det krävs mer än att föraren har glömt körkortet hemma.","sources":["Trafikjuridik 4, bild 42"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l10"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"5 kap. 13–15 b §§ och 7 kap. 8 §","title":"Körning efter körkortsingripande","rule":"Bestämmelserna reglerar förutsättningar för nytt körkort efter återkallelse och när beslut får verkan.","apply":"Kontrollera beslut, delgivning, eventuell spärrtid och faktisk behörighet på kördagen.","pitfall":"Utgången spärrtid innebär inte ensam att en ny behörighet har utfärdats.","sources":["RäV 2024:3 Olovlig körning, avsnitt om återkallelse"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l3","l8"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"6 kap. 1–2 och 7 §§","title":"Utländska körkort i Sverige","rule":"Kontrollera giltigheten i utfärdandelandet, behörighet, eventuell svensk återkallelse och folkbokföringstid. För tredjelandskörkort finns som huvudregel en ettårsgräns och särskilda undantag.","apply":"För en förare från Förenade kungariket eller Färöarna gäller särskilda regler om fortsatt användning efter ett år. En pågående ansökan enligt 7 § påverkar också bedömningen enligt 2 §.","pitfall":"Möjligheten att byta ut ett körkort är en separat fråga. Kontrollera även eventuella krav på översättning och fotografi.","sources":["Trafikjuridik 4, bild 38–39"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l11"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"9 kap. 4 §","title":"Hitta ansvar för obehörig körning","rule":"Bestämmelsen hänvisar till trafikbrottslagen för ansvar vid körning utan rätt behörighet och tillåtande av sådan körning.","apply":"Använd KKL för själva behörighetskravet och pröva därefter rekvisiten i 3 § trafikbrottslagen.","pitfall":"En objektiv avvikelse mellan körkort och fordon avgör inte automatiskt skuldfrågan.","sources":["Trafikjuridik 4, bild 40–42"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l3","l8"]},{"law":"KKF","name":"Körkortsförordning (1998:980)","ref":"1 kap. 2 § och 3 kap., särskilt 9 §","title":"Utfärdande, körkortstillstånd och villkor","rule":"Körkortsförordningen utvecklar reglerna om bland annat körkortstillstånd, förarprov och villkor för innehavet.","apply":"Slå upp vad ett krav på särskild utrustning eller viss typ av fordon betyder innan du bedömer en avvikelse.","pitfall":"Ett körkortstillstånd är inte ett färdigt körkort.","sources":["Trafikjuridik 4, bild 29, 34","RäV 2024:3 Olovlig körning, avsnitt om villkor"],"url":"https://data.riksdagen.se/dokument/sfs-1998-980.html","units":["l3","l8"]},{"law":"KKF","name":"Körkortsförordning (1998:980)","ref":"4 kap. 5–9 §§ och 9 kap. 3 §","title":"Vem är förare vid privat övningskörning?","rule":"Vid övningskörning i personbil sitter handledaren bredvid eleven och anses som förare. Övningskörningen ska anges på lämpligt sätt och beviset om handledargodkännande ska medföras.","apply":"I Anna-och-Kalle-fallet bedöms föraransvaret utifrån vem som har uppsikt. Pröva varje skyldighet mot den särskilda ansvarsregeln.","pitfall":"Ett vanligt privat handledargodkännande gäller en viss elev. Samma handledare kan ha flera godkännanden.","sources":["Trafikjuridik 4, bild 30","Vecka 3, facit uppgift 13","RäV 2023:18 Vårdslöshet i trafik, avsnitt om övningskörning"],"url":"https://data.riksdagen.se/dokument/sfs-1998-980.html","units":["l4","l8"]},{"law":"KKF","name":"Körkortsförordning (1998:980)","ref":"5 kap. 2–3 och 8 §§","title":"Handläggning av körkortsingripanden","rule":"Transportstyrelsen kan utreda lämpligheten och begära läkarintyg. Omhändertagande av körkort ska hanteras skyndsamt och beslutet delges.","apply":"Skilj polisens omedelbara åtgärd från myndighetens fortsatta körkortsärende.","pitfall":"En begäran om medicinsk utredning är inte i sig ett återkallelsebeslut.","sources":["Trafikjuridik 4, bild 35–37"],"url":"https://data.riksdagen.se/dokument/sfs-1998-980.html","units":["l8","l11"]},{"law":"LDEF","name":"Lag om vägtrafikdefinitioner (2001:559)","ref":"2 §","title":"Fordonets kategori bestämmer nästa lagrum","rule":"Här definieras bland annat moped, motorcykel, traktor, motorredskap, släpfordon och efterfordon. Moped klass II har särskilda kriterier för effekt och konstruktion.","apply":"Jämför tekniska uppgifter, godkännande och faktiska egenskaper med definitionen. För äldre 30-mopeder måste även övergångsregler beaktas.","pitfall":"Uppmätt fart på en enskild sträcka är inte ensam bevis för att en godkänd moped har ändrats till motorcykel.","sources":["RäV 2023:20 Mopeder, avsnitt 2–4","A-traktorer, bild 10, 41, 44"],"url":"https://data.riksdagen.se/dokument/sfs-2001-559.html","units":["l3","l9","l13"]},{"law":"LDEF","name":"Lag om vägtrafikdefinitioner (2001:559)","ref":"2 §, viktbegreppen","title":"Totalvikt, tjänstevikt, maximilast och bruttovikt","rule":"Totalvikten är ett registrerat värde. Bruttovikten beskriver vad fordonets hjul eller motsvarande faktiskt överför till vägbanan vid ett visst tillfälle.","apply":"Använd registrerade totalvikter för släpbehörighet. Använd de faktiska vikterna för att bedöma last och kontrollera de fordons- och väggränser som gäller i fallet.","pitfall":"Maximilast är skillnaden mellan totalvikt och tjänstevikt. Bruttovikten kan därför ändras utan att körkortskravet ändras.","sources":["Vecka 5, facit uppgift 8"],"url":"https://data.riksdagen.se/dokument/sfs-2001-559.html","units":["l8"]},{"law":"FDEF","name":"Förordning om vägtrafikdefinitioner (2001:651)","ref":"2 §","title":"Är platsen väg eller terräng?","rule":"Väg omfattar bland annat en plats som allmänt används för trafik med motorfordon och vissa leder eller banor för annan trafik. Terräng är ett område som inte är väg.","apply":"Beskriv plats och faktisk användning. Bedöm därefter om regeln i fallet gäller på väg, i terräng eller på båda.","pitfall":"Privat ägande innebär inte automatiskt att en plats är terräng.","sources":["Trafikjuridik 4, bild 19, 23","Vecka 3, facit uppgift 11"],"url":"https://data.riksdagen.se/dokument/sfs-2001-651.html","units":["l13","l7"]},{"law":"FoL","name":"Fordonslag (2002:574)","ref":"2 kap. 2, 6–7 och 9 §§","title":"Typgodkännande, registreringsbesiktning och kontrollbesiktning","rule":"Typgodkännande gäller en fordonstyp. Registreringsbesiktning fastställer bland annat fordonets tekniska identitet och registeruppgifter. Kontrollbesiktning följer upp trafiksäkerhet och miljö. Mopedbesiktning avser klass II.","apply":"Välj kontroll utifrån frågan. En ombyggnad kan kräva registreringsbesiktning även när senaste kontrollbesiktningen är godkänd.","pitfall":"Förutsättningarna för att ta moped klass II i bruk finns i FoF 2 kap. 2 §.","sources":["Trafikjuridik 4, bild 4–6","RäV 2023:20 Mopeder, avsnitt 6.1 och 6.4"],"url":"https://data.riksdagen.se/dokument/sfs-2002-574.html","units":["l9","l10"]},{"law":"FoL","name":"Fordonslag (2002:574)","ref":"2 kap. 10–11 §§","title":"Flygande inspektion och annan kontroll","rule":"Flygande inspektion kräver särskild behörighet. Varje polisman får vid anledning att anta en brist utföra den kontroll som uppenbart behövs för trafiksäkerheten.","apply":"Förklara vad som väckte misstanken, vad som kan konstateras och när fördjupad teknisk bedömning behöver göras av en behörig person.","pitfall":"En vanlig fordonskontroll ger inte varje polisman befogenhet att besluta om alla åtgärder vid flygande inspektion.","sources":["Vecka 3, facit uppgift 10","A-traktorer, bild 34–35"],"url":"https://data.riksdagen.se/dokument/sfs-2002-574.html","units":["l10","l11","l9"]},{"law":"FoL","name":"Fordonslag (2002:574)","ref":"2 kap. 12–14 §§","title":"Last, färdskrivare och taxameter","rule":"Lagen skiljer lastkontroll från särskilda vägkontroller av färdskrivare och taxameter. För de senare kontrollerna anges särskilda förutsättningar och behörigheter.","apply":"Bestäm vad som ska kontrolleras och läs vilka förrättningsmän respektive kontroll omfattar.","pitfall":"Att ett fordon används yrkesmässigt avgör inte ensamt vilken kontrollbestämmelse som gäller.","sources":["Trafikjuridik 4, bild 9","Trafik som metod, bild 33–35"],"url":"https://data.riksdagen.se/dokument/sfs-2002-574.html","units":["l10","l11"]},{"law":"FoL","name":"Fordonslag (2002:574)","ref":"3 kap. 1, 3 och 4 §§","title":"Omfattningen av en fordonskontroll","rule":"Kontrollen ska orsaka så liten olägenhet som ändamålet medger. Lagen reglerar tillträde till fordon och slutna fordonsutrymmen samt möjlighet till provkörning i samband med kontrollen.","apply":"Ange den lagliga kontrollen och hur den valda åtgärden behövs för att bedöma fordonet.","pitfall":"Tillträde för fordonskontroll ger inte fristående stöd för att leta efter föremål för en brottsutredning.","sources":["A-traktorer, bild 34"],"url":"https://data.riksdagen.se/dokument/sfs-2002-574.html","units":["l9","l10","l11"]},{"law":"FoL","name":"Fordonslag (2002:574)","ref":"5 kap. 3 §","title":"Fordonsbrist och fortsatt färd","rule":"Om bristen upptäcks vid kontroll enligt 2 kap. 10, 11 eller 13 § hänvisar fordonslagen till klampningslagen för hindrande av fortsatt färd.","apply":"Knyt den identifierade bristen till kontrolltypen och pröva sedan villkoren i 7 § klampningslagen.","pitfall":"En fordonsbrist leder inte automatiskt till klampning.","sources":["Trafikjuridik 4, bild 9–11","A-traktorer, bild 37"],"url":"https://data.riksdagen.se/dokument/sfs-2002-574.html","units":["l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"2 kap. 1 § och 8 kap. 9–10, 16 §§","title":"Utrustningsbrist och vem som ansvarar","rule":"Fordon ska vara säkra och lämpliga för trafik. Transportstyrelsens föreskrifter preciserar utrustningskraven. Ägaren kan svara för underlåtenhet att hindra brukandet. För annan förare krävs kännedom om hindret.","apply":"För en trasig lykta: identifiera fordon och föreskrift, dokumentera felet och utred vad ägaren gjort respektive vad föraren kände till. Pröva undantagen i 8 kap. 10 §.","pitfall":"En fungerande men släckt lykta kan aktualisera en handlingsregel i TrF i stället för en utrustningsbrist.","sources":["Trafikjuridik 4, bild 12–16","Vecka 5, facit uppgift 10"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l10","l6"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"2 kap. 2 §, 3 kap. 1, 9, 24, 26 och 33 §§ samt 4 kap. 35 §","title":"Mopedens godkännande, märkning och handlingar","rule":"För klass II finns två vägar till brukande: giltigt typgodkännande med föreskriven märkning och intyg, eller godkänd mopedbesiktning. Ändrade fordon kan behöva ny mopedbesiktning.","apply":"Jämför mopedens egenskaper med intyget och kontrollera vilken godkännandeform som åberopas. Bedöm äldre svenska typintyg enligt övergångsreglerna.","pitfall":"I avsnitt 6.4 i kursens mopedvägledning står FoL vid kravet för att ta mopeden i bruk. Rätt hänvisning är FoF 2 kap. 2 §.","sources":["RäV 2023:20 Mopeder, avsnitt 6.1–6.6"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l9","l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"4 kap. 20 § och 8 kap. 8 §","title":"Registreringsbesiktning efter en ändring","rule":"När fordonet ändrats så att det omfattas av 4 kap. 20 § ska ägaren låta registreringsbesiktiga det inom föreskriven tid. Huvudfristen är en månad från ändringen.","apply":"Jämför registeruppgifterna med fordonet och fastställ när ändringen gjordes. Om fordonet var avställt ska besiktningen ske inom en vecka efter att avställningen upphörde, med förbehåll för lagens undantag.","pitfall":"Tidpunkten när bristen första gången upptäcks är inte nödvändigtvis ändringsdagen.","sources":["A-traktorer, bild 13","Vecka 5, facit uppgift 2"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l9","l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"6 kap. 3 och 5–9 §§","title":"När ska fordonet kontrollbesiktigas?","rule":"För vanlig lätt personbil är huvudföljden 36 månader till första besiktning, 24 månader till nästa och sedan högst 14 månader räknat från relevant månad. Andra kategorier har egna intervall.","apply":"Ta fram kategori, vikt, första datum i trafik och senaste fullständiga kontrollbesiktning. Läs undantagen för fordonets ålder och användning.","pitfall":"Årsmodell eller registreringsnumrets slutsiffra räcker inte för att räkna ut sista besiktningsdag.","sources":["Trafikjuridik 4, bild 5–6","Vecka 2, facit uppgift 1"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"6 kap. 12 och 15–17 §§","title":"Hur uppstod körförbudet?","rule":"Körförbud kan inträda efter utebliven periodisk besiktning eller ett obesvarat föreläggande. Vid så allvarliga brister att användning innebär uppenbar fara ska besiktningsorganet meddela körförbud.","apply":"Läs registerstatus och protokoll. Skilj tidsfristens utgång från en uttrycklig bedömning av omedelbar fara.","pitfall":"Ett underkänt fordon har inte alltid omedelbart körförbud. Kontrollera fristen och den faktiska beslutstypen.","sources":["Trafikjuridik 4, bild 5–8","Vecka 3, facit uppgift 9"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"6 kap. 20–21 §§","title":"Vilken färd är fortfarande tillåten?","rule":"Här regleras följden av utebliven registreringsbesiktning efter föreläggande, hur körförbud upphör och snäva undantag för färd till besiktning eller verkstad.","apply":"Identifiera förbudets paragraf och resans mål. För förbud enligt 16 § finns inget allmänt undantag för verkstadsfärd. Kontrollera också säkerhetskraven i 2 kap. 1 §.","pitfall":"21 § har en särskild regel för olastat släp med bromsbrist. Den får inte överföras till en personbil.","sources":["Trafikjuridik 4, bild 7–8","Vecka 3, facit uppgift 9","Vecka 5, facit uppgift 7"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l10"]},{"law":"FoF","name":"Fordonsförordning (2009:211)","ref":"6 kap. 25–28 och 32 §§","title":"Åtgärd efter flygande inspektion","rule":"Ringa, enkla och allvarligare brister har olika följder. Uppenbar fara kräver meddelat körförbud. Ett föreläggande kan leda till körförbud när fristen löpt ut.","apply":"Läs beslutet och välj den bestämmelse som gäller just flygande inspektion. Beakta den särskilda färdregeln för körförbud efter sådan inspektion.","pitfall":"Ett tidigare verkstadsbesök visar inte i sig att ett föreläggande har följts eller att förbudet upphört.","sources":["Vecka 5, facit uppgift 7","Trafikjuridik 4, bild 8–9"],"url":"https://data.riksdagen.se/dokument/sfs-2009-211.html","units":["l10"]},{"law":"LFRA","name":"Lag om fordons registrering och användning (2019:370)","ref":"5–6 och 23 §§","title":"Måste fordonet vara registrerat?","rule":"Lagen anger vilka fordon som måste vara registrerade för att användas och räknar upp undantag. Moped klass I är som huvudregel registreringspliktig, klass II är det inte.","apply":"Identifiera kategorin och användningen, pröva eventuellt undantag och därefter ansvaret enligt 23 §.","pitfall":"Registreringsplikt och skyldigheten att visa läsbar skylt är två olika frågor.","sources":["Trafikjuridik 4, bild 43–45","RäV 2023:20 Mopeder, avsnitt 3"],"url":"https://data.riksdagen.se/dokument/sfs-2019-370.html","units":["l9","l10"]},{"law":"LFRA","name":"Lag om fordons registrering och användning (2019:370)","ref":"10–11 och 23 §§","title":"Körning med avställt fordon","rule":"Avställda fordon får bara användas i angivna fall. När ägaren själv ställt av fordonet finns ett begränsat undantag för kortaste lämpliga väg till eller från närmaste besiktningsorgan. Saluvagnslicens har egna villkor.","apply":"Kontrollera orsaken till avställningen, färdens syfte och om ett skatte- eller avgiftsrelaterat användningsförbud skulle ha gällt. Pröva försäkringsplikten separat.","pitfall":"Ett bokat verkstadsbesök är inte detsamma som en besiktning enligt undantaget.","sources":["Trafikjuridik 4, bild 43–46","Vecka 5, facit uppgift 6"],"url":"https://data.riksdagen.se/dokument/sfs-2019-370.html","units":["l10"]},{"law":"FFRA","name":"Förordning om fordons registrering och användning (2019:383)","ref":"3 kap. 5–7 §§ och 12 kap. 1 §","title":"Registreringsskylt saknas eller är oläslig","rule":"Reglerna anger kravet på skylt, placeringen och att skylten ska kunna avläsas under färd. Ansvarsbestämmelsen hänvisar till de enskilda skyldigheterna. Otillåtna tecken och märken får inte sättas fast på skylten.","apply":"Beskriv om skylten saknas, är skymd eller är i dåligt skick och vad som gjorde den oläsbar. Kontrollera skyltkraven för aktuell fordonstyp. För klistermärket i vecka 7, läs särskilt 3 kap. 7 § tredje stycket.","pitfall":"Ett synligt registreringsnummer på ett löst papper uppfyller inte automatiskt kravet på föreskriven registreringsskylt.","sources":["RäV 2023:20 Mopeder, avsnitt 3","A-traktorer, bild 35","Vecka 7, facit uppgift 3"],"url":"https://data.riksdagen.se/dokument/sfs-2019-383.html","units":["l9","l10","l6"]},{"law":"VTSL","name":"Vägtrafikskattelag (2006:227)","ref":"2 kap. samt 6 kap. 1 och 3–6 §§","title":"Obetald skatt och omhändertagna skyltar","rule":"Huvudregeln är användningsförbud vid obetald, förfallen fordonsskatt. Om fordonet används i strid med förbudet och två månader har gått från sista betalningsdag ska skyltarna tas om hand.","apply":"Kontrollera gammal skatt, eventuellt anstånd, förfallodag, ägare och om skyltarna redan tagits om hand. Föraransvar enligt 6 § kräver kännedom.","pitfall":"Användningsförbudet kan gälla innan tvåmånadersfristen för skyltomhändertagande löpt ut.","sources":["Trafikjuridik 4, bild 46","Vecka 4, facit uppgift 1 och 6"],"url":"https://data.riksdagen.se/dokument/sfs-2006-227.html","units":["l10"]},{"law":"TSL","name":"Trafikskadelag (1975:1410)","ref":"2 och 34–37 §§","title":"Vem måste trafikförsäkra?","rule":"Registrerade påställda motorfordon omfattas som huvudregel även när de står still. Andra motordrivna fordon kan bli försäkringspliktiga när de brukas i trafik. Reglerna skiljer avgift och vite från straff.","apply":"I fallet med avställd oförsäkrad bil: utred vem som var försäkringspliktig och om den personen körde eller tillät färden. För oregistrerad moped kan föraren behöva medföra försäkringsbevis enligt 37 §.","pitfall":"Enligt 36 § träffar straffet den försäkringspliktige under angivna förutsättningar. Föraren ansvarar inte automatiskt för att någon annans fordon är oförsäkrat.","sources":["Trafikjuridik 4, bild 46","RäV 2023:20 Mopeder, avsnitt 3","Vecka 5, facit uppgift 6"],"url":"https://data.riksdagen.se/dokument/sfs-1975-1410.html","units":["l9","l10"]},{"law":"VVFS 2003:19","name":"Vägverkets föreskrifter om bil ombyggd till traktor samt bil ombyggd till motorredskap klass II (VVFS 2003:19)","ref":"4 kap. 1–2, 33 och 35–36 §§","title":"A-traktorns grundläggande egenskaper","rule":"En A-traktor är en ombyggd bil. Den konstruktiva hastigheten får vara högst 30 km/tim på horisontell väg. Villkoren gäller även karosseriet och att fordonet uppenbart inte längre är avsett för person- eller godsbefordran, med angivet undantag för säten.","apply":"Pröva de grundläggande kraven mot fordonets skick och jämför med registreringsuppgifterna. NJA 2023 s. 509 visar varför ändrat användningsområde kan påverka körkortskravet.","pitfall":"Fordonets konstruktiva hastighet och den hastighet som föraren faktiskt höll är skilda bevisfrågor.","sources":["A-traktorer, bild 10–16, 23–25","RäV 2024:3 Olovlig körning, avsnitt om A-traktorer"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/details?RuleNumber=2020%3A46&ruleprefix=TSFS","units":["l9","l3"]},{"law":"VVFS 2003:19","name":"Vägverkets föreskrifter om bil ombyggd till traktor samt bil ombyggd till motorredskap klass II (VVFS 2003:19)","ref":"4 kap. 39, 42–45, 48, 161–164 och 167 §§","title":"Barlast, koppling, ljus, LGF-skylt och sikt","rule":"Föreskriften ställer särskilda krav på bland annat dragfordonets kopplingsanordning, sikt och märkning. Barlastkravet beror på vikt och viktfördelning.","apply":"I fallet med skymd LGF-skylt: slå först upp rätt markeringskrav. Beskriv konkret hur skylten sitter, vad som skymmer den och vilka uppgifter som behöver verifieras.","pitfall":"Varje teknisk brist innebär inte att en A-traktor byter fordonsklass.","sources":["A-traktorer, bild 27–31","VVFS 2003:19, kursbilagan 4 kap."],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/details?RuleNumber=2020%3A46&ruleprefix=TSFS","units":["l9","l10"]},{"law":"TSFS 2020:52","name":"Ändring i Vägverkets föreskrifter om bil ombyggd till traktor samt bil ombyggd till motorredskap klass II (TSFS 2020:52)","ref":"Ändring av 4 kap. 33 § VVFS 2003:19","title":"Äldre krav på lägsta växel","rule":"Ändringen tog bort det äldre särskilda kravet på hastighet vid visst varvtal på lägsta växeln. Kravet på högsta konstruktiva hastighet för A-traktor kvarstod.","apply":"Jämför originalföreskriftens årgång med ändringsföreskriften innan du bedömer kursens äldre exempel.","pitfall":"Ett struket tekniskt krav ska inte användas för att rapportera en nutida överträdelse.","sources":["A-traktorer, bild 16–18"],"url":"https://www.transportstyrelsen.se/TSFS/TSFS%202020_52.pdf","units":["l9"]},{"law":"EPA-kungörelsen","name":"Kungörelse (1940:440) om hänförande av vissa automobiler till fordonstypen motorredskap","ref":"Övergångsbestämmelsen till SFS 1975:45","title":"EPA-traktor i äldre rätt","rule":"Kungörelsen är upphävd. Övergångsbestämmelsen avser tidigare ombyggda fordon som registreringsbesiktigats före 1 april 1975.","apply":"Om ett gammalt fordon kallas EPA, kontrollera registreringen och datumet innan du väljer föreskrift.","pitfall":"Namnet EPA används även om moderna A-traktorer i vardagligt tal.","sources":["A-traktorer, bild 6–10"],"url":"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/rapporter/vagtrafik/uppdrag-utreda-regler-a-traktorer.pdf","units":["l9"]},{"law":"TSFS 2019:134","name":"Upphävande av Vägverkets föreskrifter (VVFS 2003:24) om mopeder och släpvagnar som dras av mopeder (TSFS 2019:134)","ref":"Upphävande av VVFS 2003:24","title":"Vilken mopedföreskrift gäller?","rule":"Föreläsningens äldre hänvisning till VVFS 2003:24 om mopeder och släpvagnar som dras av mopeder avser en upphävd föreskrift.","apply":"Vid utrustningsbrist på moped som tagits i bruk: börja i TSFS 2019:132 och kontrollera tillämplig version och övergångsregler.","pitfall":"Citera inte den äldre numreringen som dagens huvudregel.","sources":["A-traktorer, bild 41–42","RäV 2023:20 Mopeder, avsnitt 3.1"],"url":"https://www.transportstyrelsen.se/TSFS/TSFS%202019_134.pdf","units":["l9","l10"]},{"law":"TSFS 2019:132","name":"Transportstyrelsens föreskrifter och allmänna råd om mopeder som tagits i bruk och släpvagnar till dessa (TSFS 2019:132)","ref":"Utrustning hos mopeder som tagits i bruk","title":"Mopedens bromsar, däck och lyktor","rule":"Föreskriften anger de tekniska krav som gäller för mopeder som tagits i bruk och för släpvagnar till dem.","apply":"Fastställ klass, första brukandedatum och vilken del som brister. Koppla utrustningskravet till ansvar enligt FoF 8 kap. 9 § där förutsättningarna är uppfyllda.","pitfall":"Överför inte en bils krav på däckmönster eller belysning direkt till moped.","sources":["RäV 2023:20 Mopeder, avsnitt 3.1","A-traktorer, bild 41–42"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/details?RuleNumber=2019%3A132&ruleprefix=TSFS","units":["l9","l10"]},{"law":"TSFS 2017:94","name":"Transportstyrelsens föreskrifter och allmänna råd om skyddshjälm (TSFS 2017:94)","ref":"Skyddshjälmens utförande och användning","title":"Hjälm på moped","rule":"Föreskriften ger kompletterande regler om skyddshjälm. Skyldigheten vid själva färden och undantag bedöms i trafikförordningen utifrån fordon och situation.","apply":"Fastställ om det rör sig om vanlig moped, viss trampmoped eller moped med karosseri. Läs den aktuella ordningsbotens gärningsbeskrivning.","pitfall":"RäV 2023:20 tar upp att ledtexten begränsats till underlåtenhet att använda skyddshjälm.","sources":["RäV 2023:20 Mopeder, avsnitt 3.2"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/?RuleNumber=2017%3A94&rulePrefix=TSFS","units":["l9","l7"]},{"law":"TSFS 2009:19","name":"Transportstyrelsens föreskrifter och allmänna råd om användning av däck m.m. avsedda för bilar och släpvagnar som dras av bilar (TSFS 2009:19)","ref":"3 och 8 §§","title":"Vinterdäckens märkning och dubbperiod","rule":"Föreskriften anger hur vinterdäck ska vara märkta eller dubbade. För vanliga personbilar får dubbdäck 16 april–30 september användas bara när rådande eller befarat vinterväglag motiverar det.","apply":"Skilj trafikförordningens krav på vinterdäck från föreskriftens regler om däcktyp och dubb. Dokumentera datum, väglag, däckmärkning och fordonsslag.","pitfall":"Olika fordonskategorier, axlar och släpvagnar kan omfattas av olika villkor och övergångstider.","sources":["Vecka 2, facit uppgift 2","Vecka 3, facit uppgift 5"],"url":"https://www.transportstyrelsen.se/TSFS/TSFS%202009_19k.pdf","units":["l7","l10"]},{"law":"TSFS 2013:63","name":"Transportstyrelsens föreskrifter och allmänna råd om bilar och släpvagnar som dras av bilar (TSFS 2013:63)","ref":"Krav på bilars och släpvagnars utrustning","title":"Trasigt halvljus eller bristfälligt avgassystem","rule":"Föreskriften preciserar tekniska krav, däribland belysning, bromsar och avgassystem. Tillämpningsområdet och tidpunkten då fordonet först togs i bruk styr valet av bestämmelse.","apply":"Börja med bilens första brukandedag och den aktuella utrustningen. För de senare årsgrupperna behöver du också kontrollera TSFS 2016:22.","pitfall":"Böteskoden beskriver gärningen men ersätter inte det tekniska kravet och ansvarsbestämmelsen.","sources":["Vecka 5, facit uppgift 10","Vecka 7, facit om bristfälligt avgassystem"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/?RuleNumber=2013%3A63&rulePrefix=TSFS","units":["l10","l6"]},{"law":"TSFS 2016:22","name":"Transportstyrelsens föreskrifter och allmänna råd om bilar och släpvagnar som dras av bilar och som tas i bruk den 1 juli 2010 eller senare (TSFS 2016:22)","ref":"Bilar och släpvagnar som tas i bruk från 1 juli 2010","title":"Utrustningskrav för senare fordon","rule":"För bilar och deras släpvagnar som tas i bruk den 1 juli 2010 eller senare finns särskilda föreskrifter om beskaffenhet och utrustning.","apply":"I ett fall med trasiga lyktor: fastställ brukandedagen, kontrollera vilket krav som gäller för den aktuella installationen och utred vem som visste om felet.","pitfall":"Tillverkningsåret och första brukandedagen kan skilja sig.","sources":["Vecka 5, facit uppgift 10","Vecka 6, facit om belysning"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/details?RuleNumber=2021%3A111&ruleprefix=TSFS","units":["l10","l6"]},{"law":"TSFS 2019:29","name":"Ändring i Transportstyrelsens föreskrifter och allmänna råd om bilar och släpvagnar som dras av bilar (TSFS 2019:29)","ref":"Ändring i TSFS 2013:63","title":"När facit anger flera föreskriftsnummer","rule":"Detta är en ändringsföreskrift till TSFS 2013:63. Flera hänvisningar i kursens belysningsfall kan alltså avse ändringar i samma grundföreskrift.","apply":"Utgå från grundföreskriften i lydelsen som gällde vid den aktuella färden, och kontrollera om ändringen berör den aktuella utrustningen.","pitfall":"Flera nummer i facit betyder inte automatiskt att flera förseelser ska rapporteras.","sources":["Vecka 6, facit om belysning"],"url":"https://www.transportstyrelsen.se/TSFS/TSFS%202019_29.pdf","units":["l10","l6"]},{"law":"VVFS 2003:22","name":"Vägverkets föreskrifter och allmänna råd om bilar och släpvagnar som dras av bilar (VVFS 2003:22)","ref":"Historisk hänvisning i VVFS 2003:19","title":"Äldre grundföreskrift för bilar","rule":"Kursbilagans äldre lydelse hänvisar till VVFS 2003:22 för vissa krav på ursprungsfordonet. Den föreskriften upphävdes den 1 december 2013 genom TSFS 2013:63.","apply":"Kontrollera om en hänvisning gäller historisk fordonskonstruktion eller dagens bruk och läs aktuella övergångsbestämmelser.","pitfall":"Bilagans tryckår är inte datum för den händelse som ska bedömas.","sources":["VVFS 2003:19, kursbilagan 1 kap. 3 §"],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2010/details?RuleNumber=2010%3A8&ruleprefix=TSFS","units":["l9","l10"]},{"law":"Äldre FoF","name":"Fordonsförordning (2002:925)","ref":"11 kap. 11 § i 2002 års upphävda förordning","title":"Historiskt bemyndigande i A-traktorbilagan","rule":"I ingressen till VVFS 2003:19 står den då gällande fordonsförordningen 2002:925. Den upphävdes 2009 när den nya förordningen trädde i kraft.","apply":"Vid ett nutida kursfall används den aktuella fordonsförordningen 2009:211 och den tekniska föreskriften i tillämplig lydelse.","pitfall":"Hänvisningen förklarar hur föreskriften ursprungligen meddelades. Den är inte en aktuell ansvarsregel.","sources":["VVFS 2003:19, ingressen och 1 kap. 1–2 §§"],"url":"https://data.riksdagen.se/dokument/sfs-2002-925.html","units":["l9","l10"]},{"law":"VVFS 2003:19","name":"Vägverkets föreskrifter om bil ombyggd till traktor samt bil ombyggd till motorredskap klass II (VVFS 2003:19)","ref":"1–3 kap., EG-direktiv och ECE-reglementen","title":"Så läser du bilagans tekniska hänvisningar","rule":"Bilagans ursprungliga lydelse räknar upp rättsakter om bland annat ljus, reflexer och typgodkännande. Hänvisningarna anger tekniska specifikationer, ibland genom flera tidigare ändringar.","apply":"Hitta först komponenten och tillämpligt datum i fordonsföreskriften. I bilagan förekommer ECE-reglementena 1, 3, 4, 5, 6, 7, 8, 19, 20, 27, 31, 37, 38, 69, 91, 112, 113.","pitfall":"EG-hänvisningar i originalbilagan, inklusive tidigare ändringar: 1999/14/EG, 1999/15/EG, 1999/17/EG, 1999/18/EG, 2000/1/EG, 74/150/EEG, 74/151/EEG, 74/152/EEG, 74/346/EEG, 74/347/EEG, 75/321/EEG, 75/322/EEG, 76/432/EEG, 76/757/EEG, 76/758/EEG, 76/759/EEG, 76/760/EEG, 76/761/EEG, 76/762/EEG, 76/763/EEG, 77/311/EEG, 77/537/EEG, 77/538/EEG, 78/764/EEG, 78/933/EEG, 79/532/EEG, 79/533/EEG, 80/720/EEG, 86/297/EEG, 86/415/EEG, 89/173/EEG, 89/277/EEG, 89/516/EEG, 89/517/EEG, 89/518/EEG, 97/29/EG, 97/30/EG, 97/54/EG, 98/34/EG, 98/48/EG. Kontrollera om hänvisningen är historisk innan den används.","sources":["VVFS 2003:19, ingressen samt 2–3 kap."],"url":"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/sok-ts-foreskrifter/details?RuleNumber=2020%3A46&ruleprefix=TSFS","units":["l9"]},{"law":"Äldre vägtrafikregisterförordningen","name":"Förordning om vägtrafikregister (2001:650)","ref":"10 kap. 7 §, äldre hänvisning","title":"Återtagandeförbehåll i äldre kursvägledning","rule":"I vägledningen om förverkande hänvisas till den upphävda vägtrafikregisterförordningen. För nutida ägarbyte finns bestämmelsen om kreditköp med återtagandeförbehåll i FFRA 5 kap. 8 §.","apply":"Läs aktuell förordning för registeruppgiften. Utred vem som äger bilen och vilket anspråk kreditgivaren har i det enskilda fallet.","pitfall":"En registeranteckning avgör inte ensam vem en förverkandetalan kan riktas mot.","sources":["RäV 2023:4 Förverkande, avsnitt 4.1.3"],"url":"https://data.riksdagen.se/dokument/sfs-2001-650.html","units":["l5","l10"]},{"law":"FFRA","name":"Förordning om fordons registrering och användning (2019:383)","ref":"5 kap. 7–10 §§","title":"Ägarbyte, beslag och kreditgivarens anspråk","rule":"Transportstyrelsen får vägra registrering av ägarbyte vid exempelvis beslag. Vid vissa kreditköp ska uppgift om återtagandeförbehåll anges.","apply":"Vid ett påstått ägarbyte nära beslagsdagen: jämför registeranteckningen med tidpunkten, avtalet och andra uppgifter om vem som faktiskt förvärvat fordonet.","pitfall":"Påståenden om köp på avbetalning behöver bedömas även när registrerad ägare är den misstänkte.","sources":["RäV 2023:4 Förverkande, avsnitt 4.1.2–4.1.3"],"url":"https://data.riksdagen.se/dokument/sfs-2019-383.html","units":["l5"]},{"law":"KKL","name":"Körkortslag (1998:488)","ref":"3 kap. 18 §","title":"Prövotid efter förarprovet","rule":"Huvudregeln är ett års prövotid för ny AM-behörighet och två år för övriga behörigheter efter godkänt förarprov. Lagen innehåller också en regel för den som redan har en annan giltig behörighet än AM.","apply":"Jämför dagen för provet, behörighet och gärningsdatum. Om frågan gäller nytt körkort efter återkallelse, läs också 5 kap. 13–15 b §§.","pitfall":"Prövotiden är inte en självständig grund för återkallelse.","sources":["Seminarium Initiala utredningsåtgärder, BMW-fallet"],"url":"https://data.riksdagen.se/dokument/sfs-1998-488.html","units":["l8","l3"]},{"law":"PL","name":"Polislag (1984:387)","ref":"2 § och 8 §","title":"Uppgift, behov och proportionalitet","rule":"2 § beskriver polisens uppgifter. En åtgärd ska vara försvarlig och tvånget begränsat till vad som behövs. En grundlagsskyddad frihet kräver särskilt stöd för en inskränkning.","apply":"Beskriv uppgiften, den konkreta befogenheten och vilken mindre ingripande åtgärd som kan fungera.","pitfall":"Att en åtgärd skulle underlätta arbetet räcker inte som rättslig grund.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.1–1.2 och 4.1"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"9 §","title":"Rapport och rapporteftergift","rule":"Brott under allmänt åtal ska rapporteras så snart det kan ske. Rapporteftergift kan ges om brottet i det enskilda fallet är obetydligt och uppenbart endast skulle ge böter.","apply":"Beskriv vad som gör just den gärningen obetydlig och pröva sedan den väntade påföljden.","pitfall":"Ett bötesbrott uppfyller bara en del av prövningen.","sources":["Trafikjuridik 1, bild 9–10"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l1","l6"]},{"law":"PL","name":"Polislag (1984:387)","ref":"10 §","title":"Våld vid tjänsteåtgärd","rule":"Möjligheten att använda våld beror på vilken laglig tjänsteåtgärd som ska genomföras, om en situation i paragrafen föreligger och om andra medel är otillräckliga. Åtgärden måste vara försvarlig.","apply":"Ange först stödet för själva tjänsteåtgärden. Förklara vilken punkt som aktualiseras och fakta som stöder bedömningen.","pitfall":"Befogenheten att stoppa ett fordon enligt 22 § avgör inte vilka åtgärder som får riktas mot passagerarna.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.1, 1.5 och 1.6"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"11 §","title":"Tillfälligt omhändertagande i väntan på beslut","rule":"När beslut om omhändertagande enligt särskild föreskrift tillkommer Polismyndigheten eller Säkerhetspolisen kan en polisman i väntan på beslut tillfälligt agera om föreskrivna förutsättningar finns och dröjsmål innebär fara för liv eller hälsa eller någon annan fara.","apply":"Namnge den särskilda föreskriften och ange vad en väntan på beslut skulle innebära.","pitfall":"En inre utlänningskontroll ger ingen automatisk rätt att omhänderta personen.","sources":["Polisjuridik med kommentarer (2021), avsnitt 2.2"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11","kontroll-vistelse"]},{"law":"PL","name":"Polislag (1984:387)","ref":"12 §","title":"Barn i omedelbar fara","rule":"Den som kan antas vara under 18 år kan omhändertas vid en uppenbar, överhängande och allvarlig risk för hälsa eller utveckling. Syftet är att skyndsamt överlämna barnet till vårdnadshavare eller socialnämnd.","apply":"Skriv vilken fara barnet befinner sig i nu och till vem barnet ska lämnas.","pitfall":"Oro som utlöser en anmälan enligt SoL kan finnas även när kraven för ett omhändertagande saknas.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11","l14"]},{"law":"PL","name":"Polislag (1984:387)","ref":"13 §","title":"Avvisa, avlägsna eller omhänderta","rule":"Ordningsstörning, omedelbar fara för ordningen eller behov att avvärja en straffbelagd handling kan ge stöd för avvisande eller avlägsnande. Tillfälligt omhändertagande kräver att dessa åtgärder är otillräckliga.","apply":"Beskriv personens eget uppträdande och varför den övervägda åtgärden behövs just då.","pitfall":"Att en åskådare filmar ett ingripande visar inte i sig en ordningsstörning.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.3 och 4"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"13 a–13 c §§ och 24 §","title":"Tillträdesförbud, sammankomster och folksamlingar","rule":"13 a § gäller bland annat överträdelse av ett tillträdesförbud. 13 b § förutsätter beslut om inställande eller upplösning enligt ordningslagen. 13 c § gäller andra folksamlingar som stör ordningen eller innebär omedelbar fara. 24 § gäller områden vid allvarliga ordnings- eller säkerhetsstörningar eller risk för sådana.","apply":"Ange om situationen gäller en enskild person, en sammankomst, en folksamling eller ett särskilt område. Kontrollera vem som beslutar.","pitfall":"På en olycksplats kan räddningsledarens befogenhet enligt LSO 6 kap. 2 § vara den relevanta regeln.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.3"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11","l12"]},{"law":"PL","name":"Polislag (1984:387)","ref":"14 § och 16 § sista stycket","title":"När en okänd person får omhändertas för identifiering","rule":"Identiteten ska vara okänd och det ska finnas särskild anledning att anta att personen är efterspanad eller efterlyst och ska frihetsberövas enligt lag. Personen måste dessutom vägra lämna identitetsuppgift eller kunna antas lämna oriktig uppgift.","apply":"Skriv hur uppgifter om exempelvis en efterlysning knyts till personen och vilket frihetsberövande som ska verkställas. Avsluta omhändertagandet för identifiering så snart identiteten är klarlagd. Ett fortsatt frihetsberövande kräver egen grund.","pitfall":"En vägran att visa legitimation räcker inte på egen hand.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11","kontroll-vistelse"]},{"law":"PL","name":"Polislag (1984:387)","ref":"19 § första stycket 1–2","title":"Visitation efter lagligt ingripande","rule":"Vid ett lagligt gripande, omhändertagande eller avlägsnande får visitation ske i anslutning till ingripandet i den utsträckning som behövs av säkerhetsskäl eller för identifiering.","apply":"Ange grunden för det första ingripandet och varför det angivna syftet kräver visitation.","pitfall":"En vanlig trafikkontroll ger ingen allmän rätt att söka efter en passagerares legitimation.","sources":["Polisjuridik med kommentarer (2021), avsnitt 2 och 3"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11","kontroll-vistelse"]},{"law":"PL","name":"Polislag (1984:387)","ref":"19 § andra stycket och 20 a §","title":"Förebyggande visitation och undersökning av fordon","rule":"Bestämmelserna avser vissa förebyggande ändamål och ställer krav på omständigheterna i det enskilda fallet. För vapen eller andra farliga föremål hänvisar dagens bestämmelser till förverkande enligt BrB 36 kap. 12 §.","apply":"Skilj det förebyggande syftet från en utredning av ett redan begånget brott. Pröva då reglerna i RB 28 kap. för den tänkta åtgärden.","pitfall":"Äldre material kan hänvisa till BrB 36 kap. 3 §. Använd den aktuella hänvisningen i lagtexten.","sources":["Polisjuridik med kommentarer (2021), avsnitt 3.1–3.2"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"22 § 1–4","title":"Stoppa ett fordon","rule":"Paragrafen anger fyra grunder. De rör misstanke om brott, annat lagligt ingripande mot någon som färdas i fordonet, laglig husrannsakan i fordonet samt trafikreglering eller föreskriven kontroll av fordon, förare eller last.","apply":"Vilket var syftet när stoppet beslutades? En rutinmässig körkortskontroll kan exempelvis falla under punkt 4.","pitfall":"Stoppbeslutet behöver följas av ett särskilt lagstöd för varje ytterligare tvångsåtgärd.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.6","A-traktorer, bild 34"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"24 a §","title":"Förhindra en befarad rattfyllerikörning","rule":"Om särskilda skäl visar risk för rattfylleri eller grovt rattfylleri får polisen tillfälligt omhänderta exempelvis fordonsnycklar eller, om det krävs, fordonet för att förhindra färden.","apply":"Beskriv de konkreta omständigheter som knyter risken till en kommande körning och varför åtgärden behövs.","pitfall":"Omhändertagandet har ett förebyggande syfte. Ett beslag för brottsutredning kräver egen prövning.","sources":["Trafikjuridik 2, bild 24"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l4","l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"24 b–24 d §§","title":"Förmansprövning, återlämnande och underrättelse","rule":"Beslutet anmäls skyndsamt och förmannen prövar omedelbart om det ska bestå. Omhändertagandet ska upphöra så snart skälen upphör och får pågå högst 24 timmar. Egendomen ska då som huvudregel återlämnas till den som den omhändertogs från. För ohämtad egendom finns särskilda villkor och underrättelseregler.","apply":"Anteckna beslutstid, förmansprövning, när risken upphörde och vem som ska få tillbaka egendomen.","pitfall":"24 timmar är den längsta tillåtna tiden. Pröva behovet även innan den tiden gått.","sources":["Trafikjuridik 2, bild 24"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l4","l11"]},{"law":"PL","name":"Polislag (1984:387)","ref":"27–28 §§","title":"Dokumentera ingripandet","rule":"27 § anger när protokoll ska föras och vilka uppgifter det ska innehålla. 28 § har särskilda krav bland annat vid användning av tekniska hjälpmedel för att stoppa fordon.","apply":"Anteckna beslutsfattare, grund, tid, deltagare, berörd person och vad som hände. Särskilda protokoll ska innehålla skälen för åtgärden.","pitfall":"Även en förebyggande visitation enligt polislagen omfattas av dokumentationskrav.","sources":["Polisjuridik med kommentarer (2021), avsnitt 3.2.6"],"url":"https://data.riksdagen.se/dokument/sfs-1984-387.html","units":["l11"]},{"law":"UtlL","name":"Utlänningslag (2005:716)","ref":"9 kap. 9 §","title":"Inre utlänningskontroll","rule":"Åtgärden kräver anledning att anta att en utlänning saknar rätt att vistas i Sverige. I bedömningen ska särskild hänsyn tas till iakttagelser på platsen och myndighetens uppgifter. Personen ska då på begäran visa pass eller andra handlingar som styrker vistelserätten.","apply":"Pröva först grunden för fordonsstoppet. Beskriv separat de faktiska uppgifter som motiverar kontrollen av vistelserätten.","pitfall":"Äldre studiestöd återger den tidigare formuleringen om grundad anledning eller särskild anledning till kontroll.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2","Studiehandledning Trafik Distans, kursens innehåll"],"url":"https://data.riksdagen.se/dokument/sfs-2005-716.html","units":["kontroll-vistelse","l11"]},{"law":"LAU","name":"Lag (1976:1090) om alkoholutandningsprov","ref":"1 §","title":"Alkoholutandningsprov vid skälig misstanke","rule":"Vid skälig misstanke om något av de angivna brotten, eller annat brott där fängelse kan följa, får prov tas om det kan ha betydelse för utredningen.","apply":"Ange vilken omständighet som knyter personen till brottet och varför provet behövs i utredningen.","pitfall":"Använd 2 § när frågan i stället gäller ett rutinmässigt sållningsprov.","sources":["Trafikjuridik 2, bild 13","Hantera trafikolycka, bild 14–15"],"url":"https://data.riksdagen.se/dokument/sfs-1976-1090.html","units":["l4","l11","l12"]},{"law":"LAU","name":"Lag (1976:1090) om alkoholutandningsprov","ref":"2 §","title":"Sållningsprov vid trafikkontroll","rule":"En förare av motordrivet fordon kan lämna utandningsprov utan föregående brottsmisstanke. Fordon avsedda att föras av gående är undantagna. Instrumentet ska endast ange om alkoholhalten överstiger ett gränsvärde.","apply":"Kontrollera att personen tillhör rätt förarkategori och att provet tas på eller nära kontrollplatsen.","pitfall":"Ett positivt sållningsprov utvisar inte den exakta alkoholkoncentrationen.","sources":["Trafikjuridik 2, bild 13","Hantera trafikolycka, bild 14–15"],"url":"https://data.riksdagen.se/dokument/sfs-1976-1090.html","units":["l4","l11","l12"]},{"law":"LAU","name":"Lag (1976:1090) om alkoholutandningsprov","ref":"3 §","title":"Blodprov vid vägran eller olyckshinder","rule":"Blodprov får tas på en person som är skyldig att lämna prov enligt 2 § och vägrar, eller som inte kan lämna prov för att personen varit inblandad i en trafikolycka.","apply":"Beskriv skyldigheten enligt 2 § och vilken av de två situationerna i 3 § som föreligger.","pitfall":"Olyckan i sig räcker inte. Visa sambandet mellan olyckan och oförmågan att lämna prov.","sources":["Trafikjuridik 2, bild 13","Hantera trafikolycka, bild 14–15"],"url":"https://data.riksdagen.se/dokument/sfs-1976-1090.html","units":["l4","l12"]},{"law":"Ögonundersökningslagen","name":"Lag (1999:216) om ögonundersökning vid misstanke om vissa brott i trafiken","ref":"1–5 §§","title":"Ögonundersökning vid misstanke om trafikbrott","rule":"När det kan misstänkas att föraren begått något av de angivna brotten kan en yttre ögonundersökning göras för att utreda påverkan av annat medel än alkohol. 5 § reglerar blodprov vid vägran eller ett olycksrelaterat hinder.","apply":"Ange förarkategori, misstänkt brott och fakta bakom misstanken. Pröva därefter om det finns grund för ytterligare prov.","pitfall":"1999 års lag gäller parallellt med försökslagen, som har ett annat tillämpningsområde.","sources":["Trafikjuridik 2, bild 25–26","Trafikjuridik 1, bild 7–8"],"url":"https://data.riksdagen.se/dokument/sfs-1999-216.html","units":["l4","l11"]},{"law":"Försökslagen","name":"Lag (2024:1231) om försöksverksamhet med rutinmässiga ögonundersökningar i trafiken","ref":"1–6 §§","title":"Rutinmässig ögonundersökning utan föregående misstanke","rule":"Försökslagen medger yttre ögonundersökning av förare av motordrivet fordon för att upptäcka annan påverkan än alkohol. Undersökningen ska ske avskilt enligt 5 §. I 6 § finns särskilda förutsättningar för blodprov. Lagen är tidsbegränsad till den 1 mars 2030.","apply":"Jämför en rutinmässig kontroll av en bilförare med kontroll vid en redan uppkommen misstanke. Skriv vilken lag som bär ditt beslut.","pitfall":"Ett iakttaget tecken är en uppgift i bedömningen. Det fastställer inte i sig vilket ämne någon har använt.","sources":["Trafikjuridik 2, bild 25–26","Trafikjuridik 1, bild 7–8"],"url":"https://data.riksdagen.se/dokument/sfs-2024-1231.html","units":["l4","l11"]},{"law":"LSO","name":"Lag (2003:778) om skydd mot olyckor","ref":"6 kap. 2–3 §§","title":"Avspärrning vid räddningsinsats","rule":"Räddningsledaren får under en räddningsinsats göra ett försvarligt ingrepp i annans rätt om faran inte lämpligen kan hindras på något annat sätt. Polismyndigheten ska lämna den hjälp som behövs vid ingreppet.","apply":"Skilj räddningsledarens beslut och polisens hjälp enligt LSO från avspärrning för att säkra en brottsutredning.","pitfall":"Olycksplatsens namn avgör inte lagstödet. Utgå från syftet med just avspärrningen.","sources":["Hantera trafikolycka, bild 24–25"],"url":"https://data.riksdagen.se/dokument/sfs-2003-778.html","units":["l12"]},{"law":"HSL","name":"Hälso- och sjukvårdslag (2017:30)","ref":"7 kap. 6 §","title":"Sjuktransport i trafikreglernas undantag","rule":"Regionen ska organisera transport till och från vård för personer vars tillstånd kräver särskilt inrättade transportmedel. Trafikförordningen hänvisar till dessa transporter i vissa undantag.","apply":"Sök i TrF efter den trafikregel och det undantag som frågan gäller. Använd HSL för att förstå vilken sjuktransport som avses.","pitfall":"HSL-paragrafen ger inte ensam rätt att åsidosätta en trafikregel.","sources":["Trafikjuridik 3, bild 18, 22–23"],"url":"https://data.riksdagen.se/dokument/sfs-2017-30.html","units":["l7","l12"]},{"law":"SoL","name":"Socialtjänstlag (2025:400)","ref":"19 kap. 1 §","title":"Orosanmälan när ett barn kan fara illa","rule":"Polismyndigheten och dess anställda ska genast anmäla till socialnämnden när de i verksamheten får kännedom om eller misstänker att ett barn far illa.","apply":"Beskriv vilka iakttagelser om barnet eller dess situation som väckte oro, till exempel efter en rattfyllerikontroll.","pitfall":"Strategin från 2016 anger 14 kap. 1 § i den upphävda socialtjänstlagen (2001:453). Nu gäller 19 kap. 1 § i SoL (2025:400).","sources":["Polismyndighetens strategi för trafik som metod, barnperspektivet","Nationella strategier, bild 2"],"url":"https://data.riksdagen.se/dokument/sfs-2025-400.html","units":["l14","l4"]},{"law":"LOB","name":"Lag (1976:511) om omhändertagande av berusade personer m.m.","ref":"1–3 §§","title":"Skyddsbehov vid berusning","rule":"Berusningen ska innebära att personen inte kan ta hand om sig eller annars utgör fara för sig själv eller annan. Den som anträffas i sin egen eller någon annans bostad får inte omhändertas enligt 1 §. Läkarundersökning ska ordnas när tillståndet kräver det.","apply":"I övningen Kissaren behöver frågan om personens skyddsbehov bedömas för sig, utifrån personens tillstånd och platsen.","pitfall":"Berusning i sig uppfyller inte rekvisiten. Ett omhändertagande är en skyddsåtgärd.","sources":["Övningstentamen trafik med facit, Kissaren","Polisjuridik med kommentarer (2021), avsnitt 2.2"],"url":"https://data.riksdagen.se/dokument/sfs-1976-511.html","units":["l6","l11"]},{"law":"RF","name":"Kungörelse (1974:152) om beslutad ny regeringsform","ref":"2 kap. 15 § sista stycket","title":"Allemansrätten vid terrängkörning","rule":"Grundlagen slår fast tillgången till naturen enligt allemansrätten. Motortrafik kräver en egen bedömning enligt bland annat terrängkörningslagen.","apply":"Pröva fordon, terräng, underlag, eventuellt undantag och lokala regler när scenariot gäller en motoriserad utflykt.","pitfall":"Markägarens samtycke kan inte ensamt sätta terrängkörningslagens förbud ur spel.","sources":["Trafikjuridik 4, avsnitt Allemansrätten"],"url":"https://data.riksdagen.se/dokument/sfs-1974-152.html","units":["l13"]},{"law":"RF","name":"Kungörelse (1974:152) om beslutad ny regeringsform","ref":"1 kap. 9 § och 2 kap. 6 §","title":"Saklighet och skydd mot kroppsliga ingrepp","rule":"Myndigheter ska iaktta saklighet och opartiskhet. Regeringsformen skyddar var och en gentemot det allmänna mot bland annat kroppsvisitation och påtvingade kroppsliga ingrepp.","apply":"Ange de objektiva omständigheter som stöder åtgärden och det särskilda lagrum som tillåter ingreppet.","pitfall":"Det är en skillnad mellan att frivilligt visa legitimation och att utsättas för en tvångsåtgärd.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.1 och 2 (grundlagsbakgrund)"],"url":"https://data.riksdagen.se/dokument/sfs-1974-152.html","units":["l11","kontroll-vistelse"]},{"law":"VapenL","name":"Vapenlag (2026:408)","ref":"18 kap. 1–2 §§","title":"Vapenbrott och grovt vapenbrott","rule":"För ett påstående om olovligt innehav måste både innehavet och avsaknaden av rätt till innehavet prövas för varje person. Vid gradindelningen vägs omständigheterna samman. Platsen och ett innehav i fordon på sådan plats kan ha särskild betydelse.","apply":"I övningen Drograttfyllan: skilj förarens befattning med föremålet från passagerarens och pröva sedan eventuell medverkan särskilt.","pitfall":"Facit hänvisar till den äldre vapenlagen (1996:67), 9 kap. 1 a §. Använd gärningstidpunkten när du väljer rätt lydelse.","sources":["Övningstentamen trafik med facit, Drograttfyllan","Polisjuridik med kommentarer (2021), avsnitt 3.2.2","Uppgift inför seminarium, fall 3 Tjuvarna"],"url":"https://data.riksdagen.se/dokument/sfs-2026-408.html","units":["l4","l11"]},{"law":"Knivlagen","name":"Lag (1988:254) om förbud beträffande knivar och andra farliga föremål","ref":"1 och 4 §§","title":"Kniv i fordon på allmän plats","rule":"Förbudet omfattar bland annat knivar och vissa andra farliga föremål i fordon på allmän plats. Ett innehav kan vara befogat utifrån föremålets art, innehavarens behov och övriga omständigheter. 4 § reglerar straffansvaret.","apply":"Jämför till exempel ett arbetsredskap som behövs för ett visst arbete med ett föremål utan redovisat brukssyfte. Beskriv hela situationen.","pitfall":"Att föremålet ligger i en bil avgör varken om platskravet är uppfyllt eller om innehavet är obefogat.","sources":["Trafikjuridik 1, bild 15","Polisjuridik med kommentarer (2021), avsnitt 3.2.2"],"url":"https://data.riksdagen.se/dokument/sfs-1988-254.html","units":["l11"]},{"law":"NSL","name":"Narkotikastrafflag (1968:64)","ref":"1–2 §§ och 8 §","title":"Narkotikabrott, ringa brott och substansbegreppet","rule":"1 § omfattar bland annat olovligt innehav eller bruk av narkotika. 2 § behandlar ringa brott. I TBL 4 § andra stycket används 8 § NSL för att avgöra vad som räknas som narkotika.","apply":"Pröva bruk eller innehav separat från framförandet av fordonet. Vid drograttfylleri ska du också beakta undantaget för intag enligt behörig receptutfärdares ordination.","pitfall":"Ett fynd hos en passagerare säger inte i sig vad som fanns i förarens blod vid körningen.","sources":["Trafikjuridik 1, bild 7 och 15","Trafikjuridik 2, bild 4"],"url":"https://data.riksdagen.se/dokument/sfs-1968-64.html","units":["l4","l11"]},{"law":"Alkoholförverkandelagen","name":"Lag (1958:205) om förverkande av alkohol m.m.","ref":"1 §","title":"Förverkande av alkohol vid rattfylleri","rule":"Alkohol eller andra trafikfarliga medel som påträffas hos den som begått angivna trafiknykterhetsbrott ska som huvudregel förverkas. För medel hos en medföljande gäller särskilda villkor.","apply":"Hos vem hittades medlet? Om det tillhörde en medföljande, vad talar för att det även var avsett för den som begick brottet?","pitfall":"Ett beslag under utredningen och ett slutligt förverkande är två skilda beslut.","sources":["Trafikjuridik 2, bild 8"],"url":"https://data.riksdagen.se/dokument/sfs-1958-205.html","units":["l4","l5"]},{"law":"SkL","name":"Skadeståndslag (1972:207)","ref":"2 kap. 1–2 §§ och 3 kap. 2 §","title":"Skadestånd och myndighetsutövning","rule":"Bestämmelserna skiljer mellan person- och sakskada och ren förmögenhetsskada. Det allmännas ansvar vid fel eller försummelse i myndighetsutövning har särskilda förutsättningar.","apply":"I ett ärende om felaktigt hanterat fordonsbeslag: identifiera skadan, orsakssambandet och vems ansvar som prövas.","pitfall":"Skadeståndsreglerna hör till bedömningen av en skada. Grunden för att ta fordonet i beslag söks i andra regler.","sources":["Polisjuridik med kommentarer (2021), avsnitt 1.2","RäV 2023:4, exempel om beslag och skadestånd"],"url":"https://data.riksdagen.se/dokument/sfs-1972-207.html","units":["l5","l11"]},{"law":"TF","name":"Tryckfrihetsförordning (1949:105)","ref":"1 kap. 7 §","title":"Anskaffarfrihet för tryckta medier","rule":"Rätten att anskaffa uppgifter för publicering i tryckt skrift eller för att meddela uppgifter för sådan publicering är grundlagsskyddad inom bestämmelsens ramar.","apply":"När en person dokumenterar ett ingripande, håll isär själva upptagningen, publiceringssyftet och eventuella särskilda begränsningar.","pitfall":"Förkortningen TF här betyder tryckfrihetsförordningen. TrF används i banken för trafikförordningen.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.2"],"url":"https://data.riksdagen.se/dokument/sfs-1949-105.html","units":["l11","l12"]},{"law":"YGL","name":"Yttrandefrihetsgrundlag (1991:1469)","ref":"1 kap. 10 §","title":"Anskaffarfrihet för grundlagsskyddade medier","rule":"Grundlagen skyddar anskaffande och meddelande av uppgifter i de publiceringssyften som bestämmelsen anger, bland annat för program och tekniska upptagningar.","apply":"Pröva ändamålet och typen av medium. Skilj den bedömningen från om någon genom sitt beteende faktiskt hindrar arbetet på platsen.","pitfall":"Att någon filmar ger inte i sig grund för ett ingripande mot filmningen.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.2"],"url":"https://data.riksdagen.se/dokument/sfs-1991-1469.html","units":["l11","l12"]},{"law":"Kamerabevakningslagen","name":"Kamerabevakningslag (2018:1200)","ref":"3 §","title":"Vad omfattas av kamerabevakning?","rule":"Lagen skiljer ut utrustning som används utan att manövreras på platsen för varaktig eller regelbundet upprepad personbevakning. Andra villkor och undantag framgår av lagen.","apply":"Pröva hur kameran manövreras, om personer kan identifieras och hur bevakningen sker innan du bedömer regelverket.","pitfall":"2021 års kompendium nämner även kameraövervakningslagen (2013:460). Den ersattes av kamerabevakningslagen (2018:1200).","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.1"],"url":"https://data.riksdagen.se/dokument/sfs-2018-1200.html","units":["l11","l12"]},{"law":"GDPR","name":"Europaparlamentets och rådets förordning (EU) 2016/679 (allmän dataskyddsförordning)","ref":"Artikel 2.2 d och artikel 5","title":"Personuppgifter i en bild","rule":"En bild av en identifierbar person kan vara en personuppgift. GDPR:s tillämpning beror bland annat på vem som behandlar bilden och varför. Behöriga myndigheters behandling för brottsbekämpande ändamål ligger utanför GDPR enligt artikel 2.2 d.","apply":"Skilj mellan att ta en bild, lagra den i tjänsten och publicera den. Ange vem som behandlar uppgifterna och för vilket ändamål.","pitfall":"Ett foto av en person är inte automatiskt förbjudet att ta eller publicera. Ändamål, sammanhang och tillämpliga undantag spelar roll.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.1–4.2"],"url":"https://eur-lex.europa.eu/legal-content/SV/TXT/?uri=CELEX:32016R0679","units":["l11","l12"]},{"law":"Brottsdatalagen","name":"Brottsdatalag (2018:1177)","ref":"1 kap. 2 §","title":"Personuppgifter i brottsbekämpande verksamhet","rule":"Lagen omfattar behöriga myndigheters behandling för bland annat brottsbekämpning och för att upprätthålla allmän ordning och säkerhet, inom lagens tillämpningsområde.","apply":"Fråga vad polisens insamling eller lagring av bilden ska användas till. Identifiera sedan den kompletterande regleringen för polisen.","pitfall":"Ändamålet har betydelse även när samma myndighet utför flera slags uppgifter.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.1 (aktuell reglering)"],"url":"https://data.riksdagen.se/dokument/sfs-2018-1177.html","units":["l11"]},{"law":"Polisens brottsdatalag","name":"Lag (2018:1693) om polisens behandling av personuppgifter inom brottsdatalagens område","ref":"1 kap. 1–2 §§","title":"Polisens kompletterande dataskyddsregler","rule":"Lagen kompletterar brottsdatalagen för polisens personuppgiftsbehandling inom det område som lagen anger.","apply":"Kontrollera vilken polisiär verksamhet som behandlar uppgifterna och läs lagen tillsammans med brottsdatalagen.","pitfall":"Kompendiets hänvisning till polisdatalagen (2010:361) är historisk. Den ersattes 2019.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.1 (äldre hänvisning)"],"url":"https://data.riksdagen.se/dokument/sfs-2018-1693.html","units":["l11"]},{"law":"Skyddslagen","name":"Skyddslag (2010:305)","ref":"7 § andra stycket","title":"Beslut om avbildningsförbud vid skyddsobjekt","rule":"Ett beslut om skyddsobjekt kan förenas med särskilt förbud mot att göra avbildningar, beskrivningar eller mätningar av eller inom objektet.","apply":"Ta reda på vilket beslut som gäller där bilden togs och exakt vad förbudet omfattar.","pitfall":"En känslig plats har inte automatiskt avbildningsförbud enligt skyddslagen.","sources":["Polisjuridik med kommentarer (2021), avsnitt 4.2, skyddsobjekt (fördjupning)"],"url":"https://data.riksdagen.se/dokument/sfs-2010-305.html","units":["l11","l12"]},{"law":"LVU","name":"Lag (1990:52) med särskilda bestämmelser om vård av unga","ref":"43 §","title":"Handräckning vid vård av unga","rule":"En behörig aktör kan i de situationer som anges i lagen begära hjälp för till exempel att genomföra beslut om vård eller omhändertagande av en ung person.","apply":"Identifiera den bakomliggande åtgärden, vem som begärt hjälp och vad som måste kontrolleras för att rätt person ska beröras.","pitfall":"Kursen nämner lagen som exempel i identitetsfrågan. En hänvisning till handräckning ger inget allmänt stöd för ID-kontroll.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2"],"url":"https://data.riksdagen.se/dokument/sfs-1990-52.html","units":["l11","kontroll-vistelse"]},{"law":"LVM","name":"Lag (1988:870) om vård av missbrukare i vissa fall","ref":"45 §","title":"Handräckning vid vård enligt LVM","rule":"Paragrafen anger vem som kan begära hjälp med bland annat att genomföra vissa undersökningar och transporter vid vård av personer med missbruk.","apply":"Identifiera den bakomliggande åtgärden, vem som begärt hjälp och vad som måste kontrolleras för att rätt person ska beröras.","pitfall":"Kursen nämner lagen som exempel i identitetsfrågan. En hänvisning till handräckning ger inget allmänt stöd för ID-kontroll.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2"],"url":"https://data.riksdagen.se/dokument/sfs-1988-870.html","units":["l11","kontroll-vistelse"]},{"law":"LPT","name":"Lag (1991:1128) om psykiatrisk tvångsvård","ref":"47 §","title":"Handräckning vid psykiatrisk tvångsvård","rule":"Paragrafen reglerar bland annat vissa omhändertaganden och hjälp på begäran vid psykiatrisk tvångsvård. För en begäran ska förutsättningarna i lagen prövas.","apply":"Identifiera den bakomliggande åtgärden, vem som begärt hjälp och vad som måste kontrolleras för att rätt person ska beröras.","pitfall":"Kursen nämner lagen som exempel i identitetsfrågan. En hänvisning till handräckning ger inget allmänt stöd för ID-kontroll.","sources":["Trafikjuridik 4, bild 33","Polisjuridik med kommentarer (2021), avsnitt 2"],"url":"https://data.riksdagen.se/dokument/sfs-1991-1128.html","units":["l11","kontroll-vistelse"]},{"law":"Ordningslagen","name":"Ordningslag (1993:1617)","ref":"2 kap. 22, 22 a och 23 §§","title":"Sammankomst och offentlig tillställning","rule":"Ordningslagen reglerar när en allmän sammankomst eller offentlig tillställning får ställas in eller upplösas. Ett sådant beslut kan aktualisera PL 13 b §.","apply":"Ta först reda på vilken slags sammankomst det gäller och om ett relevant myndighetsbeslut har fattats.","pitfall":"En åskådarskara vid en trafikolycka är inte automatiskt en allmän sammankomst i lagens mening.","sources":["Föreläsning ordningsbot, bild 2","Polisjuridik med kommentarer (2021), avsnitt 1.3 (PL 13 b §)"],"url":"https://data.riksdagen.se/dokument/sfs-1993-1617.html","units":["l6","l11"]},{"law":"TKL","name":"Terrängkörningslag (1975:1313)","ref":"1, 3 och 4 §§","title":"Fyrhjuling på barmark och skoter på snö","rule":"För andra ändamål än jord- eller skogsbruk förbjuder 1 § motordrivna fordon i terräng på barmark. På snötäckt jordbruksmark och snötäckt skogsmark med plant- eller ungskog gäller förbudet om det inte är uppenbart att körningen kan ske utan risk för skada på marken respektive skogen. Ytterligare områdesförbud kan gälla.","apply":"Anteckna var spåren gick, markens skick och syftet med färden. Vid en skotertur över en frusen sjö behöver du också kontrollera lokala bestämmelser.","pitfall":"Ägarens samtycke ersätter inget lagstadgat undantag. För ansvar enligt 4 § krävs uppsåt eller oaktsamhet. Ringa gärningar är straffria.","sources":["Trafikjuridik 4, bild 18–22","Tentamensinformation, exempel på lagtext"],"url":"https://data.riksdagen.se/dokument/sfs-1975-1313.html","units":["l13"]},{"law":"TKF","name":"Terrängkörningsförordning (1978:594)","ref":"1 samt 4–8 §§","title":"Undantag och allmän skoterled","rule":"Förordningen preciserar undantag för bland annat räddningsinsatser, ledningsarbeten och hämtning av vissa fällda djur. Den reglerar också ungskog, regleringsområden och allmänna skoterleder.","apply":"Vid hämtning efter jakt: vilken art har fällts och till vilken bilväg kör man? Regeln nämner björn, älg, hjort och vildsvin och den lämpligast belägna bilvägen.","pitfall":"En yrkestitel eller pågående jakt räcker inte för att alla körningar ska omfattas. För tjänsteärendena i 1 § första stycket ska annat lämpligt sätt saknas.","sources":["Trafikjuridik 4, bild 20–22"],"url":"https://data.riksdagen.se/dokument/sfs-1978-594.html","units":["l13"]},{"law":"KlampL","name":"Klampningslag (2024:1089)","ref":"1 och 4–8 §§","title":"När får fortsatt färd förbjudas?","rule":"Det behövs en hänvisning till klampningslagen i ett annat regelverk och en tillämplig grund i lagen. I 6 § avses en trafikfarlig förare, i 7 § brister i fordonet eller dess utrustning.","apply":"En förare som har brutit mot kör- och vilotidsreglerna omfattas av 6 § om fortsatt färd medför påtaglig trafikfara. För 7 § ska fordonsbristen medföra sådan fara eller annan väsentlig olägenhet. Motivera och ompröva förbudet när förhållandena ändras.","pitfall":"Vecka 7 hänvisar till 6 § för osäkrad last. Lastens skick visar inte i sig att föraren överträtt regler om vila eller om förmåga att köra säkert.","sources":["Trafikjuridik 3, bild 29–30","Trafikjuridik 4, bild 9–10","Vecka 7, facit till case 9"],"url":"https://data.riksdagen.se/dokument/sfs-2024-1089.html","units":["l7","l10","l11"]},{"law":"KlampL","name":"Klampningslag (2024:1089)","ref":"10–14 och 23 §§","title":"Från förbud till omhändertagande eller klampning","rule":"Efter ett förbud som kan antas bli åsidosatt får bland annat fordonsnycklar omhändertas enligt 10 §. Omhändertagandet ska genast anmälas till förman. Villkoren för klampning och beslutande myndighet finns i 12 §.","apply":"Redovisa beslutet om färdförbud, omständigheterna bakom nästa åtgärd och hur länge den bestod. Pröva försvarlighet enligt 13 § och dokumentera åtgärden enligt 23 §.","pitfall":"11 § om visitation och genomsökning förutsätter ett förbud enligt 6 eller 7 § och att egendomen inte är åtkomlig på annat sätt. För passagerare krävs synnerliga skäl.","sources":["Trafikjuridik 3, bild 31","Trafikjuridik 4, bild 11"],"url":"https://data.riksdagen.se/dokument/sfs-2024-1089.html","units":["l10","l11"]},{"law":"KlampF","name":"Klampningsförordning (2024:1194)","ref":"2 §","title":"Hitta hänvisningen till klampningslagen","rule":"Förordningen samlar hänvisningar till författningar där fortsatt färd får hindras enligt klampningslagen.","apply":"Slå upp 2 §, följ hänvisningen för den aktuella överträdelsen och pröva sedan vilken grund i klampningslagen som passar.","pitfall":"En träff i uppräkningen är en ingång. Den visar inte ensam att villkoren i det enskilda fallet är uppfyllda.","sources":["Fördjupning till Trafikjuridik 3, bild 29–31"],"url":"https://data.riksdagen.se/dokument/sfs-2024-1194.html","units":["l10","l7"]},{"law":"LFA","name":"Lag (1976:206) om felparkeringsavgift","ref":"1–2 och 4–5 §§","title":"Parkeringsanmärkning och betalningsansvar","rule":"När avgiftsreglerna är tillämpliga får polisman eller behörig parkeringsvakt meddela parkeringsanmärkning. Fordonets ägare ansvarar normalt för betalningen.","apply":"Ange plats, tid och den föreskrift om stannande eller parkering som överträtts. Kontrollera att platsen och överträdelsen omfattas.","pitfall":"Parkeringsanmärkningen är en avgift. Ett erkännande enligt ordningsbotsförfarandet krävs inte.","sources":["Trafikjuridik 1, bild 7–8","Trafikjuridik 3, bild 6","Tentamensinformation, exempel på lagtext"],"url":"https://data.riksdagen.se/dokument/sfs-1976-206.html","units":["l6","l7"]},{"law":"FFA","name":"Förordning (1976:1128) om felparkeringsavgift","ref":"1 §","title":"Vilka parkeringsöverträdelser ger avgift?","rule":"Här finns de bestämmelser i trafikförordningen och de lokala föreskrifter som omfattas av felparkeringsavgift.","apply":"Om bilen står nära en korsning: mät och dokumentera placeringen, identifiera trafikregeln och leta upp den i 1 §.","pitfall":"Ett vardagligt uttryck som ”felparkerad” räcker inte för att avgöra vilket förfarande som gäller.","sources":["Trafikjuridik 1, bild 7–8","Trafikjuridik 3, bild 6","Tentamensinformation, exempel på lagtext"],"url":"https://data.riksdagen.se/dokument/sfs-1976-1128.html","units":["l6","l7"]},{"law":"VMF","name":"Vägmärkesförordning (2007:90)","ref":"2–4 kap., särskilt 3 kap. 6 §","title":"Fast gult, blinkande gult och rött","rule":"Fast gult betyder stanna, med undantag för den som kommit så långt att fordonet inte kan stannas utan fara. Blinkande gult påkallar särskild försiktighet.","apply":"Anteckna färgen när fordonet passerade stopplinjen eller, där linje saknas, signalen. Vid blinkande gult identifieras även vägmärken, markeringar och väjningsregler.","pitfall":"Att trafikljuset är gult när bilen redan befinner sig i korsningen visar inte vilken signal föraren passerade.","sources":["Trafikjuridik 1, bild 7–8","Vecka 6, facit till case 4","Vecka 7, facit till case 2 och 5"],"url":"https://data.riksdagen.se/dokument/sfs-2007-90.html","units":["l1","l6","l7"]},{"law":"LTF / STFS","name":"Förordning (2007:231) om elektroniskt kungörande av vissa trafikföreskrifter","ref":"1–3 §§","title":"Hitta den lokala regeln för rätt gata och datum","rule":"Lokala trafikföreskrifter enligt 10 kap. trafikförordningen kan reglera bland annat hastighet, parkering och färdväg. Föreskrifterna kungörs elektroniskt i Svensk trafikföreskriftssamling.","apply":"Sök i STFS på kommun, gatu-/vägnamn och datum. Läs beslut och karta, kontrollera körriktning, giltighet och eventuella undantag. Jämför med utmärkningen på platsen.","pitfall":"Ange föreskriftens eget nummer om den ligger till grund för din bedömning. Databasen innehåller även upphävda regler.","sources":["Trafikjuridik 3, bild 9"],"url":"https://rdt.transportstyrelsen.se/rdt/AF06_Search.aspx?UseStfs=1","units":["l1","l7"]},{"law":"TTF","name":"Taxitrafikförordning (2012:238)","ref":"3 kap. 13 §","title":"Legitimationen i taxibilen","rule":"Vid taxitrafik ska giltig taxiförarlegitimation medföras, vara synlig för passagerarna och visas för polisman eller bilinspektör på begäran.","apply":"Skilj på tre frågor: giltig behörighet, medhavd legitimation och synlighet för passageraren. Anteckna vilket förhållande som faktiskt observerats.","pitfall":"Samma kapitel och paragraf i taxitrafiklagen handlar om en annan fråga. Hänvisa här till förordningen.","sources":["Nationella strategier, bild 34"],"url":"https://data.riksdagen.se/dokument/sfs-2012-238.html","units":["l11","l14"]},{"law":"TTF","name":"Taxitrafikförordning (2012:238)","ref":"5 kap. 1–3 §§","title":"Taxameter eller särskild utrustning","rule":"En taxibil ska ha godkänd taxameterutrustning eller särskild utrustning för taxifordon. En taxameter ska besiktas senast ett år efter installationen eller senaste besiktningen.","apply":"Identifiera utrustningsformen. Vid taxameter: jämför kontrollrapportens datum med den aktuella färden.","pitfall":"Bild 35 hänvisar till 8 kap. 1 §, som ger rätt att utfärda föreskrifter. Tidsfristen står i 5 kap. 3 §.","sources":["Nationella strategier, bild 35"],"url":"https://data.riksdagen.se/dokument/sfs-2012-238.html","units":["l11","l14"]},{"law":"TTL","name":"Taxitrafiklag (2012:211)","ref":"2 kap. 17–21 §§","title":"Vad ska taxikunden veta om priset?","rule":"Vid taxametertrafik ska kunden kunna få kännedom om taxan före färden. Taxans utformning, när en högsta prisuppgift behövs och när den lämnas regleras här.","apply":"Fråga vad kunden kunde se innan resan började, om fast pris avtalats och vad jämförpriset var. Skilj jämförpris från det slutliga priset för resan.","pitfall":"Tröskeln för särskild prisuppgift beror på årets prisbasbelopp. TTF 8 kap. innehåller bemyndiganden.","sources":["Nationella strategier, bild 35"],"url":"https://data.riksdagen.se/dokument/sfs-2012-211.html","units":["l11","l14"]},{"law":"TTL","name":"Taxitrafiklag (2012:211)","ref":"5 kap. 7–8 §§","title":"När får taxiskylten tas om hand?","rule":"8 § anger särskilda grunder, bland annat användning utan tillstånd, vissa kör- eller användningsförbud och brister i föreskriven utrustning. Polisman eller bilinspektör får besluta.","apply":"Matcha omständigheten med rätt punkt i 8 §. Om frågan gäller att hindra fortsatt färd, läs även 7 § och klampningslagen.","pitfall":"En godtycklig taxiförseelse ger inte stöd att ta hand om skylten. Specificera vilket körförbud det gäller.","sources":["Nationella strategier, bild 35"],"url":"https://data.riksdagen.se/dokument/sfs-2012-211.html","units":["l11","l14"]},{"law":"Vilotidsförordningen","name":"Förordning (1994:1297) om vilotider vid vissa vägtransporter inom landet","ref":"1–7 och 12 §§","title":"Tidbok för inrikes budbil och taxi","rule":"Reglerna omfattar vissa inrikes transporter i förvärvsverksamhet med svenskregistrerade fordon. För godstransporter gäller bland annat en viktgräns på 3,5 ton inklusive släp och undantag för posttransporter. 3 § anger dygnsvilan, 5–6 §§ reglerar anteckningar och 7 § kräver att tidboken medförs och visas på begäran. Föraransvaret finns i 12 §.","apply":"Vid budbilskontrollen: ta reda på transportslag, vikt, sträcka och om EU-regler eller undantag gäller. Pröva sedan vad föraren antecknat och om handlingen kunde visas.","pitfall":"En glömd tidbok styrker inte i sig att föraren också har fått för lite vila. De två frågorna behöver olika bevisning.","sources":["Nationella strategier, bild 34","Vecka 7, facit till case 2"],"url":"https://data.riksdagen.se/dokument/sfs-1994-1297.html","units":["l6","l11","l14"]},{"law":"Kör- och vilotidsförordningen","name":"Förordning (2004:865) om kör- och vilotider samt färdskrivare, m.m.","ref":"9 kap. 12 §","title":"Samma körning och konkurrerande ansvar","rule":"Paragrafen anger när ansvar enligt 9 kap. 1–6 §§ faller bort, bland annat om straff kan dömas ut enligt brottsbalken eller trafikbrottslagen.","apply":"Om samma brist på vila ingår i vårdslöshet i trafik, avgränsa exakt vilket handlande som prövas och jämför med konkurrensregeln.","pitfall":"RäV 2023:18 anger äldre 9 kap. 10 §. I den gällande lydelsen finns subsidiariteten i 9 kap. 12 §.","sources":["RäV 2023:18, avsnitt 5.4, s. 27"],"url":"https://data.riksdagen.se/dokument/sfs-2004-865.html","units":["l2","l14"]},{"law":"EU 561/2006","name":"Europaparlamentets och rådets förordning (EG) nr 561/2006 om harmonisering av viss sociallagstiftning på vägtransportområdet","ref":"Art. 2–3 och 6–8","title":"Körtid, rast och vila vid vägtransport","rule":"För de transporter som omfattas skiljer förordningen mellan körtid, rast och viloperioder. Fordon, transportens art och undantag avgör om reglerna gäller.","apply":"Rita en tidslinje över körning, annat arbete, rast och vila. Jämför först transporten med artikel 2 och 3, sedan tidslinjen med artikel 6–8.","pitfall":"Ett avbrott för lastning är arbete och kan inte utan vidare räknas som rast.","sources":["Fördjupning till Nationella strategier, bild 4","RäV 2023:18, avsnitt 5.4"],"url":"https://eur-lex.europa.eu/legal-content/SV/TXT/?uri=CELEX:32006R0561","units":["l11","l14"]},{"law":"EU 165/2014","name":"Europaparlamentets och rådets förordning (EU) nr 165/2014 om färdskrivare vid vägtransporter","ref":"Art. 3 och 34","title":"Vad registrerar en färdskrivare?","rule":"Förordningen anger vilka fordon som omfattas och hur föraren ska använda diagramblad eller förarkort och registrera aktivitet.","apply":"Identifiera först reglerna för just transporten. Jämför sedan registrerad körning, annat arbete och vila med vad som faktiskt hänt.","pitfall":"Ett förarkort till färdskrivaren och den personliga tidboken i den svenska vilotidsförordningen hör till olika regelverk.","sources":["Fördjupning till Nationella strategier, bild 4","RäV 2023:18, avsnitt 5.4"],"url":"https://eur-lex.europa.eu/legal-content/SV/TXT/?uri=CELEX:32014R0165","units":["l11","l14"]},{"law":"YTL","name":"Yrkestrafiklag (2012:210)","ref":"2 kap. 1 § och 5 kap. 1 §","title":"Vem har tillstånd att bedriva trafiken?","rule":"Den som bedriver yrkesmässig trafik behöver relevant gemenskapstillstånd eller yrkestrafiktillstånd. Lagen innehåller straffansvar för uppsåtlig otillåten verksamhet.","apply":"Utred vem som driver verksamheten och vilken gods- eller persontransport som utförts. Slå upp de regler som gäller för just den verksamheten.","pitfall":"Förarens körkort och transportföretagets tillstånd besvarar två olika frågor.","sources":["Fördjupning till Nationella strategier, bild 4"],"url":"https://data.riksdagen.se/dokument/sfs-2012-210.html","units":["l11","l14"]},{"law":"YTF","name":"Yrkestrafikförordning (2012:237)","ref":"1 kap. 1 § och 4 kap. 2 §","title":"Hur knyts ett fordon till trafiktillståndet?","rule":"Förordningen kompletterar yrkestrafiklagen och EU:s regler om tillträde till yrket. Den innehåller bland annat regler om anmälan av fordon.","apply":"Läs först lagen om tillstånd och gå sedan till reglerna om det aktuella fordonet i förordningen.","pitfall":"Ett företagstillstånd visar inte ensamt vilka fordon som är anmälda för användning i verksamheten.","sources":["Fördjupning till Nationella strategier, bild 4"],"url":"https://data.riksdagen.se/dokument/sfs-2012-237.html","units":["l11","l14"]},{"law":"YKB","name":"Lag (2007:1157) om yrkesförarkompetens","ref":"2 och 6 kap.","title":"När behövs yrkeskompetensbevis?","rule":"Lagen omfattar förare vid vissa gods- och persontransporter med tunga fordon. Den reglerar grundkompetens, fortbildning och yrkeskompetensbevis. I 2 kap. finns tillämpningsområde och undantag.","apply":"Börja med fordonets behörighetsklass och transportens syfte. Pröva eventuellt undantag innan du bedömer beviset.","pitfall":"Körkortsbehörighet, yrkeskompetensbevis och företagets trafiktillstånd gäller olika krav.","sources":["Trafikjuridik 4, bild 26"],"url":"https://data.riksdagen.se/dokument/sfs-2007-1157.html","units":["l8","l14"]},{"law":"LFG","name":"Lag (2006:263) om transport av farligt gods","ref":"2 §","title":"Vem ansvarar för skyddsåtgärderna?","rule":"Skyldigheten att förebygga skador omfattar både den som utför transporten och den som lämnar godset till transport.","apply":"Ange vilket gods som avses, vilken roll personen har och vilken konkret säkerhetsregel som påstås vara överträdd. Använd rätt transportföreskrift för godset.","pitfall":"En misstanke om farligt gods ger inte ensam svar på vare sig transportvillkoren eller vem som ansvarar.","sources":["Trafikjuridik 1, bild 11","FAP 261-1, 5–6 §§"],"url":"https://data.riksdagen.se/dokument/sfs-2006-263.html","units":["l11","l14"]},{"law":"FFG","name":"Förordning (2006:311) om transport av farligt gods","ref":"10 §","title":"Tillsyn över farligt gods på väg","rule":"Förordningen delar upp tillsynen mellan flera myndigheter. Polismyndigheten ansvarar för landtransporter med undantag för järnväg inom det angivna området.","apply":"Identifiera transportsättet och kontrollera om någon särskild tillsynsmyndighet har ansvar för godset eller momentet.","pitfall":"Myndighetens ansvarsområde och den enskilda kontrollantens kompetenskrav är separata frågor.","sources":["Trafikjuridik 1, bild 11","FAP 261-1, 5–6 §§"],"url":"https://data.riksdagen.se/dokument/sfs-2006-311.html","units":["l11","l14"]},{"law":"FAP 338-1","name":"Polismyndighetens föreskrifter och allmänna råd om Polismyndighetens tillsyn över transporter av farligt gods (PMFS 2020:10, FAP 338-1)","ref":"5 §","title":"Särskild utbildning för farligt gods","rule":"Föreskriften ställer utbildningskrav på den som utför tillsyn över väg- och terrängtransporter av farligt gods.","apply":"Vid övningskontrollen: förklara varför en specialist behöver bedöma transportens klassning och vad som faktiskt har dokumenterats.","pitfall":"Trafikjuridik 1 använder samma FAP-nummer även för körkort. FAP 338-1 gäller farligt gods.","sources":["Trafikjuridik 1, bild 11–12"],"url":"https://polisen.se/siteassets/forfattningssamling/fap-nummer/fap338-01-pmfs2020-10/","units":["l11","l14"]},{"law":"FAP 331-2","name":"Rikspolisstyrelsens föreskrifter och allmänna råd om hastighetsövervakning på väg och i terräng med laserhastighetsmätare (RPSFS 2003:6, FAP 331-2)","ref":"Översikt","title":"Behörighet vid hastighetsmätning med laser","rule":"Föreskrifterna anger krav på instrument, kontroll och utbildning för den som gör mätningen.","apply":"I en bevisfråga: skilj en egen uppskattning av hastigheten från ett mätresultat som kan knytas till fordon, plats och behörig mätkontrollant.","pitfall":"Ett visat tal ensamt visar inte att rätt fordon mättes eller att kraven på kontroll var uppfyllda.","sources":["Trafikjuridik 1, bild 11–12"],"url":"https://polisen.se/siteassets/forfattningssamling/fap-nummer/fap331-02-rpsfs2003-06/","units":["l1","l11"]},{"law":"Strada","name":"Lag (2021:319) om Transportstyrelsens olycksdatabas","ref":"1 och 11 §§","title":"Vilka olyckor ska rapporteras till Strada?","rule":"Polismyndigheten ska lämna uppgifter om kända vägtrafikolyckor, olyckor med terrängmotorfordon och olyckor med fritidsfartyg som har lett till personskada eller död.","apply":"I kursens fall: fastställ olyckstypen och om någon skadats. Lägg in uppgifterna enligt kursens Samla-rutin och bedöm separat om en brottsutredning behövs.","pitfall":"Rapportskyldigheten för en personskadeolycka är inte beroende av att en förare kan misstänkas för brott.","sources":["Trafikolycka i Samla, s. 5–6 och 9"],"url":"https://data.riksdagen.se/dokument/sfs-2021-319.html","units":["l12"]},{"law":"Vägtransportledarlagen","name":"Lag (2004:1167) om vägtransportledare","ref":"2–4 och 7 §§","title":"Vem får ge anvisningar vid eskort?","rule":"En förordnad vägtransportledare får ge trafikanvisningar i samband med en vägtransport som ska utföras med eskort. Vägtransportledaren lyder under Polismyndigheten.","apply":"Fastställ att ett eskortuppdrag enligt 2 § pågår. Pröva sedan det aktuella undantaget i 11 kap. trafikförordningen.","pitfall":"Ett följefordon vid en transport innebär inte i sig att föraren är förordnad vägtransportledare.","sources":["Trafikjuridik 3, avsnitten om eskortkörning och stannande vid eskort"],"url":"https://data.riksdagen.se/dokument/sfs-2004-1167.html","units":["l7"]},{"law":"Väglagen","name":"Väglag (1971:948)","ref":"41 §","title":"Föreskrift om en enskild väg vid anslutning","rule":"I vissa fall kan väghållningsmyndigheten besluta att motorfordonstrafik förbjuds eller begränsas på en enskild väg i samband med dess anslutning.","apply":"Identifiera den faktiska föreskriften. Om frågan gäller ett undantag för tjänstekörning, pröva rekvisiten i 11 kap. 1 § trafikförordningen.","pitfall":"En enskild väg och terräng är två skilda kategorier. Vem som äger marken avgör inte ensam vilken regel som gäller.","sources":["Trafikjuridik 3, bild 12"],"url":"https://data.riksdagen.se/dokument/sfs-1971-948.html","units":["l7","l13"]},{"law":"Parkeringsövervakning","name":"Lag (1987:24) om kommunal parkeringsövervakning m.m.","ref":"2 §","title":"Kommunal parkeringsövervakning","rule":"En kommun får besluta att själv svara för parkeringsövervakning när det behövs parkeringsvakter.","apply":"Vid en fråga om parkeringsvaktens tjänstefordon, slå upp de särskilda villkoren för stannande eller parkering i 11 kap. 9 § trafikförordningen.","pitfall":"Parkeringsövervakning som arbetsuppgift innebär ingen generell befrielse från trafikregler.","sources":["Trafikjuridik 3, avsnittet om 11 kap. 9 § TrF"],"url":"https://data.riksdagen.se/dokument/sfs-1987-24.html","units":["l7"]},{"law":"LSO","name":"Lag (2003:778) om skydd mot olyckor","ref":"1 kap. 2 §","title":"När räknas insatsen som räddningstjänst?","rule":"Lagen definierar räddningstjänst som statliga eller kommunala räddningsinsatser vid olyckor eller överhängande fara för olyckor enligt angivna förutsättningar.","apply":"Om en uppgift gäller ett undantag för körning vid räddningstjänst: koppla insatsen till definitionen och pröva sedan villkoren i det aktuella trafiklagrummet.","pitfall":"Markeringen på fordonet avgör inte på egen hand om ett visst uppdrag omfattas.","sources":["Trafikjuridik 3, avsnittet om 11 kap. 10 a § TrF"],"url":"https://data.riksdagen.se/dokument/sfs-2003-778.html","units":["l7","l12"]},{"law":"Säpos instruktion","name":"Förordning (2022:1719) med instruktion för Säkerhetspolisen","ref":"5 §","title":"Personskydd som hänvisning i trafikförordningen","rule":"Instruktionen beskriver Säkerhetspolisens personskyddsuppdrag. Trafikförordningens undantag hänvisar i vissa fall till skyddsåtgärder inom den verksamheten.","apply":"Identifiera den trafikregel som berörs och om uppdraget gäller en skyddsåtgärd inom den verksamhet som paragrafen avser.","pitfall":"En anställning vid Säkerhetspolisen visar inte ensam att villkoren i varje undantag är uppfyllda.","sources":["Trafikjuridik 3, bild 11–12 och avsnitten om undantag i 11 kap. TrF"],"url":"https://data.riksdagen.se/dokument/sfs-2022-1719.html","units":["l7"]},{"law":"Immunitetslagen","name":"Lag (1976:661) om immunitet och privilegier i vissa fall","ref":"2 § och Wienkonventionen om diplomatiska förbindelser","title":"Vad säger en diplomatskylt om immunitet?","rule":"Svensk lag hänvisar till Wienkonventionens immuniteter. Artikel 22.3 skyddar beskickningens transportmedel mot bland annat genomsökning och beslag. Artiklarna 29 och 31 behandlar den diplomatiska företrädarens personliga skydd.","apply":"Dela upp frågan i vem personen är, om fordonet tillhör beskickningen och vilken konkret åtgärd som övervägs.","pitfall":"Bild 40 uttrycker en generell stoppregel. Skylten visar inte ensam omfattningen av en viss persons eller ett visst fordons immunitet.","sources":["Nationella strategier, bild 40"],"url":"https://data.riksdagen.se/dokument/sfs-1976-661.html","units":["l11","l14"]},{"law":"Automatiserade fordon","name":"Förordning (2017:309) om försöksverksamhet med automatiserade fordon","ref":"7 §","title":"Vem är förare under en automatiserad försökskörning?","rule":"Under försöksverksamheten räknas den som aktiverat den automatiserade körningen som förare tills funktionen inaktiveras. För bland annat personbil krävs en förare i eller utanför fordonet.","apply":"Kontrollera om färden ingår i en tillståndspliktig försöksverksamhet, vilket fordon som används och vem som aktiverade systemet.","pitfall":"Att en vanlig bil har förarassistans gör den inte automatiskt till ett försöksfordon enligt förordningen.","sources":["RäV 2023:18, avsnitt 2.2.3"],"url":"https://data.riksdagen.se/dokument/sfs-2017-309.html","units":["l1","l2"]},{"law":"Förverkandeförfarandelagen","name":"Lag (2024:782) om förfarandet vid förverkande av egendom och åläggande av företagsbot","ref":"3–4 kap. och övergångsbestämmelserna","title":"Hur prövas ett yrkande om förverkande?","rule":"Lagen reglerar bland annat när brottsbekämpande myndigheter får besluta och hur en fråga om förverkande i vissa fall prövas i domstol. Den ersatte lag (1986:1009) om förfarandet i vissa fall vid förverkande m.m. den 8 november 2024.","apply":"Vid ett fordon som påstås tillhöra någon annan än föraren: utred ägandet och vem som berörs av yrkandet. Håll isär beslagsfrågan, grunden i TBL och förfarandet vid prövningen.","pitfall":"Kursens vägledning återger den äldre procedurlagen. Kontrollera dagens beslutsregler innan ett äldre exempel används på ett nytt fall.","sources":["Rättslig vägledning om 7 § trafikbrottslagen, avsnitt 2.3.2 och genomgången av tredje mans äganderätt"],"url":"https://data.riksdagen.se/dokument/sfs-2024-782.html","units":["l5"]},{"law":"Äldre rattfylleribefogenheter","name":"Lag (2008:322) om Tullverkets och Kustbevakningens befogenheter att ingripa mot rattfylleribrott","ref":"Äldre 9–11 §§, upphävda","title":"Historik: hänvisningen i 2023 års vägledning","rule":"Kursens återgivning av 7 § TBL hänvisar till den äldre gemensamma lagen för Tullverket och Kustbevakningen. Den upphörde den 7 november 2024.","apply":"I ett nytt fall: använd 10 kap. 1–3 §§ tullbefogenhetslagen för tulltjänsteman och 3 kap. 16 a–16 b §§ kustbevakningslagen för kustbevakningstjänsteman. För polisman, läs 24 a–24 d §§ polislagen.","pitfall":"Ett tillfälligt omhändertagande för att hindra rattfylleri och ett slutligt förverkande enligt 7 § TBL har olika syften och förutsättningar.","sources":["RäV 2023:4, s. 4, lagtexten före avsnitt 2.1"],"url":"https://data.riksdagen.se/dokument/sfs-2008-322.html","units":["l4","l5"]},{"law":"Tullbefogenhetslagen","name":"Tullbefogenhetslag (2024:710)","ref":"10 kap. 1–3 §§","title":"Tulltjänstemannens omhändertagande vid risk för rattfylleri","rule":"Vid misstanke om rattfylleri eller grovt rattfylleri ger 1 § tulltjänstemannen samma befogenhet som en polisman enligt 24 a § polislagen. Ett beslut om omhändertagande ska skyndsamt anmälas till Polismyndigheten, som genast prövar om det ska bestå.","apply":"Ange vad som grundar misstanken och vad som visar risk för fortsatt rattfylleribrott. Identifiera vem som fattar det första beslutet och vem som prövar fortsättningen.","pitfall":"Att det finns bevis för en tidigare körning visar inte ensamt att ett förebyggande omhändertagande behövs nu.","sources":["RäV 2023:4, s. 4, lagtexten före avsnitt 2.1"],"url":"https://data.riksdagen.se/dokument/sfs-2024-710.html","units":["l4","l5"]},{"law":"Kustbevakningslagen","name":"Kustbevakningslag (2019:32)","ref":"3 kap. 16 a–16 b §§","title":"Kustbevakningstjänstemannens omhändertagande","rule":"Vid misstanke om rattfylleri eller grovt rattfylleri enligt TBL hänvisar 16 a § till befogenheterna i 24 a § polislagen. I 16 b § regleras det fortsatta förfarandet genom hänvisning till polislagen.","apply":"Knyt åtgärden till rätt tjänsteman, ett misstänkt trafikbrott och de omständigheter som ger anledning att förebygga ytterligare körning.","pitfall":"Brotten som anges här är rattfylleri enligt TBL. Ett fall om sjöfylleri behöver prövas mot andra bestämmelser.","sources":["RäV 2023:4, s. 4, lagtexten före avsnitt 2.1"],"url":"https://data.riksdagen.se/dokument/sfs-2019-32.html","units":["l4","l5"]},{"law":"Militärtrafikförordningen","name":"Militärtrafikförordning (2009:212)","ref":"3 och 5 kap. samt övergångsbestämmelserna","title":"Militära vägtrafikkungörelsen (1974:97) i äldre fordonsföreskrifter","rule":"Kursens A-traktorföreskrifter hänvisar till militära vägtrafikkungörelsen (1974:97). Den upphörde den 29 april 2009. Militärtrafikförordningen reglerar nu bland annat fordonsutrustning och det militära fordonsregistret.","apply":"Kontrollera vilken myndighet som brukar fordonet, hur det är registrerat och vad specialbestämmelsen faktiskt undantar. För övningens vanliga privatägda A-traktor fortsätter du med de ordinarie fordonskraven.","pitfall":"Den gamla hänvisningen upphäver inte i sig varje äldre föreskrift. Läs övergångsbestämmelserna och kontrollera den aktuella lydelsen.","sources":["VVFS 2003:19, 6 kap. 1 §, undantag för fordon som brukas av Försvarsmakten m.fl."],"url":"https://data.riksdagen.se/dokument/sfs-2009-212.html","units":["l9","l10"]}];
